window.CBT_DATA=window.CBT_DATA||{};window.CBT_DATA["written/2023-3"]={"track":"written","round":"2023-3","questions":[{"id":"written-2023-3-1","no":1,"unit":"소프트웨어 설계","q":"파이프 필터 형태의 소프트웨어 아키텍처에 관한 설명으로 옳은 것은?","choices":["노드와 간선으로 이루어진다.","계층 모델이라고도 불린다.","3개의 서브시스템(모델, 뷰, 제어)으로 이루어져 있다.","서브시스템이 입력 데이터를 받아 처리한 뒤 그 결과를 다음 서브시스템에 넘겨주는 과정이 반복된다."],"ans":4,"exp":{"concept":"파이프-필터(Pipe-Filter) 구조는 데이터가 파이프를 따라 흐르면서 여러 필터(처리 단계)를 차례로 거치는 아키텍처다. 각 필터는 입력을 받아 처리한 뒤 결과를 다음 필터에 넘긴다. 공장의 컨베이어 벨트에서 부품이 공정을 하나씩 거쳐 완성품이 되는 것과 비슷하다.","choices":[{"verdict":"오답","why":"노드와 간선으로 이루어진다는 것은 그래프(네트워크) 구조를 말하는 것으로, 파이프-필터 구조를 설명하는 특징이 아니다."},{"verdict":"오답","why":"계층 모델(Layered Model)은 시스템을 위아래 계층으로 나누어 각 계층이 바로 아래 계층의 서비스를 이용하는 별개의 아키텍처 스타일이다."},{"verdict":"오답","why":"모델, 뷰, 제어의 3개 서브시스템으로 나누는 것은 MVC(Model-View-Controller) 구조다."},{"verdict":"정답","why":"파이프-필터 구조의 정의 그대로다. 서브시스템(필터)이 입력 데이터를 처리해 결과를 다음 서브시스템으로 넘기는 과정이 반복된다."}],"keywords":[{"term":"파이프-필터 구조","desc":"데이터 스트림을 단계별 필터가 차례로 처리하는 구조. 예: 유닉스 쉘의 파이프(|)"},{"term":"계층 구조(Layered)","desc":"기능을 계층으로 나누고 각 계층은 인접 계층과만 상호작용하는 구조. 예: OSI 7계층"},{"term":"MVC 구조","desc":"모델(데이터), 뷰(화면), 컨트롤러(입력 처리)로 나눈 구조"},{"term":"클라이언트-서버 구조","desc":"서비스를 요청하는 클라이언트와 제공하는 서버로 나눈 구조"}],"memo":"파이프는 수도관이다. 물(데이터)이 관을 따라 흐르며 필터를 차례로 통과한다고 떠올리면 된다."}},{"id":"written-2023-3-2","no":2,"unit":"소프트웨어 설계","q":"UML 확장 모델에서 스테레오 타입 객체를 나타낼 때 쓰는 기호로 옳은 것은?","choices":["{{ }}","&lt;&lt; &gt;&gt;","(( ))","[[ ]]"],"ans":2,"exp":{"concept":"UML의 스테레오타입(Stereotype)은 UML 기본 요소에 새로운 의미를 덧붙여 확장할 때 쓰는 표기다. 길러멧(Guillemet)이라 부르는 겹화살괄호 << >> 안에 이름을 적는다. 예를 들어 <<interface>>, <<include>>, <<extend>>처럼 쓴다.","choices":[{"verdict":"오답","why":"중괄호 { }는 UML에서 제약 조건(Constraint)을 적을 때 쓰는 기호이며, 겹중괄호는 스테레오타입 표기가 아니다."},{"verdict":"정답","why":"스테레오타입은 << >>(길러멧) 안에 이름을 적어 표시한다. 예: <<interface>>, <<include>>."},{"verdict":"오답","why":"겹소괄호 (( ))는 UML 스테레오타입 표기로 쓰이지 않는다."},{"verdict":"오답","why":"겹대괄호 [[ ]]는 UML 스테레오타입 표기로 쓰이지 않는다. 대괄호 [ ]는 상태 다이어그램 등에서 가드 조건을 적을 때 쓴다."}],"keywords":[{"term":"스테레오타입(Stereotype)","desc":"UML 요소에 의미를 확장하는 표기, << >> 안에 이름을 쓴다"},{"term":"길러멧(Guillemet)","desc":"스테레오타입을 감싸는 겹화살괄호 << >>"},{"term":"제약 조건(Constraint)","desc":"UML 요소에 조건을 붙이는 표기, { } 안에 쓴다"},{"term":"<<include>>, <<extend>>","desc":"유스케이스 다이어그램에서 포함·확장 관계를 나타내는 대표적인 스테레오타입"}],"memo":"<<include>>, <<extend>>를 떠올리면 스테레오타입 기호가 << >>라는 것이 바로 생각난다."}},{"id":"written-2023-3-3","no":3,"unit":"소프트웨어 설계","q":"CASE(Computer Aided Software Engineering)에 관한 설명 중 틀린 것은?","choices":["소프트웨어 유지보수를 간편하게 수행할 수 있게 한다.","자동화된 기법을 통하여 소프트웨어 품질을 향상시킨다.","소프트웨어 모듈의 재사용성을 향상시킨다.","소프트웨어 사용자에게 사용 방법을 신속하게 숙지시키기 위해 사용된다."],"ans":4,"exp":{"concept":"CASE(Computer Aided Software Engineering)는 소프트웨어 개발 과정(분석, 설계, 구현, 유지보수)의 일부 또는 전체를 컴퓨터 도구로 자동화하는 것이다. 개발자가 쓰는 도구이므로 목적은 생산성, 품질, 재사용성, 유지보수 편의 향상이다. 완성된 소프트웨어 사용자에게 사용법을 가르치는 것과는 관계가 없다.","choices":[{"verdict":"오답","why":"CASE 도구는 문서와 설계 정보를 일관되게 관리하므로 유지보수를 쉽게 해 준다. 맞는 설명이다."},{"verdict":"오답","why":"자동화된 기법으로 오류를 줄이고 표준화를 돕기 때문에 소프트웨어 품질이 향상된다. 맞는 설명이다."},{"verdict":"오답","why":"설계 정보와 모듈을 저장소에 관리해 재사용성을 높인다. 맞는 설명이다."},{"verdict":"정답","why":"사용자에게 사용 방법을 빨리 익히게 하는 것은 사용자 매뉴얼이나 교육의 역할이다. CASE는 개발자를 위한 개발 자동화 도구다."}],"keywords":[{"term":"CASE","desc":"소프트웨어 개발 과정을 컴퓨터 도구로 자동화하는 기술"},{"term":"상위 CASE(Upper CASE)","desc":"요구 분석과 설계 단계를 지원하는 도구"},{"term":"하위 CASE(Lower CASE)","desc":"코드 생성, 테스트 등 구현 단계를 지원하는 도구"},{"term":"통합 CASE(I-CASE)","desc":"상위와 하위 CASE를 통합해 전체 생명주기를 지원하는 도구"}],"memo":"CASE의 E는 Engineering, 즉 개발자를 돕는 도구다. '사용자 교육'이 나오면 오답이다."}},{"id":"written-2023-3-4","no":4,"unit":"소프트웨어 설계","q":"다음 내용이 설명하고 있는 객체지향 설계 원칙은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>클라이언트는 자신이 사용하지 않는 메소드와 의존관계를 맺어서는 안 된다.</li><li>클라이언트가 사용하지 않는 인터페이스로 인해 영향을 받아서는 안 된다.</li></ul></div>","choices":["개방 폐쇄의 원칙","리스코프 교체의 원칙","인터페이스 분리 원칙","단일 책임 원칙"],"ans":3,"exp":{"concept":"객체지향 설계 원칙 SOLID 가운데 인터페이스 분리 원칙(ISP)은 클라이언트가 자기가 쓰지 않는 메소드에 의존하지 않도록 큰 인터페이스를 작게 나누라는 원칙이다. 리모컨 하나에 버튼 100개를 다는 대신, 필요한 버튼만 있는 리모컨을 여러 개 만드는 것과 같다.","choices":[{"verdict":"오답","why":"개방 폐쇄의 원칙(OCP)은 확장에는 열려 있고 수정에는 닫혀 있어야 한다는 원칙이다."},{"verdict":"오답","why":"리스코프 교체의 원칙(LSP)은 자식 클래스는 언제나 부모 클래스를 대신할 수 있어야 한다는 원칙이다."},{"verdict":"정답","why":"인터페이스 분리 원칙(ISP)은 클라이언트가 사용하지 않는 메소드나 인터페이스에 의존하거나 영향을 받지 않아야 한다는 원칙으로, 지문 내용과 같다."},{"verdict":"오답","why":"단일 책임 원칙(SRP)은 하나의 클래스는 하나의 책임만 가져야 한다는 원칙이다."}],"keywords":[{"term":"SRP(단일 책임 원칙)","desc":"클래스는 하나의 책임만 가진다"},{"term":"OCP(개방 폐쇄 원칙)","desc":"확장에는 열려 있고 수정에는 닫혀 있다"},{"term":"LSP(리스코프 치환 원칙)","desc":"자식 클래스는 부모 클래스를 대체할 수 있어야 한다"},{"term":"ISP(인터페이스 분리 원칙)","desc":"사용하지 않는 인터페이스에 의존하지 않는다"},{"term":"DIP(의존 역전 원칙)","desc":"구체적인 것이 아니라 추상화에 의존한다"}],"memo":"SOLID 5원칙을 한 줄씩 외워 두고, '사용하지 않는 메소드/인터페이스'가 보이면 ISP를 고른다."}},{"id":"written-2023-3-5","no":5,"unit":"소프트웨어 설계","q":"공통 모듈의 명세 기법 가운데, 해당 기능이 일관되게 이해되고 한 가지로만 해석되도록 작성하는 원칙은 무엇인가?","choices":["명확성","독립성","상호작용성","내용성"],"ans":1,"exp":{"concept":"공통 모듈 명세 기법은 여러 곳에서 함께 쓰는 공통 모듈의 기능을 문서로 정할 때 지켜야 할 원칙이다. 정확성, 명확성, 완전성, 일관성, 추적성의 5가지가 있다. 이 중 누가 읽어도 같은 뜻으로, 한 가지로만 해석되도록 쓰는 것이 명확성이다.","choices":[{"verdict":"정답","why":"명확성(Clarity)은 해당 기능을 이해할 때 중의적으로 해석되지 않고 한 가지로만 해석되도록 작성하는 원칙이다."},{"verdict":"오답","why":"독립성은 공통 모듈 명세 기법의 5가지 원칙에 속하지 않는다. 모듈 설계에서 말하는 모듈 독립성(결합도는 낮게, 응집도는 높게)과 혼동하기 쉽다."},{"verdict":"오답","why":"상호작용성은 공통 모듈 명세 기법의 원칙이 아니다."},{"verdict":"오답","why":"내용성은 공통 모듈 명세 기법의 원칙이 아니다."}],"keywords":[{"term":"정확성(Correctness)","desc":"시스템 구현 시 해당 기능이 필요하다는 것을 알 수 있도록 정확히 작성"},{"term":"명확성(Clarity)","desc":"해당 기능을 한 가지로만 해석되도록 작성"},{"term":"완전성(Completeness)","desc":"시스템 구현에 필요한 모든 것을 빠짐없이 기술"},{"term":"일관성(Consistency)","desc":"공통 기능들 사이에 상호 충돌이 없도록 작성"},{"term":"추적성(Traceability)","desc":"기능에 대한 요구사항의 출처와 관련 시스템을 추적할 수 있도록 작성"}],"memo":"공통 모듈 명세 기법은 '정명완일추(정확성, 명확성, 완전성, 일관성, 추적성)'로 외운다."}},{"id":"written-2023-3-6","no":6,"unit":"소프트웨어 설계","q":"객체에 어떤 행위를 수행하도록 지시하는 명령을 무엇이라 하는가?","choices":["Class","Object","Instance","Message"],"ans":4,"exp":{"concept":"객체지향에서 객체들은 서로 메시지(Message)를 보내 일을 시킨다. 메시지를 받은 객체는 그에 맞는 메소드를 실행한다. 사람에게 '문 좀 닫아 줘'라고 부탁하면 그 사람이 문을 닫는 행동을 하는 것과 같다.","choices":[{"verdict":"오답","why":"클래스(Class)는 공통된 속성과 연산을 가진 객체들을 만들기 위한 틀이다."},{"verdict":"오답","why":"객체(Object)는 데이터와 그 데이터를 처리하는 함수를 함께 가진 독립된 실체다. 명령 자체가 아니다."},{"verdict":"오답","why":"인스턴스(Instance)는 클래스로부터 실제로 만들어진 개별 객체다."},{"verdict":"정답","why":"메시지(Message)는 객체에게 어떤 행위(메소드)를 수행하도록 지시하는 명령이나 요구다."}],"keywords":[{"term":"메시지(Message)","desc":"객체에게 행위를 지시하는 명령, 받은 객체는 메소드를 실행한다"},{"term":"메소드(Method)","desc":"객체가 수행하는 연산(함수)"},{"term":"클래스(Class)","desc":"공통 속성과 연산을 가진 객체를 정의한 틀"},{"term":"인스턴스(Instance)","desc":"클래스로 실제 생성된 객체"}],"memo":"메시지는 '보내는 것', 메소드는 '받아서 실행하는 것'으로 구분한다."}},{"id":"written-2023-3-7","no":7,"unit":"소프트웨어 설계","q":"럼바우(Rumbaugh) 분석 기법에서 정보 모델링이라고도 불리며, 시스템에 요구되는 객체를 찾아내 속성과 연산을 식별하고 객체들 사이의 관계를 규정해 다이어그램으로 표시하는 모델링은?","choices":["Function","Dynamic","Static","Object"],"ans":4,"exp":{"concept":"럼바우(Rumbaugh)의 객체 모델링 기법(OMT)은 객체 모델링, 동적 모델링, 기능 모델링 세 가지로 분석한다. 이 중 객체 모델링은 정보 모델링이라고도 부르며, 객체와 속성, 연산, 객체 사이의 관계를 찾아 객체 다이어그램으로 나타낸다.","choices":[{"verdict":"오답","why":"기능 모델링(Function)은 자료 흐름도(DFD)를 이용해 입력에서 출력까지 데이터가 어떻게 변환되는지를 나타낸다."},{"verdict":"오답","why":"동적 모델링(Dynamic)은 상태 다이어그램을 이용해 시간에 따라 객체의 상태가 어떻게 변하는지 나타낸다."},{"verdict":"오답","why":"Static(정적 모델링)은 럼바우 분석 기법의 3가지 모델링에 속하지 않는다."},{"verdict":"정답","why":"객체 모델링(Object)은 정보 모델링이라고도 하며, 객체를 찾아 속성과 연산을 식별하고 객체 사이의 관계를 객체 다이어그램으로 표시한다."}],"keywords":[{"term":"객체 모델링(Object Modeling)","desc":"객체 다이어그램으로 객체, 속성, 연산, 관계를 표현. 정보 모델링이라고도 한다"},{"term":"동적 모델링(Dynamic Modeling)","desc":"상태 다이어그램으로 시간에 따른 객체의 상태 변화를 표현"},{"term":"기능 모델링(Functional Modeling)","desc":"자료 흐름도(DFD)로 데이터 처리 과정을 표현"},{"term":"OMT(Object Modeling Technique)","desc":"럼바우가 제안한 객체지향 분석 기법"}],"memo":"럼바우는 '객동기(객체 → 동적 → 기능)' 순서이고, 정보 모델링이라는 별명은 객체 모델링에 붙는다."}},{"id":"written-2023-3-8","no":8,"unit":"소프트웨어 설계","q":"다음 중 데이터 흐름도(DFD)의 구성 요소에 해당하지 않는 것은?","choices":["Data Store","Data Flow","Process","Data Dictionary"],"ans":4,"exp":{"concept":"데이터 흐름도(DFD, Data Flow Diagram)는 데이터가 시스템 안에서 어떻게 흘러가며 처리되는지를 그림으로 나타낸 것이다. 구성 요소는 처리 과정(Process), 데이터 흐름(Data Flow), 자료 저장소(Data Store), 단말(Terminator) 4가지다. 자료 사전은 DFD에 나오는 데이터를 정의한 별도 문서다.","choices":[{"verdict":"오답","why":"자료 저장소(Data Store)는 데이터가 저장되는 곳으로, 평행한 두 줄로 표시하는 DFD 구성 요소다."},{"verdict":"오답","why":"데이터 흐름(Data Flow)은 데이터의 이동을 화살표로 표시하는 DFD 구성 요소다."},{"verdict":"오답","why":"처리 과정(Process)은 입력 데이터를 출력 데이터로 바꾸는 작업으로, 원으로 표시하는 DFD 구성 요소다."},{"verdict":"정답","why":"자료 사전(Data Dictionary)은 DFD에 나타난 데이터의 이름, 구조, 의미를 정의한 별도의 문서로, DFD의 구성 요소가 아니다."}],"keywords":[{"term":"처리 과정(Process)","desc":"데이터를 변환하는 작업, 원(○)으로 표시"},{"term":"데이터 흐름(Data Flow)","desc":"데이터의 이동, 화살표로 표시"},{"term":"자료 저장소(Data Store)","desc":"데이터를 보관하는 곳, 평행선(=)으로 표시"},{"term":"단말(Terminator)","desc":"시스템 외부의 데이터 입출력 대상, 사각형으로 표시"},{"term":"자료 사전(Data Dictionary)","desc":"DFD에 나오는 데이터를 정의한 문서"}],"memo":"DFD 구성 요소는 '처리, 흐름, 저장소, 단말' 4개. 사전(Dictionary)은 그림이 아니라 문서다."}},{"id":"written-2023-3-9","no":9,"unit":"소프트웨어 설계","q":"소프트웨어 설계 지침으로 바람직하지 않은 것은?","choices":["모듈의 크기를 적당하게 유지한다.","모듈 간의 접속 관계를 분석하여 복잡도 및 중복을 줄인다.","모듈 간의 효과적인 제어를 위해 설계에서 계층적 자료 조직이 제시될 필요가 있다.","모듈 간의 결합도는 강할수록 바람직하다."],"ans":4,"exp":{"concept":"좋은 소프트웨어 설계는 모듈 하나하나가 독립적으로 동작하도록 만드는 것이다. 이를 위해 모듈 사이의 의존 정도인 결합도는 약하게(낮게), 모듈 내부 요소들의 관련 정도인 응집도는 강하게(높게) 한다. 결합도가 강하면 한 모듈을 고칠 때 다른 모듈까지 고쳐야 한다.","choices":[{"verdict":"오답","why":"모듈 크기를 적당히 유지하는 것은 이해와 유지보수를 쉽게 하는 바람직한 설계 지침이다."},{"verdict":"오답","why":"모듈 간 접속 관계를 분석해 복잡도와 중복을 줄이는 것은 바람직한 설계 지침이다."},{"verdict":"오답","why":"설계에서 계층적 자료 조직을 제시해 모듈 간 제어를 효과적으로 하는 것은 표준 설계 지침에 포함된 내용이다."},{"verdict":"정답","why":"결합도는 약할수록(낮을수록) 모듈 독립성이 높아져 바람직하다. 강할수록 좋다는 설명은 틀렸다."}],"keywords":[{"term":"결합도(Coupling)","desc":"모듈과 모듈 사이의 의존 정도, 약할수록 좋다"},{"term":"응집도(Cohesion)","desc":"모듈 내부 요소들이 서로 관련된 정도, 강할수록 좋다"},{"term":"모듈 독립성","desc":"결합도는 낮추고 응집도는 높여서 얻는 설계 품질"},{"term":"팬인(Fan-In)/팬아웃(Fan-Out)","desc":"어떤 모듈을 호출하는 모듈 수 / 어떤 모듈이 호출하는 모듈 수"}],"memo":"'결합도는 낮게, 응집도는 높게'를 한 쌍으로 외운다. 반대로 적힌 보기가 단골 오답이다."}},{"id":"written-2023-3-10","no":10,"unit":"소프트웨어 설계","q":"GoF(Gangs of Four) 디자인 패턴의 분류에 속하지 않는 것은?","choices":["객체 패턴","구조 패턴","생성 패턴","행위 패턴"],"ans":1,"exp":{"concept":"GoF(Gang of Four) 디자인 패턴은 에릭 감마 등 4명이 정리한 23가지 패턴이다. 목적에 따라 생성 패턴, 구조 패턴, 행위 패턴의 3가지로 나눈다. 객체 패턴이라는 분류는 없다.","choices":[{"verdict":"정답","why":"GoF 디자인 패턴은 생성, 구조, 행위 3가지로만 분류하며, '객체 패턴'은 목적에 따른 분류에 없다."},{"verdict":"오답","why":"구조 패턴(Structural)은 클래스나 객체를 조합해 더 큰 구조를 만드는 패턴으로 GoF 분류에 속한다. 예: Adapter, Bridge, Composite, Decorator, Facade, Flyweight, Proxy."},{"verdict":"오답","why":"생성 패턴(Creational)은 객체 생성 방법을 다루는 패턴으로 GoF 분류에 속한다. 예: Singleton, Factory Method, Abstract Factory, Builder, Prototype."},{"verdict":"오답","why":"행위 패턴(Behavioral)은 객체 사이의 책임 분배와 상호작용을 다루는 패턴으로 GoF 분류에 속한다. 예: Observer, Strategy, State, Command."}],"keywords":[{"term":"생성 패턴","desc":"객체를 만드는 방법을 다룸. Singleton, Factory Method, Abstract Factory, Builder, Prototype"},{"term":"구조 패턴","desc":"클래스·객체를 조합해 구조를 만듦. Adapter, Bridge, Composite, Decorator, Facade, Flyweight, Proxy"},{"term":"행위 패턴","desc":"객체 간 상호작용과 책임 분배. Observer, Strategy, State, Command, Iterator 등"},{"term":"GoF(Gang of Four)","desc":"디자인 패턴 23가지를 정리한 4명의 저자"}],"memo":"GoF 분류는 '생구행(생성, 구조, 행위)' 세 가지뿐이다."}},{"id":"written-2023-3-11","no":11,"unit":"소프트웨어 설계","q":"소프트웨어 설계 시 구축된 플랫폼의 성능 특성을 분석하는 데 사용되는 측정 항목으로 옳지 않은 것은?","choices":["가용성(Availability)","응답 시간(Response Time)","서버 튜닝(Server Tuning)","사용률(Utilization)"],"ans":3,"exp":{"concept":"소프트웨어를 설계할 때 그 소프트웨어가 돌아갈 플랫폼(하드웨어, 운영체제 등)의 성능이 충분한지 측정해 본다. 이때 쓰는 측정 항목은 응답 시간, 가용성, 사용률처럼 수치로 잴 수 있는 지표다. 서버 튜닝은 성능을 높이기 위한 조치이지 측정 항목이 아니다.","choices":[{"verdict":"오답","why":"가용성(Availability)은 시스템이 필요할 때 정상적으로 사용할 수 있는 정도로, 성능 특성 측정 항목이다."},{"verdict":"오답","why":"응답 시간(Response Time)은 요청을 보낸 뒤 응답을 받기까지 걸리는 시간으로, 성능 특성 측정 항목이다."},{"verdict":"정답","why":"서버 튜닝(Server Tuning)은 성능을 개선하기 위해 설정을 조정하는 작업이지, 성능 특성을 분석하는 측정 항목이 아니다."},{"verdict":"오답","why":"사용률(Utilization)은 CPU, 메모리 같은 자원이 일정 시간 동안 사용된 비율로, 성능 특성 측정 항목이다."}],"keywords":[{"term":"응답 시간(Response Time)","desc":"요청 후 응답이 올 때까지 걸리는 시간"},{"term":"가용성(Availability)","desc":"시스템을 필요할 때 사용할 수 있는 정도"},{"term":"사용률(Utilization)","desc":"자원이 사용되는 비율"},{"term":"서버 튜닝(Server Tuning)","desc":"성능 향상을 위한 서버 설정 조정 작업"}],"memo":"측정 항목은 '숫자로 잴 수 있는 것'이다. 튜닝처럼 '하는 일'이 섞여 있으면 그것이 답이다."}},{"id":"written-2023-3-12","no":12,"unit":"소프트웨어 설계","q":"XP(eXtreme Programing)의 5가지 가치와 거리가 먼 것은?","choices":["피드백","정형 분석","용기","의사소통"],"ans":2,"exp":{"concept":"XP(eXtreme Programming)는 고객의 요구 변화에 빠르게 대응하는 대표적인 애자일 방법론이다. XP의 5가지 핵심 가치는 의사소통, 단순성, 용기, 존중, 피드백이다. 정형 분석은 수학적 표기로 명세를 엄밀하게 분석하는 기법으로 XP의 가치가 아니다.","choices":[{"verdict":"오답","why":"피드백(Feedback)은 XP의 5가지 핵심 가치에 속한다."},{"verdict":"정답","why":"정형 분석은 수학 기반 언어로 요구사항을 엄밀하게 표현·분석하는 기법으로, XP의 5가지 핵심 가치에 속하지 않는다."},{"verdict":"오답","why":"용기(Courage)는 XP의 5가지 핵심 가치에 속한다."},{"verdict":"오답","why":"의사소통(Communication)은 XP의 5가지 핵심 가치에 속한다."}],"keywords":[{"term":"XP 5가지 핵심 가치","desc":"의사소통, 단순성, 용기, 존중, 피드백"},{"term":"짝 프로그래밍(Pair Programming)","desc":"두 사람이 한 컴퓨터로 함께 개발하는 XP 실천 사항"},{"term":"테스트 주도 개발(TDD)","desc":"테스트를 먼저 작성하고 그에 맞춰 코드를 작성하는 실천 사항"},{"term":"정형 분석","desc":"수학적 표기법으로 요구사항을 엄밀하게 명세·분석하는 기법"}],"memo":"XP 가치는 '용단의 피존(용기, 단순성, 의사소통, 피드백, 존중)'으로 외운다."}},{"id":"written-2023-3-13","no":13,"unit":"소프트웨어 설계","q":"아키텍처 설계 과정을 올바른 순서대로 나열한 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul class=\"is-labeled\"><li>가. 설계 목표 설정</li><li>나. 시스템 타입 결정</li><li>다. 스타일 적용 및 커스터마이즈</li><li>라. 서브시스템의 기능, 인터페이스 동작 작성</li><li>마. 아키텍처 설계 검토</li></ul></div>","choices":["㉮ → ㉯ → ㉰ → ㉱ → ㉲","㉲ → ㉮ → ㉯ → ㉱ → ㉰","㉮ → ㉲ → ㉯ → ㉱ → ㉰","㉮ → ㉯ → ㉰ → ㉲ → ㉱"],"ans":1,"exp":{"concept":"아키텍처 설계는 목표를 정하고, 시스템 종류를 정하고, 그에 맞는 스타일을 골라 다듬은 뒤, 세부 서브시스템을 작성하고, 마지막으로 전체를 검토하는 순서로 진행한다. 집을 지을 때 목적을 정하고, 건물 종류를 정하고, 설계 양식을 고르고, 방마다 세부를 그린 뒤, 마지막에 도면을 검토하는 것과 같다.","choices":[{"verdict":"정답","why":"설계 목표 설정 → 시스템 타입 결정 → 스타일 적용 및 커스터마이즈 → 서브시스템의 기능·인터페이스 동작 작성 → 아키텍처 설계 검토의 올바른 순서다."},{"verdict":"오답","why":"검토(마)는 설계를 다 마친 뒤 마지막에 하는 단계이므로 맨 앞에 올 수 없다."},{"verdict":"오답","why":"검토(마)가 두 번째에 오고 스타일 적용(다)이 맨 뒤에 있어 순서가 틀렸다."},{"verdict":"오답","why":"서브시스템의 기능과 인터페이스를 작성(라)하기 전에 검토(마)를 하는 순서라 틀렸다. 검토는 마지막 단계다."}],"keywords":[{"term":"설계 목표 설정","desc":"시스템 개발 방향을 정하는 첫 단계"},{"term":"시스템 타입 결정","desc":"대화형, 이벤트 중심, 변환형, 객체 영속형 등 시스템 종류를 정함"},{"term":"스타일 적용 및 커스터마이즈","desc":"아키텍처 스타일을 골라 시스템에 맞게 조정"},{"term":"아키텍처 설계 검토","desc":"설계 결과를 마지막에 점검하는 단계"}],"memo":"'목표 → 타입 → 스타일 → 서브시스템 → 검토', 검토는 언제나 마지막이다."}},{"id":"written-2023-3-14","no":14,"unit":"소프트웨어 설계","q":"HIPO(Hierarchy Input Process Output)에 관한 설명 중 옳지 않은 것은?","choices":["기능과 자료의 의존 관계를 통하여 표현할 수 있다.","구조도, 개요 도표 집합, 상세 도표 집합으로 이루어진다.","보기 쉬우며 이해하기 쉽다.","상향식 소프트웨어 개발을 위한 문서화 도구에 해당한다."],"ans":4,"exp":{"concept":"HIPO(Hierarchy Input Process Output)는 시스템의 기능을 위에서 아래로 계층적으로 나누어 입력, 처리, 출력을 도표로 나타내는 문서화 도구다. 큰 기능부터 작은 기능으로 내려가므로 하향식(Top-Down) 개발에 쓰인다. 가시적 도표, 총체적 도표, 세부적 도표로 구성된다.","choices":[{"verdict":"오답","why":"HIPO는 기능과 자료의 의존 관계를 함께 표현할 수 있다. 맞는 설명이다."},{"verdict":"오답","why":"구조도(가시적 도표), 개요 도표 집합(총체적 도표), 상세 도표 집합(세부적 도표)으로 이루어진다. 맞는 설명이다."},{"verdict":"오답","why":"도표 중심이라 보기 쉽고 이해하기 쉽다. 맞는 설명이다."},{"verdict":"정답","why":"HIPO는 상향식이 아니라 하향식(Top-Down) 소프트웨어 개발을 위한 문서화 도구다."}],"keywords":[{"term":"HIPO","desc":"기능을 계층적으로 나누어 입력·처리·출력을 도표로 표현하는 하향식 문서화 도구"},{"term":"가시적 도표(Visual Table of Contents)","desc":"시스템 전체 기능과 흐름을 계층(트리) 구조로 보여 주는 도표"},{"term":"총체적 도표(Overview Diagram)","desc":"기능별 입력, 처리, 출력의 전반적인 정보를 제공하는 도표"},{"term":"세부적 도표(Detail Diagram)","desc":"총체적 도표의 내용을 구체적으로 기술한 도표"}],"memo":"HIPO의 H는 Hierarchy(계층). 계층을 위에서 아래로 쪼개므로 하향식이다."}},{"id":"written-2023-3-15","no":15,"unit":"소프트웨어 설계","q":"다음 중 결합도가 가장 강한 것은?","choices":["Common Coupling","Date Coupling","Stamp Coupling","Control Coupling"],"ans":1,"exp":{"concept":"결합도는 모듈끼리 얼마나 얽혀 있는지를 나타낸다. 약한 것부터 자료(Data) < 스탬프(Stamp) < 제어(Control) < 외부(External) < 공통(Common) < 내용(Content) 결합도 순으로 강해진다. 보기 중에서는 공통 결합도가 가장 강하다.","choices":[{"verdict":"정답","why":"공통 결합도(Common Coupling)는 여러 모듈이 전역 변수 같은 공통 데이터 영역을 함께 쓰는 결합도로, 보기 중 가장 강하다."},{"verdict":"오답","why":"자료 결합도(Data Coupling, 보기의 Date는 Data의 오기)는 인터페이스가 자료 요소로만 이루어진 가장 약한 결합도다."},{"verdict":"오답","why":"스탬프 결합도(Stamp Coupling)는 배열이나 레코드 같은 자료 구조를 넘기는 결합도로, 자료 결합도 다음으로 약하다."},{"verdict":"오답","why":"제어 결합도(Control Coupling)는 제어 신호(플래그)를 넘겨 다른 모듈의 흐름을 바꾸는 결합도로, 공통 결합도보다 약하다."}],"keywords":[{"term":"자료 결합도(Data)","desc":"자료 요소만 주고받음, 가장 약함"},{"term":"스탬프 결합도(Stamp)","desc":"배열·레코드 같은 자료 구조를 주고받음"},{"term":"제어 결합도(Control)","desc":"제어 신호를 넘겨 상대 모듈의 처리 흐름을 바꿈"},{"term":"공통 결합도(Common)","desc":"전역 변수 같은 공통 데이터 영역을 함께 사용"},{"term":"내용 결합도(Content)","desc":"다른 모듈의 내부 자료나 코드를 직접 참조·수정, 가장 강함"}],"memo":"결합도 약→강은 '자스제외공내(자료, 스탬프, 제어, 외부, 공통, 내용)'."}},{"id":"written-2023-3-16","no":16,"unit":"소프트웨어 설계","q":"GoF(Gangs of Four) 디자인 패턴 가운데 생성 패턴에 해당하는 것은?","choices":["Adapter Pattern","State Pattern","Decorator Pattern","Singleton Pattern"],"ans":4,"exp":{"concept":"GoF 생성 패턴은 객체를 어떻게 만들지를 다루는 패턴이다. Singleton, Factory Method, Abstract Factory, Builder, Prototype 5가지가 있다. 그중 싱글톤은 클래스의 인스턴스를 하나만 만들어 어디서든 그 하나를 함께 쓰게 한다.","choices":[{"verdict":"오답","why":"어댑터(Adapter) 패턴은 호환되지 않는 인터페이스를 변환해 함께 쓸 수 있게 하는 구조 패턴이다."},{"verdict":"오답","why":"상태(State) 패턴은 객체의 상태에 따라 동작을 바꾸는 행위 패턴이다."},{"verdict":"오답","why":"데코레이터(Decorator) 패턴은 객체에 기능을 동적으로 덧붙이는 구조 패턴이다."},{"verdict":"정답","why":"싱글톤(Singleton) 패턴은 인스턴스를 하나만 생성하도록 보장하는 생성 패턴이다."}],"keywords":[{"term":"생성 패턴","desc":"Singleton, Factory Method, Abstract Factory, Builder, Prototype"},{"term":"싱글톤(Singleton)","desc":"클래스의 인스턴스를 하나만 만들어 전역에서 공유"},{"term":"어댑터(Adapter)","desc":"인터페이스가 다른 클래스를 연결해 주는 구조 패턴"},{"term":"데코레이터(Decorator)","desc":"객체에 기능을 동적으로 추가하는 구조 패턴"}],"memo":"생성 패턴 5개(Singleton, Factory Method, Abstract Factory, Builder, Prototype)만 확실히 외우면 나머지는 구조 패턴이나 행위 패턴이다."}},{"id":"written-2023-3-17","no":17,"unit":"소프트웨어 설계","q":"다음 중 결합도의 종류에 관한 설명으로 옳지 않은 것은?","choices":["내용 결합도 : 한 모듈이 다른 모듈과 제어 신호를 이용해 통신하며, 공유되는 공통 데이터 영역을 사용할 때의 결합도","자료 결합도 : 모듈 간 인터페이스가 자료 요소로만 이루어질 때의 결합도","스탬프 결합도 : 모듈 간 인터페이스로 배열의 자료 구조가 전달될 때의 결합도","외부 결합도 : 어떤 모듈에서 선언한 데이터를 다른 모듈이 참조할 때의 결합도"],"ans":1,"exp":{"concept":"결합도의 종류마다 모듈이 어떻게 얽히는지가 다르다. 내용 결합도는 한 모듈이 다른 모듈의 내부 자료나 코드를 직접 참조하거나 고치는, 가장 강한 결합이다. 제어 신호로 통신하는 것은 제어 결합도, 공통 데이터 영역을 쓰는 것은 공통 결합도다.","choices":[{"verdict":"정답","why":"제어 신호로 통신하는 것은 제어 결합도, 공유되는 공통 데이터 영역을 쓰는 것은 공통 결합도의 설명이다. 내용 결합도는 한 모듈이 다른 모듈의 내부 기능이나 자료를 직접 참조·수정할 때의 결합도다."},{"verdict":"오답","why":"자료 결합도는 모듈 간 인터페이스가 자료 요소로만 구성된 결합도로, 맞는 설명이다."},{"verdict":"오답","why":"스탬프 결합도는 배열이나 레코드 같은 자료 구조가 인터페이스로 전달되는 결합도로, 맞는 설명이다."},{"verdict":"오답","why":"외부 결합도는 어떤 모듈에서 선언한 데이터(변수)를 외부의 다른 모듈이 참조할 때의 결합도로, 맞는 설명이다."}],"keywords":[{"term":"내용 결합도(Content)","desc":"다른 모듈의 내부 자료나 코드를 직접 참조·수정"},{"term":"공통 결합도(Common)","desc":"공유되는 공통 데이터 영역을 여러 모듈이 사용"},{"term":"외부 결합도(External)","desc":"한 모듈에서 선언한 데이터를 외부 모듈이 참조"},{"term":"제어 결합도(Control)","desc":"제어 신호(플래그)를 넘겨 다른 모듈의 흐름을 제어"}],"memo":"내용 결합도는 '남의 집 안방(내부)에 직접 들어가는 것'. 제어 신호, 공통 영역이라는 말이 나오면 다른 결합도다."}},{"id":"written-2023-3-18","no":18,"unit":"소프트웨어 설계","q":"럼바우(Rumbaugh)의 객체지향 분석 절차를 순서대로 가장 바르게 나열한 것은?","choices":["기능 모형 → 동적 모형 → 객체 모형","객체 모형 → 기능 모형 → 동적 모형","객체 모형 → 동적 모형 → 기능 모형","기능 모형 → 객체 모형 → 동적 모형"],"ans":3,"exp":{"concept":"럼바우(Rumbaugh)의 객체지향 분석 기법은 먼저 어떤 객체가 있는지 정하고(객체 모형), 그 객체들이 시간에 따라 어떻게 변하는지 보고(동적 모형), 마지막으로 데이터가 어떻게 처리되는지(기능 모형)를 분석한다. 등장인물을 먼저 정하고, 줄거리를 짜고, 각 장면의 처리 과정을 정리하는 것과 비슷하다.","choices":[{"verdict":"오답","why":"기능 모형이 가장 먼저 오는 순서는 럼바우 분석 절차와 다르다."},{"verdict":"오답","why":"객체 모형 다음에는 기능 모형이 아니라 동적 모형이 온다."},{"verdict":"정답","why":"객체 모형 → 동적 모형 → 기능 모형이 럼바우 분석 절차의 올바른 순서다."},{"verdict":"오답","why":"기능 모형으로 시작하는 순서는 틀렸다. 럼바우는 객체 모형부터 시작한다."}],"keywords":[{"term":"객체 모형(Object Model)","desc":"객체 다이어그램으로 객체와 관계를 표현"},{"term":"동적 모형(Dynamic Model)","desc":"상태 다이어그램으로 시간에 따른 상태 변화를 표현"},{"term":"기능 모형(Functional Model)","desc":"자료 흐름도(DFD)로 데이터 처리 과정을 표현"},{"term":"OMT","desc":"럼바우의 객체 모델링 기법"}],"memo":"럼바우 순서는 '객동기(객체 → 동적 → 기능)'."}},{"id":"written-2023-3-19","no":19,"unit":"소프트웨어 설계","q":"객체지향 개념에서 서로 연관된 데이터와 함수를 하나로 묶어 외부와의 경계를 만들고 필요한 인터페이스만 밖으로 드러내는 과정은 무엇인가?","choices":["메시지(Message)","다형성(Polymorphism)","캡슐화(Encapsulation)","상속(Inheritance)"],"ans":3,"exp":{"concept":"캡슐화(Encapsulation)는 서로 관련된 데이터와 그 데이터를 다루는 함수를 하나로 묶고, 바깥에는 필요한 인터페이스만 보여 주는 것이다. 알약 캡슐 속 내용물은 보이지 않고 겉모양만 보이는 것과 같다. 내부를 숨기므로 정보 은닉이 되고, 고칠 때 다른 곳에 미치는 영향이 줄어든다.","choices":[{"verdict":"오답","why":"메시지(Message)는 객체에게 어떤 행위를 하도록 지시하는 명령이다."},{"verdict":"오답","why":"다형성(Polymorphism)은 같은 이름의 메소드가 객체에 따라 다르게 동작하는 성질이다."},{"verdict":"정답","why":"캡슐화(Encapsulation)는 데이터와 함수를 하나로 묶어 외부와 경계를 만들고 필요한 인터페이스만 드러내는 것이다."},{"verdict":"오답","why":"상속(Inheritance)은 상위 클래스의 속성과 연산을 하위 클래스가 물려받는 것이다."}],"keywords":[{"term":"캡슐화(Encapsulation)","desc":"데이터와 함수를 하나로 묶고 내부를 숨김"},{"term":"정보 은닉(Information Hiding)","desc":"다른 객체에게 내부 정보를 숨기고 인터페이스로만 접근하게 함"},{"term":"다형성(Polymorphism)","desc":"같은 메시지에 객체마다 다르게 반응하는 성질"},{"term":"상속(Inheritance)","desc":"상위 클래스의 특성을 하위 클래스가 물려받음"}],"memo":"'묶고 숨긴다'가 나오면 캡슐화다."}},{"id":"written-2023-3-20","no":20,"unit":"소프트웨어 설계","q":"메시지 지향 미들웨어(Message-Oriented Middleware, MOM)에 관한 설명 중 틀린 것은?","choices":["송신측과 수신측을 연결할 때 메시지 큐를 활용하는 방법이 있다.","독립적인 애플리케이션들을 하나의 통합된 시스템으로 묶는 역할을 한다.","서로 상이한 애플리케이션 간의 통신을 비동기 방식으로 지원한다.","느리고 안정적인 응답보다 즉각적인 응답을 요구하는 온라인 업무에 적합하다."],"ans":4,"exp":{"concept":"메시지 지향 미들웨어(MOM)는 서로 다른 애플리케이션이 메시지를 주고받으며 통신하도록 돕는 미들웨어다. 메시지 큐에 메시지를 넣어 두면 받는 쪽이 나중에 꺼내 처리하는 비동기 방식이다. 그래서 즉각적인 응답보다는 조금 느려도 확실하게 전달되어야 하는 업무에 알맞다.","choices":[{"verdict":"오답","why":"메시지 큐를 사용해 송신측과 수신측을 연결하는 것이 MOM의 대표 방식이다. 맞는 설명이다."},{"verdict":"오답","why":"독립적인 애플리케이션들을 메시지로 연결해 하나의 통합된 시스템으로 묶는다. 맞는 설명이다."},{"verdict":"오답","why":"서로 다른 애플리케이션 사이의 통신을 비동기 방식으로 지원한다. 맞는 설명이다."},{"verdict":"정답","why":"MOM은 비동기 방식이므로 즉각적인 응답이 필요한 온라인 업무보다 느리고 안정적인 응답이 필요한 업무에 적합하다. 설명이 반대로 되어 있다."}],"keywords":[{"term":"MOM(Message-Oriented Middleware)","desc":"메시지 기반 비동기 통신을 지원하는 미들웨어"},{"term":"메시지 큐(Message Queue)","desc":"메시지를 임시 저장해 두고 수신측이 나중에 꺼내 처리하는 구조"},{"term":"TP 모니터","desc":"온라인 트랜잭션을 빠르게 처리·감시하는 미들웨어, 즉각 응답이 필요한 업무에 쓰인다"},{"term":"RPC(Remote Procedure Call)","desc":"원격 프로시저를 로컬 함수처럼 호출하는 미들웨어"}],"memo":"MOM은 '우편'과 같다. 느려도 확실히 전달된다. 즉시 응답이 필요하면 TP 모니터다."}},{"id":"written-2023-3-21","no":21,"unit":"소프트웨어 개발","q":"제품 소프트웨어의 형상 관리 역할에 대한 설명으로 옳지 않은 것은?","choices":["형상 관리를 통해 이전 리버전이나 버전의 정보에 접근할 수 있어 배포본 관리에 유용","동일한 프로젝트에 대해 여러 개발자가 동시에 개발 가능","프로젝트 개발비용을 효율적으로 관리","불필요한 사용자의 소스 수정을 제한"],"ans":3,"exp":{"concept":"형상 관리(SCM)는 개발 중 생기는 소스 코드, 문서 같은 산출물의 변경을 체계적으로 기록하고 통제하는 활동이다. 이전 버전으로 돌아가기, 여러 개발자의 동시 작업 지원, 무단 변경 방지 같은 역할을 한다. 개발 비용을 관리하는 것은 프로젝트 관리의 일이지 형상 관리의 역할이 아니다.","choices":[{"verdict":"오답","why":"형상 관리로 이전 리비전이나 버전 정보에 접근할 수 있어 배포본 관리에 유용하다. 맞는 설명이다."},{"verdict":"오답","why":"버전 관리와 병합 기능으로 여러 개발자가 같은 프로젝트를 동시에 개발할 수 있다. 맞는 설명이다."},{"verdict":"정답","why":"프로젝트 개발 비용 관리는 형상 관리의 역할이 아니다. 형상 관리는 산출물의 변경을 관리하는 활동이다."},{"verdict":"오답","why":"권한이 없는 사용자의 소스 수정을 제한해 무단 변경을 막는다. 맞는 설명이다."}],"keywords":[{"term":"형상 관리(SCM)","desc":"소프트웨어 산출물의 변경을 식별·통제·기록하는 활동"},{"term":"형상 식별","desc":"관리할 형상 항목을 정하고 이름과 번호를 붙임"},{"term":"형상 통제","desc":"변경 요청을 검토해 승인된 변경만 반영"},{"term":"형상 감사","desc":"변경이 제대로 이루어졌는지 검증"},{"term":"형상 기록(상태 보고)","desc":"변경 사항을 기록하고 보고"}],"memo":"형상 관리 절차는 '식통감기(식별, 통제, 감사, 기록)'. '비용'이 나오면 오답이다."}},{"id":"written-2023-3-22","no":22,"unit":"소프트웨어 개발","q":"객체지향 개념을 활용한 소프트웨어 구현에 대한 설명으로 틀린 것은?","choices":["같은 클래스에 속하는 개개의 객체로서 하나의 클래스에서 생성된 객체를 인스턴스(Instance)라고 한다.","객체(Object)는 필요한 자료 구조와 수행되는 함수들을 가진 하나의 독립된 존재이다.","JAVA에서 정보은닉(Information Hiding)을 표기할 때 private가 갖는 의미는 ‘공개’이다.","상속(Inheritance)은 개별 클래스를 상속 관계로 묶어 클래스 간의 체계화된 전체 구조를 파악하기 쉽다는 장점을 가진다."],"ans":3,"exp":{"concept":"객체지향 구현의 기본 개념을 묻는 문제다. 정보 은닉을 위해 Java는 접근 제어자를 쓰는데, private는 클래스 내부에서만 접근할 수 있는 '비공개'를 뜻하고, public이 '공개'를 뜻한다.","choices":[{"verdict":"오답","why":"하나의 클래스에서 생성된 개개의 객체를 인스턴스라 한다. 맞는 설명이다."},{"verdict":"오답","why":"객체는 필요한 자료 구조와 이를 처리하는 함수를 함께 가진 하나의 독립된 존재다. 맞는 설명이다."},{"verdict":"정답","why":"Java에서 private는 같은 클래스 안에서만 접근할 수 있다는 '비공개'의 의미다. '공개'는 public이다."},{"verdict":"오답","why":"상속을 이용하면 클래스들을 상위·하위 관계로 묶어 전체 구조를 체계적으로 파악하기 쉽다. 맞는 설명이다."}],"keywords":[{"term":"public","desc":"어디서든 접근 가능(공개)"},{"term":"protected","desc":"같은 패키지와 하위 클래스에서 접근 가능"},{"term":"default(package)","desc":"같은 패키지 안에서만 접근 가능"},{"term":"private","desc":"같은 클래스 안에서만 접근 가능(비공개)"}],"memo":"Java 접근 범위는 넓은 것부터 public > protected > default > private. private는 '사적인, 비공개'다."}},{"id":"written-2023-3-23","no":23,"unit":"소프트웨어 개발","q":"구현 단계의 작업 절차를 순서대로 바르게 나열한 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul class=\"is-labeled\"><li>ㄱ. 코딩한다.</li><li>ㄴ. 코딩작업을 계획한다.</li><li>ㄷ. 코드를 테스트한다.</li><li>ㄹ. 컴파일한다.</li></ul></div>","choices":["㉢ → ㉠ → ㉡ → ㉣","㉣ → ㉡ → ㉠ → ㉢","㉡ → ㉠ → ㉣ → ㉢","㉠ → ㉡ → ㉢ → ㉣"],"ans":3,"exp":{"concept":"구현 단계는 무엇을 어떻게 만들지 계획을 세운 뒤 코드를 쓰고, 컴퓨터가 실행할 수 있게 컴파일한 다음, 제대로 동작하는지 테스트하는 순서로 진행한다. 요리로 치면 메뉴를 정하고(계획), 재료를 손질해 조리하고(코딩), 익히고(컴파일), 맛을 보는(테스트) 순서다.","choices":[{"verdict":"오답","why":"테스트(ㄷ)가 맨 앞에 오는 순서는 틀렸다. 테스트는 코드를 만들고 컴파일한 뒤에 한다."},{"verdict":"오답","why":"컴파일(ㄹ)이 계획과 코딩보다 먼저 올 수 없다. 컴파일할 코드가 아직 없다."},{"verdict":"정답","why":"코딩 작업 계획(ㄴ) → 코딩(ㄱ) → 컴파일(ㄹ) → 테스트(ㄷ)가 올바른 순서다."},{"verdict":"오답","why":"계획(ㄴ) 전에 코딩(ㄱ)을 하고, 컴파일(ㄹ) 전에 테스트(ㄷ)를 하는 순서라 틀렸다."}],"keywords":[{"term":"코딩 계획","desc":"구현할 기능과 방법, 표준을 먼저 정하는 단계"},{"term":"코딩","desc":"설계를 바탕으로 프로그래밍 언어로 소스 코드를 작성"},{"term":"컴파일","desc":"소스 코드를 실행 가능한 기계어로 번역"},{"term":"테스트","desc":"코드가 요구대로 동작하는지 확인"}],"memo":"'계획 → 코딩 → 컴파일 → 테스트'. 상식적인 순서이니 보기 기호(ㄱ~ㄹ)를 옮겨 적을 때 실수만 조심한다."}},{"id":"written-2023-3-24","no":24,"unit":"소프트웨어 개발","q":"다음 자료를 버블 정렬로 오름차순 정렬할 때 PASS 1의 결과로 옳은 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>9, 6, 7, 3, 5</p></div>","choices":["6, 9, 7, 3, 5","3, 9, 6, 7, 5","3, 6, 7, 9, 5","6, 7, 3, 5, 9"],"ans":4,"exp":{"concept":"버블 정렬은 이웃한 두 값을 비교해 앞의 값이 크면 자리를 바꾸는 과정을 처음부터 끝까지 반복한다. 한 번 훑는 것(PASS 1)이 끝나면 가장 큰 값이 맨 뒤로 간다. 물속 거품이 위로 떠오르듯 큰 값이 뒤로 올라간다.","choices":[{"verdict":"오답","why":"6, 9, 7, 3, 5는 첫 번째 비교(9와 6 교환)만 한 상태다. PASS 1은 끝까지 비교를 계속해야 한다."},{"verdict":"오답","why":"3, 9, 6, 7, 5는 가장 작은 값을 맨 앞으로 보낸 모양으로, 버블 정렬 PASS 1의 결과가 아니다."},{"verdict":"오답","why":"3, 6, 7, 9, 5는 버블 정렬 PASS 1의 결과가 아니다. 버블 정렬 PASS 1이 끝나면 최댓값 9가 반드시 맨 뒤에 있어야 한다."},{"verdict":"정답","why":"9,6 교환 → 6,9,7,3,5 / 9,7 교환 → 6,7,9,3,5 / 9,3 교환 → 6,7,3,9,5 / 9,5 교환 → 6,7,3,5,9. PASS 1 결과는 6, 7, 3, 5, 9다."}],"keywords":[{"term":"버블 정렬(Bubble Sort)","desc":"이웃한 두 값을 비교·교환해 큰 값을 뒤로 보내는 정렬"},{"term":"PASS","desc":"자료를 처음부터 끝까지 한 번 훑는 단위. n개면 PASS 1에서 n-1번 비교"},{"term":"선택 정렬(Selection Sort)","desc":"남은 값 중 최솟값을 골라 맨 앞과 교환하는 정렬"},{"term":"삽입 정렬(Insertion Sort)","desc":"앞쪽의 정렬된 부분에 새 값을 알맞은 자리에 끼워 넣는 정렬"}],"memo":"버블 정렬 PASS 1이 끝나면 최댓값이 맨 뒤에 있다. 맨 뒤가 최댓값이 아닌 보기는 바로 지운다."}},{"id":"written-2023-3-25","no":25,"unit":"소프트웨어 개발","q":"다음 중 스택에 관한 설명으로 옳지 않은 것은?","choices":["LIFO 구조이다.","Head(front)와 Tail(rear)이라는 2개의 포인터를 가진다.","입출력이 한쪽 끝에서만 이루어지도록 제한된 리스트이다.","더 이상 삭제할 데이터가 없는 상태에서 데이터를 삭제하려 하면 언더플로(Underflow)가 발생한다."],"ans":2,"exp":{"concept":"스택(Stack)은 한쪽 끝(Top)에서만 넣고 빼는 자료 구조다. 접시를 쌓으면 맨 위 접시부터 꺼내는 것처럼, 나중에 넣은 것이 먼저 나온다(LIFO). 그래서 포인터는 Top 하나만 있으면 되고, 앞(Front)과 뒤(Rear) 두 포인터를 쓰는 것은 큐(Queue)다.","choices":[{"verdict":"오답","why":"스택은 나중에 들어간 것이 먼저 나오는 LIFO(Last In First Out) 구조다. 맞는 설명이다."},{"verdict":"정답","why":"Head(Front)와 Tail(Rear) 두 포인터를 가지는 것은 큐(Queue)다. 스택은 Top 포인터 하나로 관리한다."},{"verdict":"오답","why":"스택은 입력과 출력이 한쪽 끝(Top)에서만 이루어지는 리스트다. 맞는 설명이다."},{"verdict":"오답","why":"빈 스택에서 삭제(Pop)를 시도하면 언더플로(Underflow)가 발생한다. 맞는 설명이다."}],"keywords":[{"term":"스택(Stack)","desc":"Top 한쪽에서만 삽입·삭제, LIFO"},{"term":"큐(Queue)","desc":"Rear에서 삽입, Front에서 삭제, FIFO"},{"term":"오버플로(Overflow)","desc":"가득 찬 스택에 삽입하려 할 때 발생"},{"term":"언더플로(Underflow)","desc":"빈 스택에서 삭제하려 할 때 발생"}],"memo":"포인터가 두 개(Front, Rear)면 큐, 하나(Top)면 스택이다."}},{"id":"written-2023-3-26","no":26,"unit":"소프트웨어 개발","q":"소프트웨어 설치 매뉴얼에 관한 설명 중 틀린 것은?","choices":["설치 과정에서 나타날 수 있는 예외상황과 관련된 내용은 별도로 구분해 설명한다.","설치 매뉴얼은 개발자를 기준으로 작성한다.","설치 시작부터 완료까지의 전 과정을 빠짐없이 순서대로 설명한다.","설치 매뉴얼에는 목차, 개요, 기본사항 등이 기본적으로 포함되어야 한다."],"ans":2,"exp":{"concept":"설치 매뉴얼은 사용자가 제품 소프트웨어를 처음부터 끝까지 혼자 설치할 수 있도록 안내하는 문서다. 읽는 사람은 개발자가 아니라 사용자이므로 사용자 입장에서 작성한다. 설치 순서, 예외 상황, 목차와 개요 같은 기본 사항을 빠짐없이 담는다.","choices":[{"verdict":"오답","why":"설치 중 생길 수 있는 예외 상황은 별도로 구분해 설명한다. 맞는 설명이다."},{"verdict":"정답","why":"설치 매뉴얼은 개발자가 아니라 사용자를 기준으로 작성한다."},{"verdict":"오답","why":"설치 시작부터 완료까지 전 과정을 빠짐없이 순서대로 설명한다. 맞는 설명이다."},{"verdict":"오답","why":"목차, 개요, 기본 사항 등은 설치 매뉴얼의 기본 구성 요소다. 맞는 설명이다."}],"keywords":[{"term":"설치 매뉴얼","desc":"사용자가 소프트웨어를 설치하는 과정을 안내하는 문서"},{"term":"사용자 매뉴얼","desc":"사용자가 소프트웨어를 사용하는 방법을 안내하는 문서"},{"term":"기본 사항","desc":"제품 개요, 문서 이력, 설치 환경 등 매뉴얼에 기본으로 들어가는 내용"},{"term":"예외 상황","desc":"설치 중 발생할 수 있는 오류와 대처 방법"}],"memo":"매뉴얼은 '읽는 사람' 기준이다. 설치·사용자 매뉴얼은 모두 사용자 중심이다."}},{"id":"written-2023-3-27","no":27,"unit":"소프트웨어 개발","q":"다음 그래프의 정점 A에서 출발하여 깊이 우선 탐색(DFS)으로 운행할 때의 결과는?<img class=\"q-img\" src=\"data/img/d475244f8596758476041415ba7bd9c4.png\" width=\"494\" alt=\"문항 원본 자료\">","choices":["ABECDFG","ABEFGCD","ABECFDG","ABCDEFG"],"ans":2,"exp":{"concept":"깊이 우선 탐색(DFS)은 한 정점에서 아직 방문하지 않은 이웃으로 계속 깊이 들어가고, 더 갈 곳이 없으면 바로 앞 정점으로 되돌아가 다른 길을 찾는다. 미로에서 한 길로 끝까지 가 보고 막히면 갈림길로 돌아오는 방식이다. 이웃을 고르는 순서가 정해져 있지 않으면 여러 결과가 나올 수 있으므로, 보기마다 DFS 규칙대로 갈 수 있는 순서인지 따져 본다. 그림의 간선은 A-B, A-C, A-D, B-C, B-E, C-D, C-F, D-F, E-F, F-G이다.","choices":[{"verdict":"오답","why":"A→B→E 다음에 E의 이웃 중 방문하지 않은 F가 있으므로 F로 가야 한다. E와 연결되지 않은 C로 갈 수 없어 DFS 순서가 아니다."},{"verdict":"정답","why":"A→B→E→F→G로 끝까지 내려가고, G에서 막히면 F로 돌아와 아직 방문하지 않은 C로 가고, C에서 D로 간다. DFS 규칙에 맞는 유일한 보기다."},{"verdict":"오답","why":"A→B→E 다음에는 E의 이웃 F로 가야 하는데 E와 연결되지 않은 C를 방문하므로 DFS 순서가 아니다."},{"verdict":"오답","why":"A→B→C→D 다음에 D의 이웃 중 방문하지 않은 F로 가야 한다. D와 연결되지 않은 E로 넘어가므로 DFS 순서가 아니다."}],"keywords":[{"term":"깊이 우선 탐색(DFS)","desc":"갈 수 있는 데까지 깊이 들어갔다가 막히면 되돌아오는 탐색, 스택(또는 재귀)으로 구현"},{"term":"너비 우선 탐색(BFS)","desc":"시작 정점에서 가까운 정점부터 차례로 방문하는 탐색, 큐로 구현"},{"term":"백트래킹","desc":"더 갈 곳이 없을 때 직전 정점으로 되돌아가는 동작"},{"term":"인접 정점","desc":"간선으로 직접 연결된 정점"}],"memo":"DFS 보기 검사법: 방문 순서에서 '다음 정점'이 '아직 갈 곳이 남은 가장 최근 정점'의 이웃인지 하나씩 확인한다.","doubt":"이웃 방문 순서가 문제에 정해져 있지 않다(이웃을 알파벳 순으로 고르면 ABCDFEG가 되며 이 순서는 보기에 없다). 다만 보기 중 DFS 규칙을 지키는 순서는 2번 하나뿐이므로 정답은 2번이다."}},{"id":"written-2023-3-28","no":28,"unit":"소프트웨어 개발","q":"여러 사람이 동시에 소스를 수정하는 것을 막고, 서로 다른 방향으로 진행된 개발 결과를 합치거나 변경 내용을 추적할 수 있는 소프트웨어 버전 관리 도구는 무엇인가?","choices":["RTS(Reliable Transfer Service)","RPC(Remote Procedure Call)","RCS(Revision Control System)","RVS(Relative Version System)"],"ans":3,"exp":{"concept":"버전 관리 도구는 소스 코드가 바뀐 기록을 남기고, 여러 사람이 작업한 결과를 관리하는 도구다. RCS(Revision Control System)는 파일을 수정할 때 잠금(Lock)을 걸어 다른 사람이 동시에 고치지 못하게 하고, 변경 이력을 추적하며 분기된 개발 내용을 병합할 수 있다.","choices":[{"verdict":"오답","why":"RTS(Reliable Transfer Service)는 신뢰성 있는 데이터 전송을 위한 통신 서비스로, 버전 관리 도구가 아니다."},{"verdict":"오답","why":"RPC(Remote Procedure Call)는 원격지의 함수를 로컬 함수처럼 호출하는 통신 방식(미들웨어)이다."},{"verdict":"정답","why":"RCS(Revision Control System)는 잠금으로 동시 수정을 막고, 변경 내용을 추적하며 분기된 개발 결과를 병합할 수 있는 버전 관리 도구다."},{"verdict":"오답","why":"RVS(Relative Version System)는 출제 범위의 표준 버전 관리 도구 이름이 아니다."}],"keywords":[{"term":"RCS(Revision Control System)","desc":"잠금 기능으로 동시 수정을 막는 파일 단위 버전 관리 도구"},{"term":"CVS(Concurrent Versions System)","desc":"서버-클라이언트 구조의 공유 폴더 방식 버전 관리 도구"},{"term":"SVN(Subversion)","desc":"CVS를 개선한 중앙 집중형 버전 관리 도구"},{"term":"Git","desc":"각 개발자가 전체 저장소를 복사해 쓰는 분산형 버전 관리 도구"}],"memo":"RCS의 R은 Revision(개정판). 버전 관리 도구 이름에는 Revision, Version, Concurrent 같은 단어가 들어간다."}},{"id":"written-2023-3-29","no":29,"unit":"소프트웨어 개발","q":"소프트웨어 패키징 도구를 활용할 때 고려해야 할 사항으로 옳지 않은 것은?","choices":["내부 콘텐츠에 대한 암호화 및 보안을 반드시 고려한다.","사용자 편의성을 위해 복잡성 및 비효율성 문제를 고려한다.","제품 소프트웨어의 종류에 적합한 암호화 알고리즘을 적용한다.","보안을 위해 이기종 연동은 고려하지 않아도 된다."],"ans":4,"exp":{"concept":"소프트웨어 패키징은 개발한 소프트웨어를 사용자가 설치해 쓸 수 있는 형태로 묶는 작업이다. 패키징 도구를 쓸 때는 콘텐츠 암호화와 보안, 사용자 편의성, 알맞은 암호화 알고리즘, 그리고 여러 종류의 콘텐츠와 단말기 사이의 연동(이기종 연동)까지 고려해야 한다.","choices":[{"verdict":"오답","why":"패키징 도구는 내부 콘텐츠의 암호화와 보안을 반드시 고려해야 한다. 맞는 설명이다."},{"verdict":"오답","why":"보안을 강화하다 보면 사용이 복잡해지거나 비효율적이 될 수 있으므로 사용자 편의성을 함께 고려한다. 맞는 설명이다."},{"verdict":"오답","why":"제품 소프트웨어의 종류에 맞는 암호화 알고리즘을 적용해야 한다. 맞는 설명이다."},{"verdict":"정답","why":"다양한 이기종 콘텐츠와 단말기 사이의 연동(DRM 연동 등)도 고려해야 한다. 이기종 연동을 고려하지 않아도 된다는 설명은 틀렸다."}],"keywords":[{"term":"소프트웨어 패키징","desc":"개발한 소프트웨어를 사용자가 설치할 수 있도록 묶는 작업"},{"term":"DRM(Digital Rights Management)","desc":"디지털 콘텐츠의 불법 복제와 사용을 막는 저작권 보호 기술"},{"term":"이기종 연동","desc":"서로 다른 종류의 시스템·단말기·콘텐츠가 함께 동작하도록 하는 것"},{"term":"패키징 도구","desc":"패키징 과정에서 암호화와 보안 기능을 적용하는 도구"}],"memo":"'고려하지 않아도 된다'처럼 무언가를 빼도 된다는 보기는 대부분 오답이다."}},{"id":"written-2023-3-30","no":30,"unit":"소프트웨어 개발","q":"클린 코드 작성 원칙에 관한 설명 중 틀린 것은?","choices":["코드가 다른 모듈에 미치는 영향이 최대화되도록 작성한다.","코드의 중복은 최소화한다.","코드는 간단하게 작성한다.","누구든지 쉽게 읽을 수 있도록 코드를 작성한다."],"ans":1,"exp":{"concept":"클린 코드(Clean Code)는 누구나 쉽게 읽고 고칠 수 있게 깔끔하게 작성한 코드다. 원칙은 가독성, 단순성, 의존성 배제, 중복성 최소화, 추상화다. 특히 한 모듈을 고쳤을 때 다른 모듈에 영향이 적어야 하므로 의존성과 영향은 최소화한다.","choices":[{"verdict":"정답","why":"클린 코드는 의존성을 배제해 다른 모듈에 미치는 영향을 최소화해야 한다. 최대화한다는 설명은 반대다."},{"verdict":"오답","why":"중복을 최소화하는 것(중복성 최소화)은 클린 코드 원칙이다. 맞는 설명이다."},{"verdict":"오답","why":"코드를 간단하게 작성하는 것(단순성)은 클린 코드 원칙이다. 맞는 설명이다."},{"verdict":"오답","why":"누구나 쉽게 읽을 수 있게 작성하는 것(가독성)은 클린 코드 원칙이다. 맞는 설명이다."}],"keywords":[{"term":"가독성","desc":"누구든지 쉽게 읽을 수 있게 작성"},{"term":"단순성","desc":"코드를 간단하게, 한 번에 한 가지만 처리하도록 작성"},{"term":"의존성 배제","desc":"다른 모듈에 미치는 영향을 최소화"},{"term":"중복성 최소화","desc":"중복된 코드를 제거"},{"term":"추상화","desc":"상위에서는 간략하게, 세부 내용은 하위에서 구현"}],"memo":"클린 코드 원칙은 '가단의중추(가독성, 단순성, 의존성 배제, 중복성 최소화, 추상화)'. 영향·의존은 언제나 최소화다."}},{"id":"written-2023-3-31","no":31,"unit":"소프트웨어 개발","q":"소프트웨어 품질 목표 가운데 쉽게 배워서 사용할 수 있는 정도를 의미하는 것은?","choices":["Integrity","Reliability","Correctness","Usability"],"ans":4,"exp":{"concept":"소프트웨어 품질 목표는 좋은 소프트웨어가 갖춰야 할 특성들이다. 그중 사용 용이성(Usability)은 사용자가 쉽게 배우고 편하게 쓸 수 있는 정도다. 처음 쓰는 스마트폰 앱도 설명서 없이 금방 쓸 수 있다면 사용 용이성이 높은 것이다.","choices":[{"verdict":"오답","why":"무결성(Integrity)은 허용되지 않은 사용이나 자료 변경을 막아 시스템을 보호하는 정도다."},{"verdict":"오답","why":"신뢰성(Reliability)은 정해진 기능을 오류 없이 정확하게 수행하는 정도다."},{"verdict":"오답","why":"정확성(Correctness)은 사용자의 요구 기능을 충족시키는 정도다."},{"verdict":"정답","why":"사용 용이성(Usability)은 사용자가 쉽게 배우고 사용할 수 있는 정도다."}],"keywords":[{"term":"정확성(Correctness)","desc":"사용자 요구 기능을 충족시키는 정도"},{"term":"신뢰성(Reliability)","desc":"기능을 오류 없이 수행하는 정도"},{"term":"무결성(Integrity)","desc":"허용되지 않은 사용과 변경을 막는 정도"},{"term":"사용 용이성(Usability)","desc":"쉽게 배우고 사용할 수 있는 정도"},{"term":"효율성(Efficiency)","desc":"최소한의 자원으로 기능을 수행하는 정도"}],"memo":"Usability = Use + Ability, '쓰기 쉬운 능력'으로 기억한다."}},{"id":"written-2023-3-32","no":32,"unit":"소프트웨어 개발","q":"다음 중 해싱 함수(Hashing Function)의 종류에 해당하지 않는 것은?","choices":["제산법(Division)","숫자 분석법(Digit Analysis)","제곱법(Mid-Square)","개방주소법(Open Addressing)"],"ans":4,"exp":{"concept":"해싱 함수는 키 값을 계산해 데이터를 저장할 주소(홈 주소)를 바로 구하는 함수다. 대표적으로 제산법, 제곱법, 폴딩법, 기수 변환법, 대수적 코딩법, 숫자 분석법, 무작위법이 있다. 서로 다른 키가 같은 주소를 받는 충돌이 생기면 개방 주소법이나 체이닝 같은 충돌 해결 기법을 쓴다.","choices":[{"verdict":"오답","why":"제산법(Division)은 키를 특정한 수(보통 해시표 크기보다 큰 수 중 가장 작은 소수)로 나눈 나머지를 주소로 쓰는 해싱 함수다."},{"verdict":"오답","why":"숫자 분석법(Digit Analysis)은 키의 각 자리 중 분포가 고른 자리를 골라 주소로 쓰는 해싱 함수다."},{"verdict":"오답","why":"제곱법(Mid-Square)은 키를 제곱한 값의 중간 부분을 주소로 쓰는 해싱 함수다."},{"verdict":"정답","why":"개방 주소법(Open Addressing)은 충돌이 났을 때 테이블의 다른 빈 자리를 찾아 저장하는 충돌 해결 기법이지 해싱 함수가 아니다."}],"keywords":[{"term":"제산법(Division)","desc":"키 mod 소수 = 주소"},{"term":"제곱법(Mid-Square)","desc":"키를 제곱한 값의 중간 자리를 주소로 사용"},{"term":"폴딩법(Folding)","desc":"키를 여러 부분으로 나눠 더하거나 XOR한 값을 주소로 사용"},{"term":"충돌(Collision)","desc":"서로 다른 키가 같은 주소를 갖는 현상"},{"term":"개방 주소법(Open Addressing)","desc":"충돌 시 다른 빈 버킷을 찾아 저장하는 충돌 해결 기법"}],"memo":"'~법'으로 끝나도 개방 주소법은 주소를 만드는 함수가 아니라 충돌 해결법이다."}},{"id":"written-2023-3-33","no":33,"unit":"소프트웨어 개발","q":"다음 중 블랙박스 테스트 기법과 거리가 먼 것은?","choices":["기초 경로 검사","원인 결과 그래프","경계값 분석","동치 클래스 분해"],"ans":1,"exp":{"concept":"블랙박스 테스트는 프로그램 내부를 보지 않고 입력과 출력만으로 기능이 맞는지 확인하는 테스트다. 화이트박스 테스트는 소스 코드 내부의 논리 흐름을 직접 보며 확인한다. 기초 경로 검사는 코드의 제어 흐름을 분석하므로 화이트박스 기법이다.","choices":[{"verdict":"정답","why":"기초 경로 검사(Basis Path Testing)는 제어 흐름 그래프로 코드의 실행 경로를 분석하는 화이트박스 테스트 기법이다."},{"verdict":"오답","why":"원인-결과 그래프(Cause-Effect Graph)는 입력(원인)과 출력(결과)의 관계를 분석하는 블랙박스 테스트 기법이다."},{"verdict":"오답","why":"경계값 분석(Boundary Value Analysis)은 입력 범위의 경계 부근 값을 테스트하는 블랙박스 테스트 기법이다."},{"verdict":"오답","why":"동치 클래스 분해(동치 분할, Equivalence Partitioning)는 입력을 같은 결과를 내는 그룹으로 나눠 대표값으로 테스트하는 블랙박스 테스트 기법이다."}],"keywords":[{"term":"블랙박스 테스트","desc":"동치 분할, 경계값 분석, 원인-결과 그래프, 오류 예측, 비교 검사"},{"term":"화이트박스 테스트","desc":"기초 경로 검사, 제어 구조 검사(조건, 루프, 데이터 흐름)"},{"term":"기초 경로 검사","desc":"McCabe의 순환 복잡도를 바탕으로 실행 경로를 테스트"},{"term":"경계값 분석","desc":"경계값 근처에서 오류가 잘 난다는 점을 이용한 테스트"}],"memo":"'경로, 조건, 루프'처럼 코드 안을 들여다보는 말이 있으면 화이트박스다."}},{"id":"written-2023-3-34","no":34,"unit":"소프트웨어 개발","q":"하향식 통합 시험에서 일시적으로 필요한 조건만 갖추어 임시로 제공되는 시험용 모듈은 무엇인가?","choices":["Function","Stub","Driver","Procedure"],"ans":2,"exp":{"concept":"통합 테스트에서 아직 만들어지지 않은 모듈은 임시 모듈로 대신한다. 하향식 통합은 위 모듈부터 테스트하므로 아직 없는 아래 모듈 자리에 스텁(Stub)을 둔다. 상향식 통합은 아래 모듈부터 테스트하므로 이를 호출해 줄 위 모듈 대신 드라이버(Driver)를 쓴다.","choices":[{"verdict":"오답","why":"Function은 특정 기능을 수행하는 함수를 뜻하는 일반 용어로, 통합 시험용 임시 모듈 이름이 아니다."},{"verdict":"정답","why":"스텁(Stub)은 하향식 통합 시험에서 아직 없는 하위 모듈을 대신하는, 필요한 조건만 갖춘 임시 시험용 모듈이다."},{"verdict":"오답","why":"드라이버(Driver)는 상향식 통합 시험에서 상위 모듈을 대신해 하위 모듈을 호출하는 임시 모듈이다."},{"verdict":"오답","why":"Procedure는 일련의 처리 절차(프로시저)를 뜻하는 일반 용어로, 통합 시험용 임시 모듈 이름이 아니다."}],"keywords":[{"term":"스텁(Stub)","desc":"하향식 통합에서 하위 모듈을 대신하는 임시 모듈"},{"term":"드라이버(Driver)","desc":"상향식 통합에서 상위 모듈을 대신하는 임시 모듈"},{"term":"하향식 통합","desc":"상위 모듈부터 하위로 내려가며 통합·테스트"},{"term":"상향식 통합","desc":"하위 모듈부터 클러스터 단위로 묶어 위로 올라가며 통합·테스트"}],"memo":"'하스상드(하향식은 스텁, 상향식은 드라이버)'로 외운다."}},{"id":"written-2023-3-35","no":35,"unit":"소프트웨어 개발","q":"다음 전위식(prefix)을 후위식(postfix)으로 바르게 나타낸 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p><code>- / * A + B C D E</code></p></div>","choices":["A B * C + D / E -","A B C + D / * E -","A B C + * D / E -","A B * C D / + E -"],"ans":3,"exp":{"concept":"전위식(prefix)은 연산자가 피연산자 앞에, 후위식(postfix)은 연산자가 피연산자 뒤에 오는 표기법이다. 전위식을 바꿀 때는 '연산자 피연산자1 피연산자2' 묶음을 안쪽부터 찾아 '피연산자1 피연산자2 연산자'로 바꾼다. 괄호를 쳐서 구조를 먼저 드러내면 실수가 줄어든다.","choices":[{"verdict":"오답","why":"A B * C +는 (A*B)+C를 뜻하므로 A와 (B+C)를 곱하는 원래 식과 구조가 다르다."},{"verdict":"오답","why":"A B C + D / *는 A*((B+C)/D)를 뜻하므로 (A*(B+C))/D인 원래 식과 연산 순서가 다르다."},{"verdict":"정답","why":"괄호로 묶으면 -( /( *(A, +(B,C)), D ), E )이다. 안쪽부터 후위식으로 바꾸면 B C + → A B C + * → A B C + * D / → A B C + * D / E -가 된다."},{"verdict":"오답","why":"A B * C D / + E -는 (A*B + C/D) - E를 뜻하므로 원래 식과 구조가 다르다."}],"keywords":[{"term":"전위식(Prefix)","desc":"연산자가 앞에 오는 표기, 예: + A B"},{"term":"중위식(Infix)","desc":"연산자가 피연산자 사이에 오는 표기, 예: A + B"},{"term":"후위식(Postfix)","desc":"연산자가 뒤에 오는 표기, 예: A B +"},{"term":"스택(Stack)","desc":"후위식 계산과 표기 변환에 쓰이는 자료 구조"}],"memo":"전위식은 '연산자 바로 뒤 두 덩어리'에 괄호를 치고, 괄호 안 연산자를 맨 뒤로 옮기면 후위식이 된다. 중위식으로는 ((A*(B+C))/D)-E다."}},{"id":"written-2023-3-36","no":36,"unit":"소프트웨어 개발","q":"정보 시스템 개발 단계에서 프로그래밍 언어를 선택할 때 고려할 사항과 가장 거리가 먼 것은?","choices":["컴파일러의 독창성","개발 정보 시스템의 특성","사용자의 요구사항","컴파일러의 가용성"],"ans":1,"exp":{"concept":"프로그래밍 언어를 고를 때는 그 언어로 만들 시스템의 특성, 사용자의 요구사항, 그리고 그 언어의 컴파일러를 실제로 구해 쓸 수 있는지(가용성) 등을 따진다. 컴파일러가 독창적인지는 개발과 관계가 없다.","choices":[{"verdict":"정답","why":"컴파일러의 독창성은 언어 선택 기준이 아니다. 컴파일러는 독창적인지보다 실제로 사용할 수 있는지가 중요하다."},{"verdict":"오답","why":"개발할 정보 시스템의 특성(업무용, 과학 계산용, 실시간 처리 등)은 언어 선택 시 고려할 사항이다."},{"verdict":"오답","why":"사용자의 요구사항은 언어 선택 시 고려할 사항이다."},{"verdict":"오답","why":"컴파일러의 가용성(해당 환경에서 컴파일러를 구해 쓸 수 있는지)은 언어 선택 시 고려할 사항이다."}],"keywords":[{"term":"컴파일러의 가용성","desc":"개발 환경에서 해당 언어의 컴파일러를 사용할 수 있는지"},{"term":"시스템 특성","desc":"업무 처리, 과학 계산, 실시간 처리 등 개발할 시스템의 성격"},{"term":"개발자의 언어 경험","desc":"개발자가 해당 언어를 얼마나 잘 다루는지"},{"term":"사용자 요구사항","desc":"사용자가 요구하는 기능과 환경"}],"memo":"'독창성'은 언어 선택 기준에 없다. 가용성(쓸 수 있느냐)과 헷갈리게 내는 함정이다."}},{"id":"written-2023-3-37","no":37,"unit":"소프트웨어 개발","q":"알고리즘의 시간 복잡도가 O(1)이라는 것은 무엇을 의미하는가?","choices":["알고리즘의 입력 데이터 수가 한 개임","알고리즘의 수행시간이 입력 데이터 수와 무관하게 일정함","알고리즘의 길이가 입력 데이터보다 작음","컴퓨터로 처리가 불가함"],"ans":2,"exp":{"concept":"시간 복잡도는 입력 데이터 수(n)가 늘어날 때 수행 시간이 얼마나 늘어나는지를 나타낸다. O(1)은 입력이 아무리 많아도 수행 시간이 항상 일정하다는 뜻이다. 배열에서 인덱스로 원소 하나를 바로 꺼내는 것이 대표적인 예다.","choices":[{"verdict":"오답","why":"O(1)은 입력이 한 개라는 뜻이 아니라, 입력 수와 관계없이 수행 시간이 일정하다는 뜻이다."},{"verdict":"정답","why":"O(1)은 상수 시간으로, 입력 데이터 수와 무관하게 수행 시간이 일정함을 의미한다."},{"verdict":"오답","why":"시간 복잡도는 알고리즘의 길이(코드 길이)와 입력 크기를 비교하는 개념이 아니다."},{"verdict":"오답","why":"O(1)은 가장 빠른 복잡도로, 처리가 불가능하다는 뜻이 전혀 아니다."}],"keywords":[{"term":"O(1)","desc":"상수 시간, 입력 크기와 무관하게 일정"},{"term":"O(log n)","desc":"로그 시간, 예: 이진 탐색"},{"term":"O(n)","desc":"선형 시간, 예: 순차 탐색"},{"term":"O(n log n)","desc":"예: 힙 정렬, 합병 정렬"},{"term":"O(n²)","desc":"예: 버블 정렬, 선택 정렬, 삽입 정렬"}],"memo":"O( ) 안의 식에 n이 없으면 n과 상관없이 일정하다는 뜻이다."}},{"id":"written-2023-3-38","no":38,"unit":"소프트웨어 개발","q":"인터페이스 보안을 위해 네트워크 영역에서 적용될 수 있는 것과 가장 거리가 먼 것은?","choices":["S-HTTP","SSL","IPSec","SMTP"],"ans":4,"exp":{"concept":"인터페이스 보안은 모듈이나 시스템 사이에 오가는 데이터를 보호하는 것이다. 네트워크 영역에서는 전송 구간을 암호화하는 IPSec, SSL/TLS, S-HTTP 같은 프로토콜을 적용한다. SMTP는 메일을 보내는 프로토콜일 뿐 자체 보안 기능이 없다.","choices":[{"verdict":"오답","why":"S-HTTP(Secure HTTP)는 웹에서 주고받는 메시지 단위로 암호화하는 보안 프로토콜로, 네트워크 영역 인터페이스 보안에 쓰인다."},{"verdict":"오답","why":"SSL(Secure Sockets Layer)은 전송 계층 위에서 데이터를 암호화하는 보안 프로토콜로, 네트워크 영역 인터페이스 보안에 쓰인다."},{"verdict":"오답","why":"IPSec은 네트워크 계층(IP)에서 패킷을 암호화하고 인증하는 보안 프로토콜로, 네트워크 영역 인터페이스 보안에 쓰인다."},{"verdict":"정답","why":"SMTP(Simple Mail Transfer Protocol)는 전자 우편을 전송하는 프로토콜로, 인터페이스 보안 기술이 아니다."}],"keywords":[{"term":"IPSec","desc":"네트워크 계층에서 IP 패킷을 암호화·인증하는 프로토콜"},{"term":"SSL/TLS","desc":"전송 계층과 응용 계층 사이에서 데이터를 암호화하는 프로토콜"},{"term":"S-HTTP","desc":"HTTP 메시지를 암호화하는 웹 보안 프로토콜"},{"term":"SMTP","desc":"전자 우편을 보내는 데 쓰는 프로토콜"}],"memo":"보안 프로토콜은 이름에 S(Secure)나 Sec가 들어간다. SMTP의 S는 Simple이다."}},{"id":"written-2023-3-39","no":39,"unit":"소프트웨어 개발","q":"다음 설명에 해당하는 용어로 옳은 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>소프트웨어 구조를 이루면서 다른 것들과 구별되는 독립적인 기능을 가진 단위이다.</li><li>하나 또는 몇 개의 논리적인 기능을 수행하기 위한 명령어들의 집합이라고 할 수도 있다.</li><li>서로 모여 하나의 완전한 프로그램으로 만들어질 수 있다.</li></ul></div>","choices":["저장소","통합 프로그램","모듈","데이터"],"ans":3,"exp":{"concept":"모듈(Module)은 소프트웨어를 이루는 독립적인 기능 단위다. 하나 또는 몇 개의 기능을 수행하는 명령어 묶음이며, 여러 모듈을 모아 하나의 완전한 프로그램을 만든다. 레고 블록 하나하나가 모듈이고, 블록을 조립해 완성한 작품이 프로그램이다.","choices":[{"verdict":"오답","why":"저장소(Repository)는 소스 코드나 산출물을 보관하는 곳이다."},{"verdict":"오답","why":"통합 프로그램은 여러 모듈을 합쳐 완성된 결과물이지, 그 구성 단위가 아니다."},{"verdict":"정답","why":"모듈은 독립적인 기능을 가진 소프트웨어 구성 단위로, 서로 모여 하나의 완전한 프로그램이 된다. 지문 내용과 같다."},{"verdict":"오답","why":"데이터는 프로그램이 처리하는 자료로, 명령어들의 집합이 아니다."}],"keywords":[{"term":"모듈(Module)","desc":"독립적인 기능을 가진 소프트웨어 구성 단위"},{"term":"모듈화(Modularity)","desc":"소프트웨어를 여러 모듈로 나누는 것"},{"term":"모듈 독립성","desc":"결합도는 낮고 응집도는 높을 때 커짐"},{"term":"컴포넌트(Component)","desc":"독립적으로 배포·교체할 수 있는 재사용 가능한 소프트웨어 부품"}],"memo":"'독립적인 기능 단위', '모여서 프로그램'이 나오면 모듈이다."}},{"id":"written-2023-3-40","no":40,"unit":"소프트웨어 개발","q":"다음과 같은 제어 흐름 그래프에서 McCabe의 cyclomatic 수는 얼마인가?<img class=\"q-img\" src=\"data/img/234a2bf4fd444af90634c157fd08ae42.png\" width=\"498\" alt=\"문항 원본 자료\">","choices":["3","4","5","6"],"ans":2,"exp":{"concept":"McCabe의 순환 복잡도(Cyclomatic Complexity)는 프로그램의 논리적 복잡도를 나타내는 수로, 제어 흐름 그래프에서 V(G) = E - N + 2(E: 간선 수, N: 노드 수)로 구한다. 그래프가 나누는 영역(바깥 영역 포함)의 수를 세어도 같은 값이 나온다. 이 값만큼의 독립 경로를 테스트하면 된다.","choices":[{"verdict":"오답","why":"간선 6개, 노드 4개이므로 6 - 4 + 2 = 4이며 3이 아니다."},{"verdict":"정답","why":"간선은 a→b, a→c, b→c, c→d, d→a, d→c로 6개, 노드는 a, b, c, d로 4개다. V(G) = 6 - 4 + 2 = 4다."},{"verdict":"오답","why":"5는 공식에 맞지 않는 값이다. V(G) = 6 - 4 + 2 = 4다."},{"verdict":"오답","why":"6은 간선 수 그 자체로, 노드 수를 빼고 2를 더하는 계산을 하지 않은 값이다."}],"keywords":[{"term":"순환 복잡도(Cyclomatic Complexity)","desc":"V(G) = E - N + 2, 독립 경로의 수"},{"term":"제어 흐름 그래프","desc":"프로그램의 실행 흐름을 노드와 간선으로 나타낸 그래프"},{"term":"기초 경로 검사","desc":"순환 복잡도만큼의 독립 경로를 테스트하는 화이트박스 기법"},{"term":"영역 계산법","desc":"그래프가 평면을 나누는 영역 수(바깥 포함)도 순환 복잡도와 같다"}],"memo":"공식은 '간선 - 노드 + 2'. 화살표를 하나씩 체크하며 세면 빠뜨리지 않는다."}},{"id":"written-2023-3-41","no":41,"unit":"데이터베이스 구축","q":"데이터베이스에서 병행제어의 목적에 해당하지 않는 것은?","choices":["사용자에 대한 응답시간 최소화","시스템 활용도 최대화","데이터베이스 공유 최소화","데이터베이스 일관성 유지"],"ans":3,"exp":{"concept":"병행 제어(Concurrency Control)는 여러 트랜잭션이 동시에 실행될 때 데이터베이스가 엉망이 되지 않도록 순서를 조절하는 기법이다. 목적은 데이터베이스 공유와 시스템 활용도를 최대화하고, 응답 시간을 최소화하며, 일관성을 유지하는 것이다.","choices":[{"verdict":"오답","why":"사용자에 대한 응답 시간 최소화는 병행 제어의 목적이다."},{"verdict":"오답","why":"시스템 활용도 최대화는 병행 제어의 목적이다."},{"verdict":"정답","why":"병행 제어는 여러 사용자가 데이터베이스를 동시에 쓰게 하려는 것이므로 공유를 최대화하는 것이 목적이다. 공유 최소화는 반대다."},{"verdict":"오답","why":"데이터베이스 일관성 유지는 병행 제어의 목적이다."}],"keywords":[{"term":"병행 제어(Concurrency Control)","desc":"동시에 실행되는 트랜잭션들이 데이터 일관성을 해치지 않도록 제어"},{"term":"로킹(Locking)","desc":"데이터에 잠금을 걸어 다른 트랜잭션의 접근을 막는 기법"},{"term":"타임 스탬프 순서","desc":"트랜잭션에 시간 표시를 부여해 그 순서대로 실행"},{"term":"낙관적 검증","desc":"트랜잭션 수행 중에는 검사하지 않고 끝날 때 검증"}],"memo":"병행 제어는 '공유와 활용도는 최대, 응답 시간은 최소, 일관성은 유지'. '공유 최소화'는 바로 오답이다."}},{"id":"written-2023-3-42","no":42,"unit":"데이터베이스 구축","q":"다음 중 SQL의 DDL문에 해당하지 않는 것은?","choices":["DELETE","ALTER","CREATE","DROP"],"ans":1,"exp":{"concept":"SQL은 용도에 따라 DDL(정의어), DML(조작어), DCL(제어어)로 나뉜다. DDL은 테이블 같은 구조를 만들고(CREATE), 바꾸고(ALTER), 없애는(DROP) 명령이다. DELETE는 테이블 구조는 그대로 두고 그 안의 데이터(행)를 지우므로 DML이다.","choices":[{"verdict":"정답","why":"DELETE는 테이블의 행(데이터)을 삭제하는 DML(데이터 조작어)이다."},{"verdict":"오답","why":"ALTER는 테이블 구조를 변경하는 DDL이다."},{"verdict":"오답","why":"CREATE는 테이블, 뷰, 인덱스 등을 생성하는 DDL이다."},{"verdict":"오답","why":"DROP은 테이블, 뷰 등 객체 자체를 삭제하는 DDL이다."}],"keywords":[{"term":"DDL(Data Definition Language)","desc":"CREATE, ALTER, DROP, TRUNCATE"},{"term":"DML(Data Manipulation Language)","desc":"SELECT, INSERT, UPDATE, DELETE"},{"term":"DCL(Data Control Language)","desc":"GRANT, REVOKE, COMMIT, ROLLBACK"},{"term":"DROP과 DELETE","desc":"DROP은 구조까지 삭제(DDL), DELETE는 데이터만 삭제(DML)"}],"memo":"DDL은 구조를 다루는 CREATE, ALTER, DROP. 지우는 명령이라도 데이터만 지우는 DELETE는 DML이다."}},{"id":"written-2023-3-43","no":43,"unit":"데이터베이스 구축","q":"다음 질의를 수행하기 위한 SQL 문으로 옳은 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>프로젝트번호(PNO) 1, 2, 3에서 근무하는 사원의 주민등록번호(JUNO)를 검색하라. (단, 사원 테이블(WORKS)은 프로젝트번호(PNO), 주민등록번호(JUNO) 필드로 구성되어 있다.)</p></div>","choices":["SELECT WORKS FROM JUNO WHERE PNO IN 1, 2, 3;","SELECT JUNO FROM WORKS WHERE PNO IN(1, 2, 3);","SELECT JUNO FROM WORKS WHERE PNO ON(1, 2, 3);","SELECT WORKS FROM JUNO WHERE PNO ON 1, 2, 3;"],"ans":2,"exp":{"concept":"SELECT 문의 기본 형식은 'SELECT 검색할 열 FROM 테이블 WHERE 조건'이다. 여러 값 중 하나와 같은지 확인할 때는 IN 연산자를 쓰고, 값 목록은 괄호로 감싼다. PNO IN (1, 2, 3)은 PNO = 1 OR PNO = 2 OR PNO = 3과 같다.","choices":[{"verdict":"오답","why":"SELECT 뒤에 테이블 이름(WORKS), FROM 뒤에 열 이름(JUNO)을 써서 자리가 뒤바뀌었고, IN 뒤의 값 목록에 괄호도 없다."},{"verdict":"정답","why":"WORKS 테이블에서 PNO가 1, 2, 3 중 하나인 행의 JUNO를 검색한다. 형식이 올바르다."},{"verdict":"오답","why":"ON은 조인 조건을 쓸 때 사용하는 키워드로, 값 목록 비교에 쓸 수 없다."},{"verdict":"오답","why":"SELECT와 FROM 뒤의 테이블과 열이 뒤바뀌었고, ON을 값 목록 비교에 잘못 썼다."}],"keywords":[{"term":"SELECT 기본 형식","desc":"SELECT 열 FROM 테이블 WHERE 조건"},{"term":"IN","desc":"값 목록 중 하나와 일치하는지 비교, 예: PNO IN (1, 2, 3)"},{"term":"BETWEEN","desc":"범위 비교, 예: PNO BETWEEN 1 AND 3"},{"term":"ON","desc":"JOIN할 때 결합 조건을 지정"}],"memo":"'SELECT 열 FROM 테이블' 순서를 먼저 확인하면 보기 절반이 바로 지워진다."}},{"id":"written-2023-3-44","no":44,"unit":"데이터베이스 구축","q":"관계 데이터베이스의 정규화에 관한 설명 중 옳지 않은 것은?","choices":["정규화의 목적은 각 릴레이션에 분산되어 있는 종속성을 하나의 릴레이션으로 통합하는 데 있다.","이상(Anomaly) 현상은 데이터들 사이에 존재하는 함수 종속이 하나의 원인이 될 수 있다.","정규화가 잘못되면 데이터의 불필요한 중복이 발생하여 릴레이션을 조작할 때 문제가 생길 수 있다.","정규화를 거치지 않을 경우 서로 다른 여러 종류의 정보를 하나의 릴레이션으로 표현하게 되어 그 릴레이션을 조작할 때 이상(Anomaly) 현상이 발생할 수 있다."],"ans":1,"exp":{"concept":"정규화(Normalization)는 하나의 릴레이션에 여러 종류의 정보가 섞여 생기는 중복과 이상 현상을 없애기 위해 릴레이션을 작게 쪼개는(분해하는) 과정이다. 큰 서랍 하나에 옷, 책, 장난감을 다 넣으면 정리가 어려우니 종류별 서랍으로 나누는 것과 같다.","choices":[{"verdict":"정답","why":"정규화는 종속성을 하나로 통합하는 것이 아니라, 하나의 릴레이션에 섞인 종속성을 분해해 여러 릴레이션으로 나누는 과정이다."},{"verdict":"오답","why":"함수 종속이 잘못 섞여 있으면 삽입·삭제·갱신 이상이 생길 수 있다. 맞는 설명이다."},{"verdict":"오답","why":"정규화가 잘못되면 데이터가 불필요하게 중복되어 조작할 때 문제가 생긴다. 맞는 설명이다."},{"verdict":"오답","why":"정규화하지 않으면 여러 종류의 정보가 한 릴레이션에 섞여 이상 현상이 생길 수 있다. 맞는 설명이다."}],"keywords":[{"term":"정규화(Normalization)","desc":"이상 현상을 없애기 위해 릴레이션을 분해하는 과정"},{"term":"이상(Anomaly)","desc":"중복 때문에 생기는 삽입 이상, 삭제 이상, 갱신 이상"},{"term":"함수 종속(Functional Dependency)","desc":"X 값이 정해지면 Y 값이 하나로 정해지는 관계(X → Y)"},{"term":"반정규화(Denormalization)","desc":"성능을 위해 정규화된 릴레이션을 일부러 합치거나 중복시키는 것"}],"memo":"정규화 = 분해. '통합'이라는 말이 보이면 정규화 설명이 아니다."}},{"id":"written-2023-3-45","no":45,"unit":"데이터베이스 구축","q":"다음 보기에서 DML에 해당하는 것만을 모두 고른 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul class=\"is-labeled\"><li>ㄱ. SELECT</li><li>ㄴ. UPDATE</li><li>ㄷ. INSERT</li><li>ㄹ. GRANT</li></ul></div>","choices":["㉠, ㉡, ㉢, ㉣","㉠, ㉢, ㉣","㉠, ㉡, ㉢","㉠, ㉡, ㉣"],"ans":3,"exp":{"concept":"DML(데이터 조작어)은 테이블 안의 데이터를 검색, 삽입, 수정, 삭제하는 명령이다. SELECT, INSERT, UPDATE, DELETE 네 가지가 있다. GRANT는 사용자에게 권한을 주는 DCL(데이터 제어어)이다.","choices":[{"verdict":"오답","why":"GRANT(ㄹ)는 권한을 부여하는 DCL이므로 DML에 포함하면 안 된다."},{"verdict":"오답","why":"UPDATE(ㄴ)가 빠지고 DCL인 GRANT(ㄹ)가 들어가 틀렸다."},{"verdict":"정답","why":"SELECT(ㄱ), UPDATE(ㄴ), INSERT(ㄷ)가 DML이고 GRANT(ㄹ)는 DCL이다."},{"verdict":"오답","why":"INSERT(ㄷ)가 빠지고 DCL인 GRANT(ㄹ)가 들어가 틀렸다."}],"keywords":[{"term":"DML","desc":"SELECT, INSERT, UPDATE, DELETE"},{"term":"DCL","desc":"GRANT, REVOKE, COMMIT, ROLLBACK"},{"term":"GRANT","desc":"사용자에게 권한을 부여"},{"term":"REVOKE","desc":"부여한 권한을 회수"}],"memo":"DML은 '셀인업델(SELECT, INSERT, UPDATE, DELETE)'. GRANT/REVOKE는 권한이라 DCL이다."}},{"id":"written-2023-3-46","no":46,"unit":"데이터베이스 구축","q":"다음 중 분산 데이터베이스의 투명성(Transparency)에 해당하지 않는 것은?","choices":["Media Access Transparency","Replication Transparency","Failure Transparency","Location Transparency"],"ans":1,"exp":{"concept":"분산 데이터베이스의 투명성(Transparency)은 데이터가 여러 곳에 흩어져 있어도 사용자는 한 곳에 있는 것처럼 신경 쓰지 않고 쓸 수 있게 하는 성질이다. 대표적으로 위치, 복제, 병행, 장애 투명성이 있다. 매체 접근 투명성은 분산 데이터베이스의 투명성에 속하지 않는다.","choices":[{"verdict":"정답","why":"Media Access Transparency(매체 접근 투명성)는 분산 데이터베이스의 투명성 종류에 속하지 않는다."},{"verdict":"오답","why":"복제 투명성(Replication Transparency)은 같은 데이터가 여러 곳에 복제되어 있어도 사용자는 하나처럼 쓰게 하는 성질이다."},{"verdict":"오답","why":"장애 투명성(Failure Transparency)은 일부 사이트나 통신망에 장애가 나도 데이터 무결성을 지키며 처리하게 하는 성질이다."},{"verdict":"오답","why":"위치 투명성(Location Transparency)은 데이터가 실제 어디에 있는지 몰라도 논리적인 이름만으로 접근하게 하는 성질이다."}],"keywords":[{"term":"위치 투명성(Location)","desc":"데이터의 물리적 위치를 몰라도 접근 가능"},{"term":"복제 투명성(Replication)","desc":"데이터가 여러 곳에 복제되어 있어도 하나처럼 사용"},{"term":"병행 투명성(Concurrency)","desc":"여러 트랜잭션이 동시에 실행되어도 결과가 일관됨"},{"term":"장애 투명성(Failure)","desc":"장애가 발생해도 무결성을 유지하며 처리"}],"memo":"분산 DB 투명성은 '위복병장(위치, 복제, 병행, 장애)'."}},{"id":"written-2023-3-47","no":47,"unit":"데이터베이스 구축","q":"트랜잭션을 수행하는 도중 장애가 발생하여 손상된 데이터베이스를 손상 이전의 정상적인 상태로 되돌리는 작업은?","choices":["Restart","Commit","Abort","Recovery"],"ans":4,"exp":{"concept":"회복(Recovery)은 트랜잭션 수행 중 장애가 나서 데이터베이스가 손상되었을 때, 로그나 백업을 이용해 손상 이전의 올바른 상태로 되돌리는 작업이다. 컴퓨터가 멈췄을 때 마지막으로 저장한 상태에서 다시 이어 가는 것과 비슷하다.","choices":[{"verdict":"오답","why":"Restart(재시작)는 철회된 트랜잭션을 다시 실행하는 것으로, 손상된 데이터베이스를 정상 상태로 되돌리는 작업 자체를 말하지 않는다."},{"verdict":"오답","why":"Commit(완료)은 트랜잭션이 성공적으로 끝나 변경 내용을 데이터베이스에 영구히 반영하는 연산이다."},{"verdict":"오답","why":"Abort(철회)는 트랜잭션 실행이 실패해 중단된 상태 또는 그 트랜잭션을 취소하는 것이다."},{"verdict":"정답","why":"Recovery(회복)는 장애로 손상된 데이터베이스를 손상 이전의 정상적인 상태로 복구하는 작업이다."}],"keywords":[{"term":"회복(Recovery)","desc":"장애로 손상된 DB를 정상 상태로 복구"},{"term":"REDO","desc":"로그를 보고 완료된 트랜잭션의 변경을 다시 반영"},{"term":"UNDO","desc":"로그를 보고 완료되지 않은 트랜잭션의 변경을 취소"},{"term":"Commit","desc":"트랜잭션의 변경을 확정"},{"term":"Rollback","desc":"트랜잭션의 변경을 취소하고 이전 상태로 되돌림"}],"memo":"'손상 이전 상태로 되돌린다' = 회복(Recovery). Commit은 확정, Abort는 철회다."}},{"id":"written-2023-3-48","no":48,"unit":"데이터베이스 구축","q":"릴레이션 R의 차수(Degree)가 3이고 카디널리티(Cardinality)가 3이며, 릴레이션 S의 차수가 4이고 카디널리티가 4일 때, 두 릴레이션을 카티션 프로덕트(Cartesian Product)한 결과 릴레이션의 차수와 카디널리티는 얼마인가?","choices":["4, 4","7, 7","7, 12","12, 12"],"ans":3,"exp":{"concept":"릴레이션에서 차수(Degree)는 속성(열)의 개수, 카디널리티(Cardinality)는 튜플(행)의 개수다. 카티션 프로덕트(R × S)는 R의 모든 행과 S의 모든 행을 하나씩 짝지어 붙인다. 그래서 열은 더해지고(차수 합), 행은 곱해진다(카디널리티 곱).","choices":[{"verdict":"오답","why":"4, 4는 S의 차수와 카디널리티일 뿐, 카티션 프로덕트의 결과가 아니다."},{"verdict":"오답","why":"7, 7은 차수와 카디널리티를 모두 더한 값이다. 카디널리티는 곱해야 한다."},{"verdict":"정답","why":"차수 = 3 + 4 = 7, 카디널리티 = 3 × 4 = 12이다."},{"verdict":"오답","why":"12, 12는 차수와 카디널리티를 모두 곱한 값이다. 차수는 더해야 한다."}],"keywords":[{"term":"차수(Degree)","desc":"속성(열)의 개수"},{"term":"카디널리티(Cardinality)","desc":"튜플(행)의 개수"},{"term":"카티션 프로덕트(Cartesian Product)","desc":"두 릴레이션의 모든 튜플을 짝지어 연결하는 연산, 기호 ×"},{"term":"결과 크기","desc":"차수는 합, 카디널리티는 곱"}],"memo":"카티션 프로덕트는 '열은 더하고 행은 곱한다'."}},{"id":"written-2023-3-49","no":49,"unit":"데이터베이스 구축","q":"학적 테이블에서 전화번호가 Null 값이 아닌 학생명을 모두 검색하려고 할 때, 옳은 SQL 구문은?","choices":["SELECT 학생명 FROM 학적 WHERE 전화번호 DON’T NULL;","SELECT 학생명 FROM 학적 WHERE 전화번호 IS NULL;","SELECT 학생명 FROM 학적 WHERE 전화번호 IS NOT NULL;","SELECT 학생명 FROM 학적 WHERE 전화번호 != NOT NULL;"],"ans":3,"exp":{"concept":"SQL에서 NULL은 '값이 없음'을 뜻하므로 = 나 != 같은 비교 연산자로는 확인할 수 없다. 대신 IS NULL(값이 없다), IS NOT NULL(값이 있다)을 쓴다. 전화번호가 NULL이 아닌 학생을 찾으려면 '전화번호 IS NOT NULL'이라고 쓴다.","choices":[{"verdict":"오답","why":"DON'T NULL은 SQL에 없는 문법이다."},{"verdict":"오답","why":"IS NULL은 전화번호가 없는(NULL인) 학생을 찾는 조건이라 문제와 반대다."},{"verdict":"정답","why":"IS NOT NULL은 값이 NULL이 아닌 행을 찾는 올바른 조건이다."},{"verdict":"오답","why":"!= NOT NULL은 SQL 문법에 맞지 않는다. NULL 여부는 IS NULL, IS NOT NULL로만 검사한다."}],"keywords":[{"term":"NULL","desc":"값이 없거나 알 수 없음을 나타내는 특수 값"},{"term":"IS NULL","desc":"값이 NULL인 행을 찾는 조건"},{"term":"IS NOT NULL","desc":"값이 NULL이 아닌 행을 찾는 조건"},{"term":"NULL과 비교 연산","desc":"= NULL, != NULL로는 원하는 결과를 얻을 수 없다"}],"memo":"NULL 검사는 언제나 IS. 'IS NULL / IS NOT NULL' 두 개만 기억한다."}},{"id":"written-2023-3-50","no":50,"unit":"데이터베이스 구축","q":"다음 SQL 문장은 무엇을 의미하는가?<pre class=\"q-sql\"><code class=\"language-sql\">INSERT INTO 컴퓨터과테이블(학번, 이름, 학년)\nSELECT 학번, 이름, 학년\nFROM 학생테이블\nWHERE 학과='컴퓨터'</code></pre>","choices":["학생테이블에 학과가 검퓨터인 사람의 학번, 이름, 학년을 삽입한다.","학생테이블에서 학과가 컴퓨터인 사람의 학번, 이름, 학년을 검색해 컴퓨터과테이블에 삽입한다.","학생테이블에서 학과가 컴퓨터인 사람의 학번, 이름, 학년을 검색한다.","컴퓨터과테이블에서 학과가 컴퓨터인 사람의 학번, 이름, 학년을 검색해 학생테이블에 삽입한다."],"ans":2,"exp":{"concept":"INSERT INTO 테이블(열들) SELECT ... 형식은 다른 테이블에서 검색한 결과를 그대로 새 테이블에 넣는 문장이다. VALUES 대신 SELECT 문을 쓰면 검색 결과의 여러 행을 한 번에 삽입할 수 있다. 이 문장은 학생테이블에서 학과가 '컴퓨터'인 학생의 학번, 이름, 학년을 골라 컴퓨터과테이블에 넣는다.","choices":[{"verdict":"오답","why":"학생테이블에 삽입하는 것이 아니라, 학생테이블에서 검색한 결과를 컴퓨터과테이블에 삽입한다."},{"verdict":"정답","why":"SELECT로 학생테이블에서 학과='컴퓨터'인 학생의 학번, 이름, 학년을 검색하고, INSERT INTO로 그 결과를 컴퓨터과테이블에 삽입한다."},{"verdict":"오답","why":"검색만 하는 것이 아니라 INSERT INTO로 검색 결과를 컴퓨터과테이블에 삽입까지 한다."},{"verdict":"오답","why":"방향이 반대다. 검색 대상은 학생테이블이고 삽입 대상은 컴퓨터과테이블이다."}],"keywords":[{"term":"INSERT INTO ~ VALUES","desc":"값을 직접 지정해 한 행을 삽입"},{"term":"INSERT INTO ~ SELECT","desc":"다른 테이블의 검색 결과를 삽입"},{"term":"FROM","desc":"데이터를 가져올(검색할) 테이블"},{"term":"WHERE","desc":"검색할 행의 조건"}],"memo":"INSERT INTO 뒤가 '넣는 곳', FROM 뒤가 '가져오는 곳'이다."}},{"id":"written-2023-3-51","no":51,"unit":"데이터베이스 구축","q":"아래 두 릴레이션 중 외래키로 쓰인 속성은 무엇인가? (단, 밑줄 친 속성은 기본키이다.)<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>과목(<u>과목번호</u>, 과목명)<br>수강(<u>수강번호</u>, 학번, 과목번호, 학기)</p></div>","choices":["학번","수강번호","과목번호","과목명"],"ans":3,"exp":{"concept":"외래키(Foreign Key)는 한 릴레이션의 속성이 다른 릴레이션의 기본키를 참조할 때 그 속성을 말한다. 두 테이블을 이어 주는 연결 고리 역할을 한다. 수강 릴레이션의 과목번호는 과목 릴레이션의 기본키인 과목번호를 참조하므로 외래키다.","choices":[{"verdict":"오답","why":"학번은 과목 릴레이션의 기본키가 아니므로, 주어진 두 릴레이션(과목, 수강) 사이에서 다른 릴레이션의 기본키를 참조하는 속성이 아니다."},{"verdict":"오답","why":"수강번호는 수강 릴레이션 자신의 기본키다."},{"verdict":"정답","why":"수강 릴레이션의 과목번호는 과목 릴레이션의 기본키인 과목번호를 참조하므로 외래키다."},{"verdict":"오답","why":"과목명은 과목 릴레이션의 일반 속성으로, 다른 릴레이션의 기본키를 참조하지 않는다."}],"keywords":[{"term":"기본키(Primary Key)","desc":"튜플을 유일하게 식별하는 키, NULL과 중복 불가"},{"term":"외래키(Foreign Key)","desc":"다른 릴레이션의 기본키를 참조하는 속성"},{"term":"참조 무결성","desc":"외래키 값은 참조하는 릴레이션의 기본키 값이거나 NULL이어야 한다"},{"term":"후보키(Candidate Key)","desc":"유일성과 최소성을 만족하는 키"}],"memo":"두 테이블에 '똑같은 이름'으로 나오고 한쪽에서 기본키인 속성이 외래키다."}},{"id":"written-2023-3-52","no":52,"unit":"데이터베이스 구축","q":"스키마의 종류 가운데 조직이나 기관의 총괄적 입장에서 바라본 데이터베이스의 전체적인 논리적 구조로, 모든 응용 프로그램이나 사용자들이 필요로 하는 데이터를 종합한 조직 전체의 데이터베이스 구조를 뜻하는 것은?","choices":["개념 스키마","관계 스키마","외부 스키마","내부 스키마"],"ans":1,"exp":{"concept":"데이터베이스 스키마는 보는 관점에 따라 외부, 개념, 내부의 3단계로 나뉜다. 개념 스키마는 조직 전체의 입장에서 본 데이터베이스의 전체 논리적 구조로, 모든 사용자와 응용 프로그램이 필요로 하는 데이터를 종합한 것이다. 보통 '스키마'라고 하면 개념 스키마를 뜻한다.","choices":[{"verdict":"정답","why":"개념 스키마(Conceptual Schema)는 조직 전체 관점에서 본 데이터베이스의 전체적인 논리적 구조로, 지문 설명과 같다."},{"verdict":"오답","why":"관계 스키마(릴레이션 스키마)는 릴레이션 하나의 이름과 속성들로 이루어진 구조를 말하며, 3단계 스키마의 종류가 아니다."},{"verdict":"오답","why":"외부 스키마(External Schema)는 개별 사용자나 응용 프로그램 관점에서 본 데이터베이스의 일부 논리적 구조로, 서브 스키마라고도 한다."},{"verdict":"오답","why":"내부 스키마(Internal Schema)는 물리적 저장 장치 관점에서 본 데이터베이스 구조로, 레코드 형식과 저장 방법 등을 정의한다."}],"keywords":[{"term":"외부 스키마","desc":"사용자·응용 프로그래머 관점의 논리적 구조, 서브 스키마"},{"term":"개념 스키마","desc":"조직 전체 관점의 논리적 구조, 하나만 존재"},{"term":"내부 스키마","desc":"물리적 저장 장치 관점의 구조"},{"term":"데이터 독립성","desc":"한 단계 스키마를 바꿔도 다른 단계에 영향이 없는 성질"}],"memo":"'조직 전체', '총괄적'이 나오면 개념 스키마, '개별 사용자'면 외부, '물리적 저장'이면 내부."}},{"id":"written-2023-3-53","no":53,"unit":"데이터베이스 구축","q":"데이터베이스의 릴레이션에 관한 설명 중 틀린 것은?","choices":["모든 속성 값은 원자값(Atomic Value)을 갖는다.","하나의 릴레이션에서 튜플은 특정한 순서를 갖는다.","각 속성은 릴레이션 내에서 유일한 이름을 갖는다.","모든 튜플은 서로 다른 값을 갖는다."],"ans":2,"exp":{"concept":"릴레이션(테이블)에는 지켜야 할 특성이 있다. 튜플은 모두 달라야 하고(유일성), 튜플 사이와 속성 사이에는 순서가 없으며(무순서성), 속성 값은 더 쪼갤 수 없는 원자값이어야 한다(원자성). 행의 순서를 바꿔도 같은 릴레이션이다.","choices":[{"verdict":"오답","why":"속성 값은 더 이상 나눌 수 없는 원자값(Atomic Value)이어야 한다. 맞는 설명이다."},{"verdict":"정답","why":"릴레이션의 튜플 사이에는 순서가 없다(튜플의 무순서성). 특정 순서를 갖는다는 설명은 틀렸다."},{"verdict":"오답","why":"각 속성은 릴레이션 안에서 유일한 이름을 가진다. 맞는 설명이다."},{"verdict":"오답","why":"릴레이션에 똑같은 튜플이 두 개 있을 수 없다(튜플의 유일성). 맞는 설명이다."}],"keywords":[{"term":"튜플의 유일성","desc":"모든 튜플은 서로 달라야 한다"},{"term":"튜플의 무순서성","desc":"튜플 사이에 순서가 없다"},{"term":"속성의 원자성","desc":"속성 값은 원자값이다"},{"term":"속성의 무순서성","desc":"속성 사이에도 순서가 없다"}],"memo":"릴레이션 특성은 '튜플은 유일·무순서, 속성은 원자·무순서'."}},{"id":"written-2023-3-54","no":54,"unit":"데이터베이스 구축","q":"객체 지향 기법에서 유사한 객체들을 하나 이상 묶어 공통된 특성을 표현한 것은 무엇인가?","choices":["클래스","추상화","메소드","메시지"],"ans":1,"exp":{"concept":"클래스(Class)는 공통된 속성과 연산(메소드)을 가진 객체들을 하나로 묶어 표현한 틀이다. 붕어빵 틀이 클래스이고, 그 틀로 찍어 낸 붕어빵 하나하나가 객체(인스턴스)다.","choices":[{"verdict":"정답","why":"클래스는 유사한 객체들을 묶어 공통된 속성과 연산을 정의한 것이다."},{"verdict":"오답","why":"추상화(Abstraction)는 불필요한 세부 사항을 없애고 핵심적인 특징만 뽑아 내는 원리다."},{"verdict":"오답","why":"메소드(Method)는 객체가 수행하는 연산(동작)을 정의한 함수다."},{"verdict":"오답","why":"메시지(Message)는 객체에게 어떤 행위를 하도록 보내는 명령이다."}],"keywords":[{"term":"클래스(Class)","desc":"공통 속성과 연산을 가진 객체들의 틀"},{"term":"객체(Object)","desc":"데이터와 연산을 함께 가진 독립된 실체"},{"term":"인스턴스(Instance)","desc":"클래스로 생성된 실제 객체"},{"term":"추상화(Abstraction)","desc":"핵심 특징만 뽑아 내고 세부는 감추는 원리"}],"memo":"'유사한 객체를 묶은 틀'은 클래스, '핵심만 뽑아 내기'는 추상화."}},{"id":"written-2023-3-55","no":55,"unit":"데이터베이스 구축","q":"병렬 데이터베이스 환경에서 수평 분할에 활용되는 분할 기법에 해당하지 않는 것은?","choices":["범위 분할","라운드-로빈","해시 분할","예측 분할"],"ans":4,"exp":{"concept":"병렬 데이터베이스에서 수평 분할은 한 테이블의 행(튜플)들을 여러 디스크나 노드로 나누어 저장하는 것이다. 나누는 방법으로 라운드-로빈, 범위 분할, 해시 분할 등이 있다. 예측 분할이라는 기법은 없다.","choices":[{"verdict":"오답","why":"범위 분할(Range Partitioning)은 특정 속성 값의 범위에 따라 행을 나누는 수평 분할 기법이다."},{"verdict":"오답","why":"라운드-로빈(Round-Robin)은 행을 각 분할에 돌아가며 차례로 고르게 배치하는 수평 분할 기법이다."},{"verdict":"오답","why":"해시 분할(Hash Partitioning)은 해시 함수 값에 따라 행을 나누는 수평 분할 기법이다."},{"verdict":"정답","why":"예측 분할은 수평 분할 기법에 해당하지 않는다."}],"keywords":[{"term":"수평 분할","desc":"행(튜플) 단위로 나누어 저장"},{"term":"수직 분할","desc":"열(속성) 단위로 나누어 저장"},{"term":"라운드-로빈","desc":"행을 분할마다 차례로 돌아가며 배치"},{"term":"범위 분할","desc":"값의 범위 기준으로 배치"},{"term":"해시 분할","desc":"해시 함수 결과 기준으로 배치"}],"memo":"수평 분할 기법은 '라운드-로빈, 범위, 해시' 세 가지를 기본으로 외운다."}},{"id":"written-2023-3-56","no":56,"unit":"데이터베이스 구축","q":"아래 조건을 모두 충족하는 정규형은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>테이블 R의 모든 도메인이 원자값만으로 이루어져 있다.</li><li>테이블 R에서 키가 아닌 모든 필드는 키에 함수적으로 종속되고, 키의 부분집합이 결정자가 되는 부분 종속은 존재하지 않는다.</li><li>테이블 R에 있는 모든 함수적 종속에서 결정자는 후보키이다.</li></ul></div>","choices":["제3정규형","제2정규형","BCNF","제1정규형"],"ans":3,"exp":{"concept":"정규형은 단계가 올라갈수록 조건이 하나씩 추가된다. 1NF는 원자값, 2NF는 부분 함수 종속 제거, 3NF는 이행 함수 종속 제거, BCNF는 모든 결정자가 후보키인 상태다. 지문은 1NF와 2NF 조건에 더해 '모든 결정자가 후보키'라는 BCNF 조건까지 만족한다.","choices":[{"verdict":"오답","why":"제3정규형은 이행 함수 종속을 제거한 상태로, 모든 결정자가 후보키라는 조건까지 요구하지 않는다."},{"verdict":"오답","why":"제2정규형은 부분 함수 종속까지만 제거한 상태로, 셋째 조건(모든 결정자가 후보키)을 보장하지 않는다."},{"verdict":"정답","why":"원자값(1NF), 부분 종속 없음(2NF), 모든 결정자가 후보키(BCNF)를 모두 만족하므로 BCNF다."},{"verdict":"오답","why":"제1정규형은 첫째 조건(원자값)만 만족하는 상태다."}],"keywords":[{"term":"1NF","desc":"모든 도메인이 원자값"},{"term":"2NF","desc":"부분 함수 종속 제거"},{"term":"3NF","desc":"이행 함수 종속 제거"},{"term":"BCNF","desc":"결정자이면서 후보키가 아닌 것 제거, 모든 결정자가 후보키"},{"term":"4NF / 5NF","desc":"다치 종속 제거 / 조인 종속 제거"}],"memo":"정규화 순서는 '도부이결다조(도메인 원자값, 부분 종속, 이행 종속, 결정자, 다치 종속, 조인 종속)'."}},{"id":"written-2023-3-57","no":57,"unit":"데이터베이스 구축","q":"하나의 애트리뷰트가 취할 수 있는 원자값들의 집합을 뜻하는 것은?","choices":["엔티티","도메인","다형성","튜플"],"ans":2,"exp":{"concept":"도메인(Domain)은 하나의 속성(애트리뷰트)이 가질 수 있는 원자값들의 집합이다. 예를 들어 '성별' 속성의 도메인은 {남, 여}, '학년' 속성의 도메인은 {1, 2, 3, 4}다.","choices":[{"verdict":"오답","why":"엔티티(Entity, 개체)는 데이터베이스에 표현하려는 현실 세계의 대상(사람, 사물, 사건 등)이다."},{"verdict":"정답","why":"도메인은 하나의 애트리뷰트가 취할 수 있는 같은 타입의 원자값들의 집합이다."},{"verdict":"오답","why":"다형성(Polymorphism)은 객체지향에서 같은 메시지에 객체마다 다르게 반응하는 성질이다."},{"verdict":"오답","why":"튜플(Tuple)은 릴레이션의 한 행이다."}],"keywords":[{"term":"도메인(Domain)","desc":"속성이 가질 수 있는 원자값들의 집합"},{"term":"속성(Attribute)","desc":"릴레이션의 열, 데이터의 가장 작은 논리적 단위"},{"term":"튜플(Tuple)","desc":"릴레이션의 행"},{"term":"엔티티(Entity)","desc":"현실 세계에서 표현하려는 대상"}],"memo":"도메인 = 속성이 '가질 수 있는 값의 범위'. 학년 속성에 5가 들어갈 수 없는 이유가 도메인이다."}},{"id":"written-2023-3-58","no":58,"unit":"데이터베이스 구축","q":"분산 데이터베이스 시스템에 대한 설명 중 틀린 것은?","choices":["물리적으로 분산되어 있는 데이터베이스 시스템을 논리적으로는 하나의 데이터베이스 시스템처럼 사용할 수 있게 한 것이다.","물리적으로 분산되어 지역별로 필요한 데이터를 처리할 수 있는 지역 컴퓨터(Local Computer)를 분산 처리기(Distributed Processor)라고 부른다.","사용자가 데이터베이스의 분산 여부를 인식할 수 있도록 분산 투명성(Distribution Transparency)은 배제되어야 한다.","분산 데이터베이스 시스템을 위한 통신 네트워크 구조는 데이터 통신에 영향을 미치므로 효율적으로 설계되어야 한다."],"ans":3,"exp":{"concept":"분산 데이터베이스는 여러 곳에 흩어진 데이터베이스를 하나의 데이터베이스처럼 쓰게 하는 시스템이다. 핵심은 사용자가 데이터가 어디에 어떻게 나뉘어 있는지 몰라도 되게 하는 분산 투명성이다. 그래서 투명성은 배제하는 것이 아니라 반드시 보장해야 한다.","choices":[{"verdict":"오답","why":"물리적으로 분산된 데이터베이스를 논리적으로 하나처럼 사용하게 한 것이 분산 데이터베이스다. 맞는 설명이다."},{"verdict":"오답","why":"지역별로 필요한 데이터를 처리할 수 있는 지역 컴퓨터를 분산 처리기(Distributed Processor)라고 한다. 맞는 설명이다."},{"verdict":"정답","why":"분산 데이터베이스는 사용자가 분산 여부를 의식하지 않도록 분산 투명성을 보장해야 한다. 투명성을 배제해야 한다는 설명은 반대다."},{"verdict":"오답","why":"통신 네트워크 구조는 데이터 통신 성능에 영향을 미치므로 효율적으로 설계해야 한다. 맞는 설명이다."}],"keywords":[{"term":"분산 처리기(Distributed Processor)","desc":"지리적으로 분산되어 자체 처리 능력을 가진 지역 컴퓨터"},{"term":"분산 데이터베이스","desc":"각 지역에 놓인 데이터베이스"},{"term":"통신 네트워크","desc":"분산 처리기들을 연결해 논리적으로 하나의 시스템처럼 동작하게 함"},{"term":"분산 투명성","desc":"사용자가 데이터의 분산 사실을 의식하지 않고 사용하게 하는 성질"}],"memo":"분산 DB에서 투명성은 '보장'하는 것이다. '배제', '인식할 수 있도록'이 나오면 오답이다."}},{"id":"written-2023-3-59","no":59,"unit":"데이터베이스 구축","q":"아래 표와 같은 판매실적 테이블에서 서울지역만을 대상으로 판매액 내림차순으로 지점명과 판매액을 출력하려고 한다. 가장 적절한 SQL 구문은?<div class=\"q-spec\"><span class=\"q-spec__label\">보기</span><div class=\"q-tbl-title\">[테이블명 : 판매실적]</div><table class=\"q-tbl is-data\"><thead><tr><th>도시</th><th>지점명</th><th>판매액</th></tr></thead><tbody><tr><td>서울</td><td>강남 지점</td><td>330</td></tr><tr><td>서울</td><td>강북 지점</td><td>168</td></tr><tr><td>광주</td><td>광주 지점</td><td>197</td></tr><tr><td>서울</td><td>강서 지점</td><td>158</td></tr><tr><td>서울</td><td>강동 지점</td><td>197</td></tr><tr><td>대전</td><td>대전 지점</td><td>165</td></tr></tbody></table></div>","choices":["SELECT 지점명, 판매액 FROM 판매실적 ORDER BY 판매액 DESC;","SELECT * FROM 판매실적 WHEN 도시= '서울' ORDER BY 판매액 DESC;","SELECT 지점명, 판매액 FROM 판매실적 WHERE 도시= '서울' ORDER BY 판매액 DESC;","SELECT 지점명, 판매액 FROM 판매실적 WHERE 도시= '서울' ASC;"],"ans":3,"exp":{"concept":"서울 지역만 고르려면 WHERE 도시 = '서울'로 행을 거르고, 판매액이 큰 순서로 보이려면 ORDER BY 판매액 DESC로 내림차순 정렬한다. 출력할 열은 SELECT 뒤에 지점명, 판매액만 적는다. 결과는 강남 지점(330), 강동 지점(197), 강북 지점(168), 강서 지점(158) 순이다.","choices":[{"verdict":"오답","why":"WHERE 조건이 없어 서울뿐 아니라 광주, 대전 지점까지 모두 출력된다."},{"verdict":"오답","why":"조건은 WHEN이 아니라 WHERE로 써야 한다. WHEN은 CASE 식 안에서 쓰는 키워드라 문법 오류가 난다. 또 *로 모든 열을 출력한다."},{"verdict":"정답","why":"WHERE 도시 = '서울'로 서울 지점 4개만 고르고, ORDER BY 판매액 DESC로 판매액 내림차순 정렬해 지점명과 판매액을 출력한다."},{"verdict":"오답","why":"ORDER BY 없이 ASC만 쓴 것은 문법 오류이며, ASC는 오름차순이라 요구와도 반대다."}],"keywords":[{"term":"WHERE","desc":"조건에 맞는 행만 고름"},{"term":"ORDER BY","desc":"결과를 정렬, 기본은 오름차순"},{"term":"ASC","desc":"오름차순(작은 값부터), 생략 시 기본값"},{"term":"DESC","desc":"내림차순(큰 값부터)"}],"memo":"'~만을 대상으로'는 WHERE, '~순으로'는 ORDER BY. DESC는 Descending(내려가는)."}},{"id":"written-2023-3-60","no":60,"unit":"데이터베이스 구축","q":"다음은 관계 대수의 수학적 표현식이다. 이에 해당하는 연산은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>R x S = { r·s | r ∈ R ∧ s ∈ S }<br>r = &lt; a<sub>1</sub>, a<sub>2</sub>, ⋯, a<sub>n</sub> &gt;, s = &lt; b<sub>1</sub>, b<sub>2</sub>, ⋯, b<sub>m</sub> &gt;</p></div>","choices":["합집합","카티션 프로덕트","차집합","교집합"],"ans":2,"exp":{"concept":"카티션 프로덕트(Cartesian Product, 교차곱)는 두 릴레이션 R과 S의 모든 튜플을 하나씩 짝지어 이어 붙이는 연산이다. 식의 r·s는 R의 튜플 r = < a1, ..., an >과 S의 튜플 s = < b1, ..., bm >을 연결한 튜플을 뜻한다. 기호는 ×다.","choices":[{"verdict":"오답","why":"합집합(∪)은 두 릴레이션의 튜플을 중복 없이 합치는 연산으로, 튜플을 이어 붙이지 않는다."},{"verdict":"정답","why":"R × S = { r·s | r ∈ R ∧ s ∈ S }는 R의 모든 튜플과 S의 모든 튜플을 연결하는 카티션 프로덕트의 정의다."},{"verdict":"오답","why":"차집합(−)은 R에는 있고 S에는 없는 튜플을 구하는 연산이다."},{"verdict":"오답","why":"교집합(∩)은 R과 S에 공통으로 있는 튜플을 구하는 연산이다."}],"keywords":[{"term":"합집합(∪)","desc":"R ∪ S = { t | t ∈ R ∨ t ∈ S }"},{"term":"교집합(∩)","desc":"R ∩ S = { t | t ∈ R ∧ t ∈ S }"},{"term":"차집합(−)","desc":"R − S = { t | t ∈ R ∧ t ∉ S }"},{"term":"카티션 프로덕트(×)","desc":"R × S = { r·s | r ∈ R ∧ s ∈ S }, 차수는 합, 카디널리티는 곱"}],"memo":"식에 기호 ×와 튜플을 이어 붙인 r·s가 보이면 카티션 프로덕트다."}},{"id":"written-2023-3-61","no":61,"unit":"프로그래밍 언어 활용","q":"결합도(Coupling)의 단계를 약한 것부터 강한 것 순으로 가장 옳게 나열한 것은?","choices":["Stamp → Data → Control → Common → Content","Content → Stamp → Control → Common → Data","Data → Stamp → Control → Common → Content","Control → Data → Stamp → Common → Content"],"ans":3,"exp":{"concept":"결합도는 모듈 사이의 의존 정도다. 약한 것부터 자료(Data) → 스탬프(Stamp) → 제어(Control) → 외부(External) → 공통(Common) → 내용(Content) 순으로 강해진다. 보기에는 외부 결합도가 빠져 있지만 나머지의 순서로 판단하면 된다.","choices":[{"verdict":"오답","why":"스탬프 결합도가 자료 결합도보다 강하므로 Stamp가 Data보다 앞에 올 수 없다."},{"verdict":"오답","why":"가장 강한 내용 결합도(Content)가 맨 앞에 있고 가장 약한 자료 결합도(Data)가 맨 뒤에 있어 순서가 크게 틀렸다."},{"verdict":"정답","why":"Data → Stamp → Control → Common → Content는 약한 것부터 강한 것 순서로 올바르다."},{"verdict":"오답","why":"제어 결합도(Control)는 자료·스탬프 결합도보다 강하므로 맨 앞에 올 수 없다."}],"keywords":[{"term":"자료 결합도(Data)","desc":"자료 요소만 전달, 가장 약함"},{"term":"스탬프 결합도(Stamp)","desc":"자료 구조 전달"},{"term":"제어 결합도(Control)","desc":"제어 신호 전달"},{"term":"외부 결합도(External)","desc":"외부에 선언된 데이터 참조"},{"term":"내용 결합도(Content)","desc":"다른 모듈 내부를 직접 참조, 가장 강함"}],"memo":"결합도 약→강 '자스제외공내'. 처음은 Data, 끝은 Content만 확인해도 대부분 풀린다."}},{"id":"written-2023-3-62","no":62,"unit":"프로그래밍 언어 활용","q":"정보 시스템 개발 단계에서 프로그래밍 언어를 선택할 때 고려해야 할 사항과 가장 거리가 먼 것은?","choices":["사용자의 요구사항","컴파일러의 독창성","컴파일러의 가용성","개발 정보 시스템의 특성"],"ans":2,"exp":{"concept":"프로그래밍 언어를 고를 때는 개발할 정보 시스템의 특성, 사용자의 요구사항, 컴파일러를 실제로 구해 쓸 수 있는지(가용성), 개발자의 경험 등을 고려한다. 컴파일러가 독창적인지는 개발 결과와 관계가 없다.","choices":[{"verdict":"오답","why":"사용자의 요구사항은 언어 선택 시 고려할 사항이다."},{"verdict":"정답","why":"컴파일러의 독창성은 언어 선택 기준이 아니다. 중요한 것은 컴파일러를 실제로 사용할 수 있는지(가용성)다."},{"verdict":"오답","why":"컴파일러의 가용성은 언어 선택 시 고려할 사항이다."},{"verdict":"오답","why":"개발할 정보 시스템의 특성은 언어 선택 시 고려할 사항이다."}],"keywords":[{"term":"컴파일러의 가용성","desc":"개발 환경에서 해당 언어의 컴파일러를 사용할 수 있는지"},{"term":"시스템 특성","desc":"업무 처리, 과학 계산, 실시간 처리 등 개발할 시스템의 성격"},{"term":"개발자의 언어 경험","desc":"개발자가 해당 언어를 얼마나 잘 다루는지"},{"term":"사용자 요구사항","desc":"사용자가 요구하는 기능과 환경"}],"memo":"'독창성'은 언어 선택 기준에 없다. 같은 문제가 보기 순서만 바꿔 자주 나온다."}},{"id":"written-2023-3-63","no":63,"unit":"프로그래밍 언어 활용","q":"TCP 헤더에 관한 설명 중 틀린 것은?","choices":["윈도우 크기는 송수신 측의 버퍼 크기이며 최대 크기는 32767bit이다.","순서 번호(Sequence Number)는 전달되는 바이트마다 번호를 부여한다.","체크섬(Checksum)은 데이터를 포함한 세그먼트의 오류를 검사하는 데 쓰인다.","수신 번호 확인(Acknowledgement Number)은 상대편 호스트로부터 받으려는 바이트의 번호를 정의한다."],"ans":1,"exp":{"concept":"TCP 헤더에는 순서 번호, 확인 응답 번호, 윈도우 크기, 체크섬 등이 들어 있다. 윈도우 크기는 수신측이 한 번에 받을 수 있는 데이터 양(버퍼 크기)을 알려 주는 16비트 필드라서 최댓값은 2^16 - 1 = 65,535바이트다.","choices":[{"verdict":"정답","why":"윈도우 크기 필드는 16비트이므로 최대 65,535바이트를 나타낸다. 최대 32,767비트라는 설명은 틀렸다."},{"verdict":"오답","why":"순서 번호(Sequence Number)는 전송되는 데이터의 바이트마다 번호를 붙여 순서를 관리한다. 맞는 설명이다."},{"verdict":"오답","why":"체크섬(Checksum)은 헤더와 데이터를 포함한 세그먼트 전체의 오류를 검사한다. 맞는 설명이다."},{"verdict":"오답","why":"확인 응답 번호(Acknowledgement Number)는 상대편에게서 다음에 받기를 기대하는 바이트의 번호다. 맞는 설명이다."}],"keywords":[{"term":"순서 번호(Sequence Number)","desc":"보내는 데이터의 바이트 위치 번호, 32비트"},{"term":"확인 응답 번호(Acknowledgement Number)","desc":"다음에 받기를 기대하는 바이트 번호, 32비트"},{"term":"윈도우 크기(Window Size)","desc":"수신 가능한 데이터 양, 16비트, 최대 65,535바이트"},{"term":"체크섬(Checksum)","desc":"세그먼트의 오류 검출용 값, 16비트"}],"memo":"윈도우 크기는 16비트 필드 → 2^16 - 1 = 65,535바이트. 32767이라는 숫자와 bit 단위 모두 함정이다."}},{"id":"written-2023-3-64","no":64,"unit":"프로그래밍 언어 활용","q":"C언어에서 두 개의 논리 값 가운데 하나라도 참이면 1을, 둘 다 거짓이면 0을 반환하는 연산자는?","choices":["**","&amp;&amp;","!=","||"],"ans":4,"exp":{"concept":"C 언어의 논리 연산자는 &&(AND), ||(OR), !(NOT)이다. ||는 두 값 중 하나라도 참(0이 아닌 값)이면 1, 둘 다 거짓(0)이면 0을 돌려준다. &&는 둘 다 참일 때만 1을 돌려준다.","choices":[{"verdict":"오답","why":"C 언어에 **라는 논리 연산자는 없다. 선언에서 int **p처럼 쓰면 이중 포인터를 뜻한다(Python에서는 거듭제곱 연산자)."},{"verdict":"오답","why":"&&는 논리곱(AND)으로, 두 값이 모두 참일 때만 1을 반환한다."},{"verdict":"오답","why":"!=는 두 값이 다른지 비교하는 관계 연산자다."},{"verdict":"정답","why":"||는 논리합(OR)으로, 둘 중 하나라도 참이면 1, 둘 다 거짓이면 0을 반환한다."}],"keywords":[{"term":"&&(논리곱, AND)","desc":"둘 다 참일 때만 1"},{"term":"||(논리합, OR)","desc":"하나라도 참이면 1"},{"term":"!(논리 부정, NOT)","desc":"참이면 0, 거짓이면 1"},{"term":"!=(관계 연산자)","desc":"두 값이 다르면 1"}],"memo":"'하나라도'는 OR(||), '둘 다'는 AND(&&)."}},{"id":"written-2023-3-65","no":65,"unit":"프로그래밍 언어 활용","q":"192.168.1.0/24 네트워크를 FLSM 방식으로 4개의 Subnet으로 나누고 IP Subnet-zero를 적용하였다. 이때 Subnetting된 네트워크 가운데 4번째 네트워크에서 4번째로 사용 가능한 IP는 무엇인가?","choices":["192.168.1.192","192.168.1.195","192.168.1.196","192.168.1.198"],"ans":3,"exp":{"concept":"FLSM(Fixed Length Subnet Mask)은 네트워크를 같은 크기의 서브넷으로 나누는 방식이다. /24 네트워크(주소 256개)를 4개로 나누려면 서브넷 비트 2개가 필요하므로 /26이 되고, 서브넷 하나에 주소가 64개씩 들어간다. 각 서브넷의 첫 주소는 네트워크 주소, 마지막 주소는 브로드캐스트 주소라서 호스트에 줄 수 없다. IP Subnet-zero를 적용하면 첫 번째 서브넷(.0)도 사용한다.","choices":[{"verdict":"오답","why":"192.168.1.192는 4번째 서브넷(192.168.1.192/26)의 네트워크 주소라서 호스트에 할당할 수 없다."},{"verdict":"오답","why":"192.168.1.195는 4번째 서브넷에서 3번째로 사용 가능한 IP다(.193, .194, .195)."},{"verdict":"정답","why":"4개 서브넷은 .0~.63, .64~.127, .128~.191, .192~.255다. 4번째 서브넷의 사용 가능 IP는 .193부터이므로 .193, .194, .195, .196에서 4번째는 192.168.1.196이다."},{"verdict":"오답","why":"192.168.1.198은 4번째 서브넷에서 6번째로 사용 가능한 IP다."}],"keywords":[{"term":"FLSM(Fixed Length Subnet Mask)","desc":"모든 서브넷을 같은 크기로 나누는 방식"},{"term":"VLSM(Variable Length Subnet Mask)","desc":"서브넷마다 크기를 다르게 나누는 방식"},{"term":"IP Subnet-zero","desc":"첫 번째 서브넷(서브넷 번호 0)도 사용하도록 허용하는 설정"},{"term":"네트워크 주소 / 브로드캐스트 주소","desc":"서브넷의 첫 주소 / 마지막 주소, 호스트에 할당 불가"}],"memo":"4개로 나누면 256 ÷ 4 = 64. 서브넷 시작은 0, 64, 128, 192이고, 'n번째 사용 가능 IP'는 시작 주소 + n이다."}},{"id":"written-2023-3-66","no":66,"unit":"프로그래밍 언어 활용","q":"OSI 7계층 모델에서 전송에 필요한 장치 간의 실제 접속 및 절단 등 기계적, 전기적, 기능적, 절차적 특성을 정의하는 계층은?","choices":["데이터 링크 계층","전송 계층","네트워크 계층","물리 계층"],"ans":4,"exp":{"concept":"OSI 7계층 중 가장 아래인 물리 계층은 실제로 0과 1의 신호를 전선이나 전파로 주고받는 계층이다. 케이블, 커넥터, 전압처럼 장치 간 실제 접속과 절단에 필요한 기계적, 전기적, 기능적, 절차적 특성을 정의한다.","choices":[{"verdict":"오답","why":"데이터 링크 계층은 인접한 두 노드 사이에서 프레임 단위로 오류 제어와 흐름 제어를 하는 2계층이다."},{"verdict":"오답","why":"전송 계층은 종단 간(End-to-End) 신뢰성 있는 데이터 전송을 담당하는 4계층이다(예: TCP, UDP)."},{"verdict":"오답","why":"네트워크 계층은 패킷의 경로 설정(라우팅)과 논리 주소 지정을 담당하는 3계층이다(예: IP)."},{"verdict":"정답","why":"물리 계층은 장치 간 실제 접속과 절단 등 기계적, 전기적, 기능적, 절차적 특성을 정의하는 1계층이다."}],"keywords":[{"term":"물리 계층(1계층)","desc":"비트 전송, 기계적·전기적·기능적·절차적 특성 정의"},{"term":"데이터 링크 계층(2계층)","desc":"프레임 전송, 인접 노드 간 오류·흐름 제어"},{"term":"네트워크 계층(3계층)","desc":"패킷 경로 설정(라우팅)"},{"term":"전송 계층(4계층)","desc":"종단 간 신뢰성 있는 전송, 세그먼트"}],"memo":"'기계적, 전기적'이라는 말이 나오면 물리 계층이다. OSI 순서는 '물데네전세표응'."}},{"id":"written-2023-3-67","no":67,"unit":"프로그래밍 언어 활용","q":"UNIX에 관한 설명 중 옳지 않은 것은?","choices":["쉘(shell)은 프로세스 관리, 기억장치 관리, 입/출력 관리 등의 기능을 담당한다.","상당 부분이 C 언어로 작성되어 있어 이식성이 우수하다.","두 사람 이상의 사용자가 동시에 시스템을 이용할 수 있어 정보와 유틸리티들을 공유하는 편리한 작업 환경을 제공한다.","사용자는 하나 이상의 작업을 백그라운드로 수행할 수 있으므로 여러 개의 작업을 병행 처리할 수 있다."],"ans":1,"exp":{"concept":"UNIX는 커널(Kernel), 쉘(Shell), 유틸리티로 구성된다. 커널은 하드웨어를 직접 다루며 프로세스, 기억장치, 입출력, 파일 관리를 맡는 핵심 부분이다. 쉘은 사용자가 입력한 명령을 해석해 커널에 전달하는 명령어 해석기다.","choices":[{"verdict":"정답","why":"프로세스 관리, 기억장치 관리, 입출력 관리를 담당하는 것은 커널이다. 쉘은 사용자 명령을 해석해 커널에 전달하는 명령어 해석기다."},{"verdict":"오답","why":"UNIX는 대부분 C 언어로 작성되어 다른 하드웨어로 옮기기 쉽다(이식성이 높다). 맞는 설명이다."},{"verdict":"오답","why":"UNIX는 여러 사용자가 동시에 쓰는 다중 사용자(Multi-User) 시스템이다. 맞는 설명이다."},{"verdict":"오답","why":"UNIX는 여러 작업을 백그라운드로 동시에 수행하는 다중 작업(Multi-Tasking)을 지원한다. 맞는 설명이다."}],"keywords":[{"term":"커널(Kernel)","desc":"UNIX의 핵심, 프로세스·기억장치·입출력·파일 관리"},{"term":"쉘(Shell)","desc":"사용자 명령을 해석해 커널에 전달하는 명령어 해석기"},{"term":"유틸리티(Utility)","desc":"에디터, 컴파일러 등 사용자를 돕는 프로그램"},{"term":"이식성(Portability)","desc":"다른 환경으로 쉽게 옮겨 실행할 수 있는 성질"}],"memo":"커널은 '알맹이(핵심 관리)', 쉘은 '껍데기(사용자와의 창구)'."}},{"id":"written-2023-3-68","no":68,"unit":"프로그래밍 언어 활용","q":"빈 기억공간의 크기가 각각 20KB, 16KB, 8KB, 40KB 일 때, 기억장치 배치 전략으로 “Best Fit&quot;을 사용해 17KB의 프로그램을 적재하면 내부 단편화의 크기는 얼마가 되는가?","choices":["3KB","23KB","64KB","67KB"],"ans":1,"exp":{"concept":"최적 적합(Best Fit)은 프로그램이 들어갈 수 있는 빈 공간 중 남는 공간이 가장 작은 곳에 프로그램을 넣는 배치 전략이다. 17KB가 들어갈 수 있는 공간은 20KB와 40KB이고, 그중 더 작은 20KB에 넣는다. 남는 20 - 17 = 3KB가 내부 단편화다.","choices":[{"verdict":"정답","why":"Best Fit은 17KB 이상인 공간(20KB, 40KB) 중 가장 작은 20KB를 고른다. 20 - 17 = 3KB가 내부 단편화다."},{"verdict":"오답","why":"23KB는 가장 큰 40KB 공간에 넣었을 때(40 - 17)의 값으로, 최악 적합(Worst Fit)의 결과다."},{"verdict":"오답","why":"64KB는 Best Fit 배치 결과와 관계없는 값이다. 내부 단편화는 선택한 공간 하나에서 남는 크기만 계산한다."},{"verdict":"오답","why":"67KB는 전체 빈 공간을 모두 더한 값(84KB)에서 17KB를 뺀 값으로, 내부 단편화가 아니다."}],"keywords":[{"term":"최초 적합(First Fit)","desc":"들어갈 수 있는 첫 번째 공간에 배치"},{"term":"최적 적합(Best Fit)","desc":"들어갈 수 있는 공간 중 남는 공간이 가장 작은 곳에 배치"},{"term":"최악 적합(Worst Fit)","desc":"들어갈 수 있는 공간 중 남는 공간이 가장 큰 곳에 배치"},{"term":"내부 단편화","desc":"배치하고 남은 영역 안의 빈 공간"},{"term":"외부 단편화","desc":"프로그램보다 작아 사용되지 못하고 남은 빈 공간"}],"memo":"Best는 '꼭 맞는' 곳, Worst는 '가장 헐렁한' 곳. 먼저 프로그램보다 작은 공간(16KB, 8KB)을 지우고 고른다."}},{"id":"written-2023-3-69","no":69,"unit":"프로그래밍 언어 활용","q":"다음 C언어 프로그램에서 밑줄 친 부분과 같은 의미를 갖는 것은 무엇인가?<pre class=\"qcode\"><code>#include &lt;stdio.h&gt;\nmain() {\n    int a, b;\n    for (a = 0; a &lt; 2; a++)\n        for (b = 0; b &lt; 2; b++)\n            printf(\"%d\", <u>!a &amp;&amp; !b</u>);\n}</code></pre>","choices":["a || b","!(a || b)","a &amp;&amp; b","!a || !b"],"ans":2,"exp":{"concept":"밑줄 친 부분은 !a && !b이다. 드모르간 법칙에 따르면 !a && !b는 !(a || b)와 같다. 'a도 아니고 b도 아니다'는 'a 또는 b가 아니다'와 같은 뜻이다. 프로그램은 a, b가 0, 1을 도는 동안 (0,0)에서만 1을 출력해 1000을 출력한다.","choices":[{"verdict":"오답","why":"a || b는 (0,0)에서 0, 나머지에서 1을 내므로 !a && !b와 정반대 결과(0111)다."},{"verdict":"정답","why":"드모르간 법칙에 의해 !a && !b = !(a || b)이다. 두 식 모두 (0,0)일 때만 1이고 나머지는 0이다."},{"verdict":"오답","why":"a && b는 (1,1)일 때만 1이므로 결과가 0001로 다르다."},{"verdict":"오답","why":"!a || !b는 !(a && b)와 같아 (1,1)일 때만 0이고 나머지는 1이므로 결과가 1110으로 다르다."}],"keywords":[{"term":"드모르간 법칙 1","desc":"!(A || B) = !A && !B"},{"term":"드모르간 법칙 2","desc":"!(A && B) = !A || !B"},{"term":"논리 부정(!)","desc":"0이면 1, 0이 아니면 0"},{"term":"C의 참·거짓","desc":"0은 거짓, 0이 아닌 값은 참, 논리 연산 결과는 0 또는 1"}],"memo":"드모르간은 '괄호 밖 !를 안으로 넣으면 각 항에 !가 붙고 &&와 ||가 서로 바뀐다'."}},{"id":"written-2023-3-70","no":70,"unit":"프로그래밍 언어 활용","q":"배치 프로그램의 필수 요소에 관한 설명으로 옳지 않은 것은?","choices":["무결성은 주어진 시간 안에 처리를 완료할 수 있어야 하며, 동시에 동작 중인 다른 애플리케이션을 방해하지 말아야 한다.","자동화는 심각한 오류 상황을 제외하고는 사용자의 개입 없이 동작해야 한다.","안정성은 어떤 문제가 생겼는지, 언제 발생했는지 등을 추적할 수 있어야 한다.","대용량 데이터는 대량의 데이터를 처리할 수 있어야 한다."],"ans":1,"exp":{"concept":"배치 프로그램은 사용자의 개입 없이 정해진 시간에 대량의 데이터를 한꺼번에 처리하는 프로그램이다. 필수 요소는 대용량 데이터, 자동화, 견고성, 안정성(신뢰성), 성능 5가지다. 보기 1의 '주어진 시간 안에 처리를 완료하고 다른 애플리케이션을 방해하지 않아야 한다'는 성능의 설명이며, 무결성은 필수 요소에 없다.","choices":[{"verdict":"정답","why":"주어진 시간 안에 처리를 끝내고 다른 애플리케이션을 방해하지 않아야 한다는 것은 '성능'에 대한 설명이다. 무결성은 배치 프로그램 필수 요소가 아니다."},{"verdict":"오답","why":"자동화는 심각한 오류 상황 외에는 사용자 개입 없이 동작해야 한다는 요소로, 맞는 설명이다."},{"verdict":"오답","why":"안정성(신뢰성)은 어떤 문제가 언제 발생했는지 등을 추적할 수 있어야 한다는 요소로, 맞는 설명이다."},{"verdict":"오답","why":"대용량 데이터는 대량의 데이터를 가공·처리할 수 있어야 한다는 요소로, 맞는 설명이다."}],"keywords":[{"term":"대용량 데이터","desc":"대량의 데이터를 처리할 수 있어야 함"},{"term":"자동화","desc":"심각한 오류 외에는 사용자 개입 없이 동작"},{"term":"견고성","desc":"잘못된 데이터나 중복 등 비정상 상황에서도 중단 없이 수행"},{"term":"안정성(신뢰성)","desc":"문제의 내용과 발생 시점 등을 추적할 수 있어야 함"},{"term":"성능","desc":"주어진 시간 내 처리 완료, 다른 애플리케이션을 방해하지 않음"}],"memo":"배치 필수 요소는 '대자견안성(대용량, 자동화, 견고성, 안정성, 성능)'."}},{"id":"written-2023-3-71","no":71,"unit":"프로그래밍 언어 활용","q":"C언어의 정수 자료형에 해당하는 것은?","choices":["double","float","char *","int"],"ans":4,"exp":{"concept":"C 언어의 자료형은 정수형(char, short, int, long 등), 실수형(float, double), 포인터형 등으로 나뉜다. int는 대표적인 정수형이다. char *는 문자형 변수의 주소를 저장하는 포인터형이다.","choices":[{"verdict":"오답","why":"double은 배정도 실수형(8바이트)이다."},{"verdict":"오답","why":"float는 단정도 실수형(4바이트)이다."},{"verdict":"오답","why":"char *는 char형 데이터의 주소를 저장하는 포인터형이다. 정수형이 아니다."},{"verdict":"정답","why":"int는 정수를 저장하는 대표적인 정수 자료형이다."}],"keywords":[{"term":"정수형","desc":"char, short, int, long, long long"},{"term":"실수형","desc":"float(단정도), double(배정도)"},{"term":"포인터형","desc":"자료형 뒤에 *를 붙여 주소를 저장, 예: char *, int *"},{"term":"sizeof","desc":"자료형이나 변수의 크기(바이트)를 구하는 연산자"}],"memo":"자료형 뒤에 *가 붙으면 그 자료형이 무엇이든 '주소를 담는 포인터'다."}},{"id":"written-2023-3-72","no":72,"unit":"프로그래밍 언어 활용","q":"다음 중 시간 구역성(Temporal Locality)과 거리가 먼 것은?","choices":["루프","서브루틴","스택","배열 순회"],"ans":4,"exp":{"concept":"구역성(Locality)은 프로그램이 실행될 때 일부 기억 장소를 집중적으로 참조하는 성질이다. 시간 구역성은 한 번 참조한 곳을 가까운 미래에 다시 참조하는 것이고, 공간 구역성은 참조한 곳의 근처를 이어서 참조하는 것이다. 배열을 차례로 훑는 것은 이웃 주소를 이어서 참조하므로 공간 구역성이다.","choices":[{"verdict":"오답","why":"루프(반복문)는 같은 명령어와 변수를 반복해서 참조하므로 시간 구역성의 대표 예다."},{"verdict":"오답","why":"서브루틴은 같은 코드를 여러 번 호출해 다시 참조하므로 시간 구역성의 예다."},{"verdict":"오답","why":"스택은 최근에 쌓은 Top 부근을 반복해서 참조하므로 시간 구역성의 예다."},{"verdict":"정답","why":"배열 순회는 연속된 이웃 주소를 차례로 참조하는 공간 구역성(Spatial Locality)의 예다."}],"keywords":[{"term":"구역성(Locality)","desc":"프로그램이 일부 기억 장소를 집중적으로 참조하는 성질"},{"term":"시간 구역성(Temporal Locality)","desc":"최근 참조한 곳을 곧 다시 참조. 예: 루프, 서브루틴, 스택, 카운팅·집계 변수"},{"term":"공간 구역성(Spatial Locality)","desc":"참조한 곳의 근처를 참조. 예: 배열 순회, 순차적 코드 실행"},{"term":"워킹 셋(Working Set)","desc":"구역성을 바탕으로 프로세스가 일정 시간 동안 자주 참조하는 페이지 집합"}],"memo":"'같은 곳을 또'는 시간 구역성, '옆 칸으로'는 공간 구역성. 배열은 옆 칸으로 간다."}},{"id":"written-2023-3-73","no":73,"unit":"프로그래밍 언어 활용","q":"다음 자바 프로그램의 조건문의 조건식과 각 분기의 계산식을 그대로 유지하면서 삼항 조건 연산자로 옳게 나타낸 것은?<pre class=\"qcode\"><code class=\"language-java\">int i = 7, j = 9;\nint k;\nif (i &gt; j)\n    k = i - j;\nelse\n    k = i + j;</code></pre>","choices":["<pre class=\"qcode\"><code>int i = 7, j = 9;\nint k;\nk = (i＞j) ? (i - j) : (i + j);</code></pre>","<pre class=\"qcode\"><code>int i = 7, j = 9;\nint k;\nk = (i＜j) ? (i - j) : (i + j);</code></pre>","<pre class=\"qcode\"><code>int i = 7, j = 9;\nint k;\nk = (i＜j) ? (i + j) : (i - j);</code></pre>","<pre class=\"qcode\"><code>int i = 7, j = 9;\nint k;\nk = (i＞j) ? (i + j) : (i - j);</code></pre>"],"ans":1,"exp":{"concept":"삼항 조건 연산자는 '조건 ? 참일 때 값 : 거짓일 때 값' 형태로 if-else를 한 줄로 쓰는 방법이다. 원래 코드는 i > j가 참이면 i - j, 거짓이면 i + j를 k에 넣으므로 k = (i > j) ? (i - j) : (i + j)가 된다. i = 7, j = 9에서 i > j는 거짓이라 k = 7 + 9 = 16이다.","choices":[{"verdict":"정답","why":"조건식 i > j, 참일 때 i - j, 거짓일 때 i + j가 원래 if-else와 그대로 대응한다. 실행하면 k = 16이다."},{"verdict":"오답","why":"조건이 i < j로 바뀌었다. i = 7, j = 9에서 i < j가 참이 되어 k = 7 - 9 = -2로 결과가 달라진다."},{"verdict":"오답","why":"조건을 i < j로 바꾸고 두 계산식의 위치도 바꿨다. 이 입력에서는 16이 나오지만 조건식을 그대로 유지하라는 요구에 어긋나고, i와 j가 같을 때는 0이 나와 원래 코드(i + j)와 결과도 다르다."},{"verdict":"오답","why":"조건은 i > j 그대로지만 참·거짓일 때의 계산식이 뒤바뀌어 k = 7 - 9 = -2가 된다."}],"keywords":[{"term":"삼항 조건 연산자","desc":"조건 ? 값1 : 값2, 조건이 참이면 값1, 거짓이면 값2"},{"term":"if-else","desc":"조건에 따라 두 갈래 중 하나를 실행하는 제어문"},{"term":"관계 연산자","desc":">, <, >=, <=, ==, !="},{"term":"대입 연산","desc":"삼항 연산 결과를 변수에 대입할 수 있다"}],"memo":"if(조건) A; else B; 는 조건 ? A : B. 물음표 앞은 조건, 콜론 앞은 참, 뒤는 거짓."}},{"id":"written-2023-3-74","no":74,"unit":"프로그래밍 언어 활용","q":"다음 설명에 해당하는 소프트웨어 취약점은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>메모리를 다루는 과정에서 오류가 발생해 프로그램이 잘못된 동작을 하게 되는 취약점</p></div>","choices":["버퍼 오버플로","FTP 바운스 공격","SQL 삽입","디렉토리 접근 공격"],"ans":1,"exp":{"concept":"버퍼 오버플로(Buffer Overflow)는 메모리에 잡아 둔 버퍼의 크기보다 많은 데이터를 넣어 이웃한 메모리 영역을 덮어쓰는 취약점이다. 이로 인해 프로그램이 잘못 동작하거나 공격자가 넣은 코드가 실행될 수 있다. 컵에 물을 너무 많이 부어 넘친 물이 옆을 적시는 것과 같다.","choices":[{"verdict":"정답","why":"버퍼 오버플로는 메모리를 다루는 과정에서 버퍼 크기를 넘는 데이터가 들어가 프로그램이 잘못 동작하게 되는 취약점이다."},{"verdict":"오답","why":"FTP 바운스 공격은 FTP 서버의 데이터 연결(PORT 명령) 기능을 악용해 다른 호스트를 공격하거나 포트를 탐색하는 공격이다."},{"verdict":"오답","why":"SQL 삽입(SQL Injection)은 입력값에 SQL 구문을 끼워 넣어 데이터베이스를 조작하는 공격이다."},{"verdict":"오답","why":"디렉토리 접근 공격은 경로 조작으로 허용되지 않은 디렉토리나 파일에 접근하는 공격이다."}],"keywords":[{"term":"버퍼 오버플로(Buffer Overflow)","desc":"버퍼 크기를 넘는 데이터로 인접 메모리를 덮어쓰는 취약점"},{"term":"스택 가드(Stack Guard)","desc":"복귀 주소 앞에 카나리 값을 두어 변조를 감지하는 대응 기법"},{"term":"ASLR","desc":"메모리 주소 배치를 무작위로 바꿔 공격을 어렵게 하는 기법"},{"term":"SQL 삽입(SQL Injection)","desc":"입력값에 SQL을 삽입해 DB를 조작하는 공격"}],"memo":"'메모리'와 '넘침'이 보이면 버퍼 오버플로다."}},{"id":"written-2023-3-75","no":75,"unit":"프로그래밍 언어 활용","q":"다음 표에 제시된 시점의 HRN 응답률을 기준으로 작업의 우선순위를 높은 순서부터 나열한 것은?<div class=\"q-spec\"><span class=\"q-spec__label\">보기</span><table class=\"q-tbl is-data\"><thead><tr><th>작업</th><th>대기 시간</th><th>서비스(실행)시간</th></tr></thead><tbody><tr><td>A</td><td>5</td><td>20</td></tr><tr><td>B</td><td>40</td><td>20</td></tr><tr><td>C</td><td>15</td><td>45</td></tr><tr><td>D</td><td>20</td><td>2</td></tr></tbody></table></div>","choices":["D → B → C → A","A → C → B → D","A → B → C → D","D → A → B → C"],"ans":1,"exp":{"concept":"HRN(Highest Response-ratio Next)은 대기 시간이 길수록 우선순위를 높여 주는 스케줄링이다. 우선순위 = (대기 시간 + 서비스 시간) ÷ 서비스 시간이고, 값이 클수록 먼저 실행한다. 짧은 작업에 유리하지만 오래 기다린 작업도 결국 실행되게 해 SJF의 기아 현상을 줄인다.","choices":[{"verdict":"정답","why":"A = (5 + 20) ÷ 20 = 1.25, B = (40 + 20) ÷ 20 = 3, C = (15 + 45) ÷ 45 ≈ 1.33, D = (20 + 2) ÷ 2 = 11이다. 큰 순서는 D(11) → B(3) → C(1.33) → A(1.25)다."},{"verdict":"오답","why":"A는 응답률이 1.25로 가장 낮아 맨 마지막이어야 한다. 순서가 정반대에 가깝다."},{"verdict":"오답","why":"A(1.25)가 맨 앞에 오고 D(11)가 맨 뒤에 있어 틀렸다."},{"verdict":"오답","why":"D 다음은 응답률 3인 B여야 하는데, 가장 낮은 A(1.25)가 두 번째에 와서 틀렸다."}],"keywords":[{"term":"HRN 우선순위","desc":"(대기 시간 + 서비스 시간) ÷ 서비스 시간, 클수록 먼저"},{"term":"SJF(Shortest Job First)","desc":"실행 시간이 가장 짧은 작업을 먼저 실행"},{"term":"기아 현상(Starvation)","desc":"특정 작업이 계속 밀려 실행되지 못하는 현상"},{"term":"에이징(Aging)","desc":"오래 기다린 작업의 우선순위를 높여 기아를 막는 기법"}],"memo":"HRN 공식은 '(대기 + 서비스) ÷ 서비스'. 분모는 서비스 시간이다. 분모를 대기 시간으로 잘못 쓰는 실수가 잦다."}},{"id":"written-2023-3-76","no":76,"unit":"프로그래밍 언어 활용","q":"UNIX에서 새 프로세스를 만들 때 사용하는 시스템 호출은?","choices":["fork","chmod","ls","cat"],"ans":1,"exp":{"concept":"fork()는 UNIX에서 현재 실행 중인 프로세스(부모)를 복제해 새로운 프로세스(자식)를 만드는 시스템 호출이다. 시스템 호출은 프로그램이 커널의 기능을 쓰기 위해 부르는 함수다.","choices":[{"verdict":"정답","why":"fork는 현재 프로세스를 복제해 새 자식 프로세스를 생성하는 시스템 호출이다."},{"verdict":"오답","why":"chmod는 파일의 접근 권한을 변경하는 명령(및 시스템 호출)으로, 프로세스를 만들지 않는다."},{"verdict":"오답","why":"ls는 디렉토리의 파일 목록을 보여 주는 명령어다."},{"verdict":"오답","why":"cat은 파일 내용을 화면에 출력하는 명령어다."}],"keywords":[{"term":"fork","desc":"부모 프로세스를 복제해 자식 프로세스를 생성"},{"term":"exec","desc":"현재 프로세스를 새 프로그램으로 바꿔 실행"},{"term":"wait","desc":"자식 프로세스가 끝날 때까지 부모가 기다림"},{"term":"exit","desc":"프로세스를 종료"},{"term":"chmod","desc":"파일 접근 권한 변경"}],"memo":"fork는 '포크(갈래)', 프로세스가 둘로 갈라진다."}},{"id":"written-2023-3-77","no":77,"unit":"프로그래밍 언어 활용","q":"다음 Python 프로그램을 실행했을 때의 실행 결과는?<pre class=\"qcode\"><code class=\"language-python\">a = 100\nlist_data = ['a','b','c']\ndict_data = {'a':90, 'b':95}\nprint(list_data[0])\nprint(dict_data['a'])</code></pre>","choices":["<pre class=\"qcode\"><code>a\na</code></pre>","<pre class=\"qcode\"><code>100\n100</code></pre>","<pre class=\"qcode\"><code>a\n90</code></pre>","<pre class=\"qcode\"><code>100\n90</code></pre>"],"ans":3,"exp":{"concept":"파이썬의 리스트는 0부터 시작하는 인덱스로, 딕셔너리는 키로 값을 꺼낸다. list_data[0]은 리스트의 첫 원소인 문자열 'a'이고, dict_data['a']는 키 'a'에 대응하는 값 90이다. 변수 a = 100은 문자열 'a'와 전혀 다른 것이라 결과에 영향이 없다.","choices":[{"verdict":"오답","why":"dict_data['a']는 문자열 'a'가 아니라 키 'a'에 연결된 값 90을 출력한다."},{"verdict":"오답","why":"list_data[0]은 변수 a(100)가 아니라 리스트에 저장된 문자열 'a'이며, dict_data['a']는 90이다."},{"verdict":"정답","why":"print(list_data[0])은 a를, print(dict_data['a'])는 90을 출력한다."},{"verdict":"오답","why":"list_data[0]은 리스트 안의 문자열 'a'이므로 100이 아니라 a가 출력된다. 따옴표가 있는 'a'는 변수 a가 아니다."}],"keywords":[{"term":"리스트(list)","desc":"순서가 있는 자료형, 인덱스 0부터 접근"},{"term":"딕셔너리(dict)","desc":"키:값 쌍으로 저장, 키로 값에 접근"},{"term":"문자열 리터럴","desc":"따옴표로 감싼 값, 'a'는 변수 a와 다르다"},{"term":"print()","desc":"값을 출력하고 줄을 바꿈"}],"memo":"따옴표가 있으면 문자열, 없으면 변수. 'a'와 a를 혼동시키는 것이 이 문제의 함정이다."}},{"id":"written-2023-3-78","no":78,"unit":"프로그래밍 언어 활용","q":"파이썬의 변수 작성 규칙에 대한 설명으로 옳지 않은 것은?","choices":["첫 자리에는 숫자를 사용할 수 없다.","영문 대문자/소문자, 숫자, 밑줄(_)을 사용할 수 있다.","변수 이름 중간에 공백을 사용할 수 있다.","이미 사용 중인 예약어는 사용할 수 없다."],"ans":3,"exp":{"concept":"파이썬 변수 이름은 영문 대·소문자, 숫자, 밑줄(_)로 만든다. 첫 글자에 숫자를 쓸 수 없고, 공백을 넣을 수 없으며, if나 for 같은 예약어는 쓸 수 없다. 대문자와 소문자는 서로 다른 이름으로 구분한다.","choices":[{"verdict":"오답","why":"변수 이름의 첫 글자에는 숫자를 쓸 수 없다. 맞는 설명이다."},{"verdict":"오답","why":"영문 대·소문자, 숫자, 밑줄(_)을 사용할 수 있다. 맞는 설명이다."},{"verdict":"정답","why":"변수 이름에는 공백을 넣을 수 없다. 단어를 이으려면 my_var처럼 밑줄을 쓴다."},{"verdict":"오답","why":"if, for, while 같은 예약어는 변수 이름으로 쓸 수 없다. 맞는 설명이다."}],"keywords":[{"term":"식별자(Identifier)","desc":"변수, 함수 등에 붙이는 이름"},{"term":"예약어(Keyword)","desc":"언어가 미리 정해 둔 단어, 예: if, for, while, def, class"},{"term":"대소문자 구분","desc":"Name과 name은 서로 다른 변수"},{"term":"스네이크 표기법","desc":"단어를 밑줄로 잇는 표기, 예: student_name"}],"memo":"변수 이름 규칙: 숫자로 시작 금지, 공백 금지, 예약어 금지. 특수문자는 밑줄(_)만 허용."}},{"id":"written-2023-3-79","no":79,"unit":"프로그래밍 언어 활용","q":"다음 IP address 중 C Class에 해당하는 것은?","choices":["200.168.30.1","10.3.2.14","225.2.4.1","172.16.98.3"],"ans":1,"exp":{"concept":"IPv4 주소는 첫 번째 옥텟(8비트) 값으로 클래스를 나눈다. A 클래스는 0~127, B 클래스는 128~191, C 클래스는 192~223, D 클래스(멀티캐스트)는 224~239, E 클래스(연구용)는 240~255다.","choices":[{"verdict":"정답","why":"첫 옥텟이 200이므로 192~223 범위의 C 클래스다."},{"verdict":"오답","why":"첫 옥텟이 10이므로 A 클래스이며, 10.0.0.0/8은 사설 IP 대역이다."},{"verdict":"오답","why":"첫 옥텟이 225이므로 224~239 범위의 D 클래스(멀티캐스트)다."},{"verdict":"오답","why":"첫 옥텟이 172이므로 B 클래스이며, 172.16.0.0~172.31.255.255는 사설 IP 대역이다."}],"keywords":[{"term":"A 클래스","desc":"0~127, 기본 서브넷 마스크 255.0.0.0"},{"term":"B 클래스","desc":"128~191, 기본 서브넷 마스크 255.255.0.0"},{"term":"C 클래스","desc":"192~223, 기본 서브넷 마스크 255.255.255.0"},{"term":"D 클래스","desc":"224~239, 멀티캐스트용"},{"term":"E 클래스","desc":"240~255, 연구용"}],"memo":"클래스 경계 128, 192, 224, 240만 외우면 된다. 첫 옥텟 이진수의 앞자리가 0, 10, 110, 1110, 1111인 것과 같다."}},{"id":"written-2023-3-80","no":80,"unit":"프로그래밍 언어 활용","q":"다음 중 페이지 교체(Page Replacement) 알고리즘에 해당하지 않는 것은?","choices":["Optimal","LUF(Least Used First)","LRU(Least Recently Used)","FIFO(First-In-First-Out)"],"ans":2,"exp":{"concept":"페이지 교체 알고리즘은 페이지 부재가 났는데 주기억장치가 꽉 찼을 때, 어떤 페이지를 내보낼지 정하는 방법이다. OPT(Optimal), FIFO, LRU, LFU, NUR, SCR 등이 있다. LUF라는 알고리즘은 없으며, 비슷한 이름의 LFU(Least Frequently Used)와 헷갈리게 만든 보기다.","choices":[{"verdict":"오답","why":"OPT(Optimal, 최적 교체)는 앞으로 가장 오랫동안 사용하지 않을 페이지를 교체하는 알고리즘이다."},{"verdict":"정답","why":"LUF(Least Used First)는 페이지 교체 알고리즘이 아니다. 사용 횟수가 가장 적은 페이지를 교체하는 것은 LFU(Least Frequently Used)다."},{"verdict":"오답","why":"LRU(Least Recently Used)는 가장 오랫동안 사용하지 않은 페이지를 교체하는 알고리즘이다."},{"verdict":"오답","why":"FIFO(First-In-First-Out)는 가장 먼저 들어온 페이지를 교체하는 알고리즘이다."}],"keywords":[{"term":"OPT(Optimal)","desc":"앞으로 가장 오래 사용되지 않을 페이지 교체, 실제 구현은 어려움"},{"term":"FIFO","desc":"가장 먼저 들어온 페이지 교체"},{"term":"LRU(Least Recently Used)","desc":"가장 오랫동안 사용되지 않은 페이지 교체"},{"term":"LFU(Least Frequently Used)","desc":"사용 횟수가 가장 적은 페이지 교체"},{"term":"NUR(Not Used Recently)","desc":"참조 비트와 변형 비트로 최근 사용하지 않은 페이지 교체"}],"memo":"LRU는 Recently(최근), LFU는 Frequently(빈도). 글자 순서를 바꾼 LUF는 가짜다."}},{"id":"written-2023-3-81","no":81,"unit":"정보시스템 구축 관리","q":"전자 칩처럼 소프트웨어 부품, 즉 블록(모듈)을 만들어 끼워 맞추는 방식으로 소프트웨어를 완성하는 재사용 방법은?","choices":["합성 중심","분리 중심","생성 중심","구조 중심"],"ans":1,"exp":{"concept":"소프트웨어 재사용 방법에는 합성 중심과 생성 중심이 있다. 합성 중심(Composition-Based)은 전자 칩을 꽂듯 만들어 둔 모듈(블록)을 끼워 맞춰 소프트웨어를 완성하는 방법으로 블록 구성 방법이라고도 한다. 생성 중심(Generation-Based)은 추상화된 명세를 구체화해 소프트웨어를 만드는 방법으로 패턴 구성 방법이라고도 한다.","choices":[{"verdict":"정답","why":"합성 중심은 소프트웨어 부품(블록, 모듈)을 만들어 끼워 맞추는 방식으로 소프트웨어를 완성하는 재사용 방법이다."},{"verdict":"오답","why":"분리 중심은 소프트웨어 재사용 방법의 분류에 없다."},{"verdict":"오답","why":"생성 중심은 추상화 형태로 쓰인 명세를 구체화해 프로그램을 만드는 방법(패턴 구성 방법)으로, 블록을 끼워 맞추는 방식이 아니다."},{"verdict":"오답","why":"구조 중심은 소프트웨어 재사용 방법의 분류에 없다."}],"keywords":[{"term":"합성 중심(Composition-Based)","desc":"모듈(블록)을 끼워 맞춰 완성, 블록 구성 방법"},{"term":"생성 중심(Generation-Based)","desc":"추상화된 명세를 구체화해 생성, 패턴 구성 방법"},{"term":"소프트웨어 재사용","desc":"이미 개발된 소프트웨어의 전체나 일부를 다시 사용하는 것"},{"term":"CBD(Component Based Development)","desc":"컴포넌트를 조립해 소프트웨어를 개발하는 방법"}],"memo":"'끼워 맞춘다(조립)'는 합성, '패턴·명세에서 만들어 낸다'는 생성."}},{"id":"written-2023-3-82","no":82,"unit":"정보시스템 구축 관리","q":"세션 하이재킹의 탐지 방법과 거리가 먼 것은?","choices":["패킷 유실 및 재전송 증가 탐지","ACK STORM 탐지","비동기화 상태 탐지","FTP SYN SEGMENT 탐지"],"ans":4,"exp":{"concept":"세션 하이재킹은 이미 인증된 정상 사용자의 세션(TCP 연결)을 가로채는 공격이다. 공격자가 끼어들면 순서 번호가 어긋나는 비동기화 상태가 생기고, 그 결과 ACK 패킷이 폭주(ACK Storm)하거나 패킷 유실과 재전송이 늘어난다. 이런 현상을 탐지하는 것이 세션 하이재킹 탐지 방법이다.","choices":[{"verdict":"오답","why":"공격으로 순서 번호가 어긋나면 패킷 유실과 재전송이 늘어나므로, 이를 탐지하는 것은 세션 하이재킹 탐지 방법이다."},{"verdict":"오답","why":"비동기화된 양쪽이 서로 ACK를 계속 주고받는 ACK Storm을 탐지하는 것은 세션 하이재킹 탐지 방법이다."},{"verdict":"오답","why":"클라이언트와 서버의 순서 번호가 어긋난 비동기화 상태를 탐지하는 것은 세션 하이재킹 탐지 방법이다."},{"verdict":"정답","why":"FTP SYN SEGMENT 탐지는 세션 하이재킹 탐지 방법에 해당하지 않는다."}],"keywords":[{"term":"세션 하이재킹(Session Hijacking)","desc":"인증된 사용자의 세션을 가로채는 공격"},{"term":"비동기화 상태","desc":"클라이언트와 서버의 순서 번호가 서로 맞지 않는 상태"},{"term":"ACK Storm","desc":"비동기화된 양쪽이 ACK 패킷을 끝없이 주고받는 현상"},{"term":"세션 하이재킹 탐지","desc":"비동기화 상태, ACK Storm, 패킷 유실·재전송 증가, 예상치 못한 접속 리셋 탐지"}],"memo":"세션 하이재킹 탐지는 '비동기화 → ACK Storm → 재전송 증가'라는 인과 순서로 기억한다."}},{"id":"written-2023-3-83","no":83,"unit":"정보시스템 구축 관리","q":"백도어를 탐지하는 방법으로 옳지 않은 것은?","choices":["무결성 검사","SetUID 파일 검사","로그 분석","닫힌 포트 확인"],"ans":4,"exp":{"concept":"백도어(Back Door)는 정상적인 인증 절차를 거치지 않고 시스템에 몰래 들어올 수 있게 만든 뒷문이다. 백도어는 외부와 통신하기 위해 포트를 열어 두므로, 탐지할 때는 닫힌 포트가 아니라 열린 포트와 실행 중인 프로세스를 확인한다. 그 밖에 무결성 검사, SetUID 파일 검사, 로그 분석, 탐지 도구 사용이 있다.","choices":[{"verdict":"오답","why":"중요 파일이 바뀌었는지 해시값 등으로 확인하는 무결성 검사는 백도어 탐지 방법이다."},{"verdict":"오답","why":"관리자 권한으로 실행되도록 SetUID가 설정된 파일 중 의심스러운 것을 찾는 검사는 백도어 탐지 방법이다."},{"verdict":"오답","why":"접속 기록과 작업 기록을 살피는 로그 분석은 백도어 탐지 방법이다."},{"verdict":"정답","why":"백도어는 포트를 열어 외부와 통신하므로 열린 포트를 확인해야 한다. 닫힌 포트 확인은 탐지 방법이 아니다."}],"keywords":[{"term":"백도어(Back Door)","desc":"정상 인증 없이 시스템에 접근할 수 있게 만든 비밀 통로"},{"term":"무결성 검사","desc":"파일이 변조되었는지 해시값 등으로 확인"},{"term":"SetUID","desc":"실행하는 동안 파일 소유자의 권한을 얻게 하는 UNIX 권한 설정"},{"term":"백도어 탐지 방법","desc":"실행 중인 프로세스·열린 포트 확인, SetUID 파일 검사, 무결성 검사, 로그 분석, 탐지 도구 사용"}],"memo":"뒷문을 찾으려면 '열린' 문을 봐야 한다."}},{"id":"written-2023-3-84","no":84,"unit":"정보시스템 구축 관리","q":"시스템 사용자가 로그인하여 명령을 내리는 과정에서 나타나는 시스템의 동작 가운데 다음 설명에 해당하는 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>자신의 신원(Identity)을 시스템에 증명하는 과정이다.</li><li>아이디와 패스워드를 입력하는 과정이 가장 일반적인 예라고 할 수 있다.</li></ul></div>","choices":["Authentication","Accounting","Authorization","Aging"],"ans":1,"exp":{"concept":"AAA는 사용자가 시스템에 접속해 자원을 사용하는 과정을 관리하는 세 가지 기능으로, 인증(Authentication), 권한 부여(Authorization), 계정 관리(Accounting)다. 인증은 '당신이 누구인지' 증명하는 과정이며, 아이디와 패스워드 입력이 대표적인 예다.","choices":[{"verdict":"정답","why":"인증(Authentication)은 자신의 신원을 시스템에 증명하는 과정으로, 아이디와 패스워드 입력이 대표적이다."},{"verdict":"오답","why":"계정 관리(Accounting)는 사용자가 어떤 자원을 얼마나 사용했는지 기록하고 추적하는 기능이다."},{"verdict":"오답","why":"권한 부여(Authorization)는 인증된 사용자에게 어떤 작업을 할 수 있는지 권한을 주는 기능이다."},{"verdict":"오답","why":"Aging은 AAA 기능이 아니다. 운영체제에서 오래 기다린 프로세스의 우선순위를 높이는 기법을 에이징(Aging)이라고 한다."}],"keywords":[{"term":"인증(Authentication)","desc":"사용자의 신원을 확인"},{"term":"권한 부여(Authorization)","desc":"인증된 사용자에게 접근 권한 부여"},{"term":"계정 관리(Accounting)","desc":"자원 사용 내역을 기록·추적"},{"term":"AAA","desc":"인증, 권한 부여, 계정 관리를 묶어 부르는 보안 기능"}],"memo":"AAA 순서는 '누구냐(인증) → 뭘 할 수 있냐(권한) → 뭘 했냐(계정 관리)'."}},{"id":"written-2023-3-85","no":85,"unit":"정보시스템 구축 관리","q":"프로젝트에 내재된 위험 요소를 인식하고 그 영향을 분석하여 관리하는 활동으로, 프로젝트의 성공을 위해 위험 요소를 사전에 예측하고 대비하는 모든 기술과 활동을 포함하는 것은?","choices":["Waterfall Model","Work Breakdown Structure","Risk Analysis","Critical Path Method"],"ans":3,"exp":{"concept":"위험 분석(Risk Analysis)은 프로젝트에 숨어 있는 위험 요소를 찾아내고, 그 영향을 분석해 관리하는 활동이다. 위험을 미리 예측하고 대비해 프로젝트를 성공으로 이끄는 것이 목적이다. 위험 식별 → 위험 분석 및 평가 → 위험 관리 계획 → 위험 감시 및 조치 순으로 진행한다.","choices":[{"verdict":"오답","why":"폭포수 모형(Waterfall Model)은 각 단계를 순서대로 진행하는 소프트웨어 생명주기 모형이다."},{"verdict":"오답","why":"작업 분해 구조(WBS, Work Breakdown Structure)는 프로젝트 작업을 계층적으로 잘게 나눈 구조다."},{"verdict":"정답","why":"위험 분석(Risk Analysis)은 프로젝트의 위험 요소를 인식하고 영향을 분석해 관리하는 활동이다."},{"verdict":"오답","why":"임계 경로 기법(CPM, Critical Path Method)은 작업들의 선후 관계를 네트워크로 그려 프로젝트 완료에 필요한 가장 긴 경로를 찾는 일정 관리 기법이다."}],"keywords":[{"term":"위험 분석(Risk Analysis)","desc":"위험 요소를 식별하고 영향을 분석해 관리"},{"term":"위험 관리 절차","desc":"위험 식별 → 위험 분석 및 평가 → 위험 관리 계획 → 위험 감시 및 조치"},{"term":"WBS","desc":"프로젝트 작업을 계층적으로 분해한 구조"},{"term":"CPM","desc":"임계 경로를 찾아 일정을 관리하는 기법"}],"memo":"'위험 요소', '사전 예측'이 나오면 Risk가 들어간 보기를 고른다."}},{"id":"written-2023-3-86","no":86,"unit":"정보시스템 구축 관리","q":"다음 설명에 해당하는 용어로 옳은 것은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>오픈 소스 기반의 분산 컴퓨팅 플랫폼이다.</li><li>일반 PC급 컴퓨터들을 이용해 가상화된 대형 스토리지를 구성한다.</li><li>여러 소스에서 생성된 빅데이터를 효율적으로 저장·처리한다.</li></ul></div>","choices":["맴리스터(Memristor)","포스퀘어(Foursquare)","비컨(Beacon)","하둡(Hadoop)"],"ans":4,"exp":{"concept":"하둡(Hadoop)은 일반 PC급 컴퓨터 여러 대를 묶어 하나의 거대한 저장소와 처리 시스템처럼 쓰게 하는 오픈 소스 분산 컴퓨팅 플랫폼이다. 빅데이터를 저장하는 HDFS와 이를 나눠 처리하는 맵리듀스(MapReduce)가 핵심이다.","choices":[{"verdict":"오답","why":"멤리스터(Memristor)는 메모리(Memory)와 저항(Resistor)의 합성어로, 전류의 흐름 이력을 기억하는 전자 소자다."},{"verdict":"오답","why":"포스퀘어(Foursquare)는 사용자의 위치 정보를 기반으로 한 소셜 네트워크 서비스다."},{"verdict":"오답","why":"비컨(Beacon)은 블루투스 저에너지(BLE)를 이용해 근거리의 스마트 기기에 위치 정보 등을 보내는 기술이다."},{"verdict":"정답","why":"하둡은 일반 PC급 컴퓨터로 가상화된 대형 스토리지를 구성하고 빅데이터를 분산 저장·처리하는 오픈 소스 분산 컴퓨팅 플랫폼이다."}],"keywords":[{"term":"하둡(Hadoop)","desc":"오픈 소스 분산 컴퓨팅 플랫폼, 빅데이터 저장·처리"},{"term":"HDFS","desc":"하둡 분산 파일 시스템"},{"term":"맵리듀스(MapReduce)","desc":"대용량 데이터를 나눠 처리(Map)하고 결과를 합치는(Reduce) 프로그래밍 모델"},{"term":"스쿱(Sqoop)","desc":"하둡과 관계형 데이터베이스 사이에서 데이터를 옮기는 도구"}],"memo":"'오픈 소스 + 분산 + 빅데이터' 세 단어가 같이 나오면 하둡이다."}},{"id":"written-2023-3-87","no":87,"unit":"정보시스템 구축 관리","q":"다음 중 정보 보안의 3대 요소에 속하지 않는 것은?","choices":["기밀성","휘발성","가용성","무결성"],"ans":2,"exp":{"concept":"정보 보안의 3대 요소는 기밀성(Confidentiality), 무결성(Integrity), 가용성(Availability)으로, 앞 글자를 따서 CIA라고 한다. 휘발성은 전원이 꺼지면 데이터가 사라지는 메모리의 성질로 보안 요소가 아니다.","choices":[{"verdict":"오답","why":"기밀성(Confidentiality)은 인가된 사용자만 정보에 접근할 수 있게 하는 보안 요소다."},{"verdict":"정답","why":"휘발성은 전원이 꺼지면 저장된 내용이 사라지는 기억장치(RAM 등)의 성질로, 정보 보안의 3대 요소가 아니다."},{"verdict":"오답","why":"가용성(Availability)은 인가된 사용자가 필요할 때 언제든 정보를 사용할 수 있게 하는 보안 요소다."},{"verdict":"오답","why":"무결성(Integrity)은 인가된 사용자만 정보를 수정할 수 있게 해 정보가 변조되지 않도록 하는 보안 요소다."}],"keywords":[{"term":"기밀성(Confidentiality)","desc":"인가된 사용자만 접근"},{"term":"무결성(Integrity)","desc":"인가된 사용자만 수정, 변조 방지"},{"term":"가용성(Availability)","desc":"필요할 때 언제든 사용 가능"},{"term":"CIA","desc":"보안 3대 요소의 앞 글자"}],"memo":"보안 3요소는 CIA(Confidentiality, Integrity, Availability)."}},{"id":"written-2023-3-88","no":88,"unit":"정보시스템 구축 관리","q":"다음 중 CMMI의 단계에 해당하지 않는 것은?","choices":["관리","반복","초기","정의"],"ans":2,"exp":{"concept":"CMMI(Capability Maturity Model Integration)는 조직의 소프트웨어 개발 능력이 얼마나 성숙했는지 평가하는 모델이다. 성숙도는 초기(Initial) → 관리(Managed) → 정의(Defined) → 정량적 관리(Quantitatively Managed) → 최적화(Optimizing)의 5단계다. '반복'은 CMMI의 단계가 아니다.","choices":[{"verdict":"오답","why":"관리(Managed)는 CMMI 2단계로, 프로젝트별로 기본적인 관리 체계가 갖춰진 단계다."},{"verdict":"정답","why":"반복은 CMMI의 단계가 아니다. 반복(Repeatable)은 CMMI 이전 모델인 SW-CMM에서 2단계를 부르던 이름이며, CMMI에서는 관리(Managed)라고 한다."},{"verdict":"오답","why":"초기(Initial)는 CMMI 1단계로, 정해진 프로세스 없이 개인 역량에 의존하는 단계다."},{"verdict":"오답","why":"정의(Defined)는 CMMI 3단계로, 조직 차원의 표준 프로세스가 정의된 단계다."}],"keywords":[{"term":"1단계 초기(Initial)","desc":"프로세스 없음, 개인 역량에 의존"},{"term":"2단계 관리(Managed)","desc":"프로젝트 단위로 관리"},{"term":"3단계 정의(Defined)","desc":"조직 표준 프로세스 활용"},{"term":"4단계 정량적 관리(Quantitatively Managed)","desc":"프로세스를 수치로 측정·관리"},{"term":"5단계 최적화(Optimizing)","desc":"프로세스를 지속적으로 개선"}],"memo":"CMMI 5단계는 '초관정정최(초기, 관리, 정의, 정량적 관리, 최적화)'."}},{"id":"written-2023-3-89","no":89,"unit":"정보시스템 구축 관리","q":"OSI 7 Layer의 모든 계층 프로토콜과 패킷 내부 콘텐츠를 파악해 침입 시도, 해킹 등을 탐지하고 트래픽을 조정하는 데 쓰이는 패킷 분석 기술은?","choices":["Traffic Distributor","Packet Tree","PLCP(Packet Level Control Processor)","DPI(Deep Packet Inspection)"],"ans":4,"exp":{"concept":"DPI(Deep Packet Inspection)는 패킷의 헤더뿐 아니라 실제 내용(페이로드)까지 깊이 들여다보는 패킷 분석 기술이다. OSI 7계층 전체의 프로토콜과 콘텐츠를 분석해 침입 시도, 해킹, 악성 코드를 탐지하고 트래픽을 조절하는 데 쓴다.","choices":[{"verdict":"오답","why":"Traffic Distributor는 출제 범위의 표준 패킷 분석 기술 용어가 아니다."},{"verdict":"오답","why":"Packet Tree는 출제 범위의 표준 패킷 분석 기술 용어가 아니다."},{"verdict":"오답","why":"보기의 PLCP(Packet Level Control Processor)는 출제 범위의 표준 패킷 분석 기술 용어가 아니다."},{"verdict":"정답","why":"DPI는 OSI 7계층 전체의 프로토콜과 패킷 내부 콘텐츠까지 분석해 침입·해킹을 탐지하고 트래픽을 조정하는 기술이다."}],"keywords":[{"term":"DPI(Deep Packet Inspection)","desc":"패킷의 내용까지 깊이 분석하는 기술"},{"term":"페이로드(Payload)","desc":"패킷에서 헤더를 뺀 실제 데이터 부분"},{"term":"IDS(Intrusion Detection System)","desc":"침입을 탐지하는 시스템"},{"term":"IPS(Intrusion Prevention System)","desc":"침입을 탐지하고 차단까지 하는 시스템"}],"memo":"Deep(깊이) + Packet + Inspection(검사) = 패킷 속까지 들여다보는 검사."}},{"id":"written-2023-3-90","no":90,"unit":"정보시스템 구축 관리","q":"COCOMO Model 가운데 기관 내부에서 개발된 중·소 규모의 소프트웨어로서 일괄 자료 처리, 과학기술 계산용, 비즈니스 자료 처리용 등 5만 라인 이하의 소프트웨어를 개발하는 유형은 무엇인가?","choices":["Embeded","Semi-Detached","Semi-Embeded","Organic"],"ans":4,"exp":{"concept":"COCOMO는 소스 코드 라인 수(LOC)를 바탕으로 개발 비용을 추정하는 모델이다. 소프트웨어 유형을 규모와 복잡도에 따라 조직형(Organic), 반분리형(Semi-Detached), 내장형(Embedded) 3가지로 나눈다. 조직형은 기관 내부에서 개발하는 5만 라인 이하의 중·소규모 소프트웨어다.","choices":[{"verdict":"오답","why":"내장형(Embedded)은 초대형 규모의 트랜잭션 처리 시스템이나 운영체제 등 30만 라인 이상의 소프트웨어를 개발하는 유형이다."},{"verdict":"오답","why":"반분리형(Semi-Detached)은 조직형과 내장형의 중간형으로, 트랜잭션 처리 시스템, 운영체제, 데이터베이스 관리 시스템 등 30만 라인 이하의 소프트웨어를 개발하는 유형이다."},{"verdict":"오답","why":"Semi-Embedded라는 유형은 COCOMO에 없다."},{"verdict":"정답","why":"조직형(Organic)은 기관 내부에서 개발되는 5만 라인 이하의 중·소규모 소프트웨어로, 일괄 자료 처리, 과학 기술 계산용, 비즈니스 자료 처리용 등이 해당한다."}],"keywords":[{"term":"조직형(Organic)","desc":"5만(50KDSI) 라인 이하, 중·소규모, 사무 처리·업무용"},{"term":"반분리형(Semi-Detached)","desc":"30만(300KDSI) 라인 이하, 트랜잭션 처리 시스템·DBMS 등"},{"term":"내장형(Embedded)","desc":"30만(300KDSI) 라인 이상, 초대형 트랜잭션 처리 시스템·운영체제 등"},{"term":"COCOMO","desc":"보헴(Boehm)이 제안한 LOC 기반 비용 산정 모델"}],"memo":"COCOMO 유형은 '조반내(조직형 → 반분리형 → 내장형)' 순으로 규모가 커진다."}},{"id":"written-2023-3-91","no":91,"unit":"정보시스템 구축 관리","q":"IP 또는 ICMP의 특성을 악용해 특정 사이트로 데이터를 집중적으로 보내 네트워크나 시스템의 상태를 불능으로 만드는 공격 방법은?","choices":["Qshing","TearDrop","Smurfing","Smishing"],"ans":3,"exp":{"concept":"스머핑(Smurfing)은 출발지 주소를 공격 대상의 IP로 위조한 ICMP Echo Request(ping) 패킷을 네트워크 전체(브로드캐스트 주소)로 보내는 공격이다. 그러면 네트워크의 모든 호스트가 공격 대상에게 응답을 보내 대상이 응답 패킷에 파묻혀 마비된다. IP와 ICMP의 특성을 악용한 대표적인 DoS 공격이다.","choices":[{"verdict":"오답","why":"큐싱(Qshing)은 QR 코드와 피싱(Phishing)의 합성어로, QR 코드를 이용해 악성 사이트로 유도하는 공격이다."},{"verdict":"오답","why":"티어드롭(TearDrop)은 IP 패킷을 조각낼 때 조각의 위치를 나타내는 오프셋(Fragment Offset) 값을 조작해, 재조립 과정에서 오류를 일으키는 공격이다."},{"verdict":"정답","why":"스머핑은 IP와 ICMP의 특성을 악용해, 위조한 ICMP 패킷을 브로드캐스트로 보내 대량의 응답이 특정 사이트로 집중되게 함으로써 네트워크를 불능 상태로 만드는 공격이다."},{"verdict":"오답","why":"스미싱(Smishing)은 SMS(문자 메시지)와 피싱의 합성어로, 문자 메시지로 악성 링크를 보내 개인정보를 빼내는 공격이다."}],"keywords":[{"term":"스머핑(Smurfing)","desc":"위조한 ICMP 패킷을 브로드캐스트해 응답을 대상에게 집중시키는 DoS 공격"},{"term":"티어드롭(TearDrop)","desc":"IP 단편화 오프셋을 조작해 재조립 오류를 일으키는 공격"},{"term":"핑 오브 데스(Ping of Death)","desc":"허용 크기를 넘는 ICMP 패킷을 보내는 공격"},{"term":"랜드 어택(Land Attack)","desc":"출발지와 목적지 IP를 같게 만들어 보내는 공격"}],"memo":"'ICMP + 집중적으로 보내 불능'은 스머핑. 오프셋 조작은 티어드롭, 문자는 스미싱, QR은 큐싱."}},{"id":"written-2023-3-92","no":92,"unit":"정보시스템 구축 관리","q":"공개키 암호화 기법에서 소인수 분해 문제를 바탕으로 널리 쓰이는 암호 알고리즘 기법은?","choices":["RSA","PKI","ECC","PRM"],"ans":1,"exp":{"concept":"RSA(Rivest-Shamir-Adleman)는 큰 두 소수를 곱하기는 쉽지만, 곱한 결과를 다시 소인수분해하기는 매우 어렵다는 점을 이용한 공개키 암호 알고리즘이다. 이름은 제안자인 리베스트(Rivest), 샤미르(Shamir), 애들먼(Adleman)의 앞 글자를 딴 것이다.","choices":[{"verdict":"정답","why":"RSA는 큰 수의 소인수분해가 어렵다는 점에 기반한 대표적인 공개키 암호 알고리즘이다."},{"verdict":"오답","why":"PKI(Public Key Infrastructure, 공개키 기반 구조)는 인증서를 발급·관리해 공개키를 안전하게 쓰게 하는 기반 체계로, 암호 알고리즘이 아니다."},{"verdict":"오답","why":"ECC(Elliptic Curve Cryptography)는 소인수분해가 아니라 타원 곡선 위의 이산대수 문제의 어려움에 기반한 공개키 암호다."},{"verdict":"오답","why":"PRM은 출제 범위의 표준 암호 알고리즘이 아니다."}],"keywords":[{"term":"RSA","desc":"소인수분해 문제 기반 공개키 암호"},{"term":"ECC","desc":"타원 곡선 이산대수 문제 기반 공개키 암호, 짧은 키로 높은 보안"},{"term":"ElGamal","desc":"이산대수 문제 기반 공개키 암호"},{"term":"PKI","desc":"인증서로 공개키를 관리하는 기반 구조"}],"memo":"RSA는 '소인수분해', ECC는 '타원 곡선', ElGamal은 '이산대수'."}},{"id":"written-2023-3-93","no":93,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발 프레임워크를 적용했을 때 기대되는 효과와 거리가 먼 것은?","choices":["개발 용이성","품질 보증","변경 용이성","시스템 복잡도 증가"],"ans":4,"exp":{"concept":"소프트웨어 개발 프레임워크는 개발에 필요한 기본 구조와 공통 기능을 미리 만들어 둔 뼈대다. 이를 쓰면 개발이 쉬워지고, 정해진 구조 덕분에 품질이 일정해지며, 변경과 유지보수도 쉬워진다. 그래서 시스템 복잡도는 오히려 줄어든다.","choices":[{"verdict":"오답","why":"공통 기능과 구조가 이미 있어 개발이 쉬워진다(개발 용이성). 기대 효과에 해당한다."},{"verdict":"오답","why":"검증된 구조와 표준을 따르므로 품질이 보증된다. 기대 효과에 해당한다."},{"verdict":"오답","why":"구조가 정형화되어 있어 변경이 쉽다(변경 용이성). 기대 효과에 해당한다."},{"verdict":"정답","why":"프레임워크는 표준화된 구조로 시스템 복잡도를 줄여 준다. 복잡도 증가는 기대 효과가 아니다."}],"keywords":[{"term":"프레임워크(Framework)","desc":"개발에 필요한 기본 구조와 공통 기능을 제공하는 반제품 형태의 뼈대"},{"term":"기대 효과","desc":"개발 용이성, 품질 보증, 변경 용이성, 유지보수 용이성, 재사용성, 복잡도 감소"},{"term":"제어의 역전(IoC)","desc":"프로그램 흐름을 개발자 코드가 아니라 프레임워크가 제어하는 것"},{"term":"라이브러리","desc":"개발자가 필요할 때 호출해 쓰는 기능 모음"}],"memo":"'증가'라는 말이 기대 효과 보기에 섞여 있으면 의심한다. 프레임워크는 복잡도를 줄인다."}},{"id":"written-2023-3-94","no":94,"unit":"정보시스템 구축 관리","q":"기존 무선 랜의 한계를 극복하고자 등장하였으며, 대규모 디바이스의 네트워크 생성에 최적화되어 차세대 이동통신, 홈네트워킹, 공공 안전 등 특수목적에 활용되는 새로운 방식의 네트워크 기술을 의미하는 것은?","choices":["Local Area Network","Virtual Private Network","Software Defined Perimeter","Mesh Network"],"ans":4,"exp":{"concept":"메시 네트워크(Mesh Network)는 여러 기기(노드)가 그물처럼 서로 직접 연결되어 데이터를 주고받는 네트워크다. 한 경로가 끊겨도 다른 경로로 돌아갈 수 있어 안정적이고, 대규모 기기 연결에 알맞다. 기존 무선 랜의 한계를 극복하기 위해 등장했으며 차세대 이동통신, 홈 네트워킹, 공공 안전 등 특수 목적에 쓰인다.","choices":[{"verdict":"오답","why":"LAN(Local Area Network)은 건물이나 학교 같은 좁은 지역을 연결하는 근거리 통신망이다."},{"verdict":"오답","why":"VPN(Virtual Private Network)은 공중망 위에 암호화된 터널을 만들어 사설망처럼 쓰는 가상 사설망이다."},{"verdict":"오답","why":"SDP(Software Defined Perimeter)는 신원이 확인된 사용자와 기기에만 접근을 허용하도록 네트워크 경계를 소프트웨어로 구성하는 보안 기술이다."},{"verdict":"정답","why":"메시 네트워크는 대규모 디바이스의 네트워크 생성에 최적화된 그물망 형태의 네트워크로, 차세대 이동통신, 홈 네트워킹, 공공 안전 등 특수 목적에 쓰인다."}],"keywords":[{"term":"메시 네트워크(Mesh Network)","desc":"노드가 그물처럼 연결된 대규모 디바이스용 네트워크"},{"term":"VPN","desc":"공중망에서 암호화 터널로 사설망처럼 통신"},{"term":"SDP(Software Defined Perimeter)","desc":"인증된 사용자와 기기에만 접근을 허용하는 소프트웨어 정의 경계"},{"term":"애드 혹 네트워크(Ad-hoc Network)","desc":"기지국 없이 이동 단말끼리 구성하는 네트워크"}],"memo":"Mesh는 '그물'. 그물처럼 많은 기기를 촘촘히 잇는 네트워크다."}},{"id":"written-2023-3-95","no":95,"unit":"정보시스템 구축 관리","q":"COCOMO(Constructive Cost Model) 모형의 특징에 해당하지 않는 것은?","choices":["비교적 작은 규모의 프로젝트 기록을 통계 분석하여 얻은 결과를 반영한 모델로서 중소 규모 소프트웨어 프로젝트 비용 추정에 적합하다.","프로젝트 완성에 필요한 Man-Month로 산정 결과를 표현할 수 있다.","보헴(Boehm)이 제안하였으며 원시 코드 라인 수에 의한 비용 산정 기법이다.","프로젝트 개발 유형에 따라 object, dynamic, function의 3가지 모드로 나눈다."],"ans":4,"exp":{"concept":"COCOMO(Constructive Cost Model)는 보헴(Boehm)이 제안한, 소스 코드 라인 수(LOC)로 비용을 추정하는 모델이다. 결과는 투입 인원과 기간을 곱한 Man-Month(MM)로 나타내며, 소프트웨어 유형을 조직형(Organic), 반분리형(Semi-Detached), 내장형(Embedded)으로 나눈다. object, dynamic, function은 럼바우 분석 기법의 3가지 모델링이다.","choices":[{"verdict":"오답","why":"비교적 작은 규모의 프로젝트 기록을 통계 분석해 만든 모델로 중·소 규모 프로젝트 비용 추정에 적합하다. COCOMO의 특징에 해당한다."},{"verdict":"오답","why":"산정 결과를 프로젝트 완성에 필요한 Man-Month로 나타낸다. COCOMO의 특징에 해당한다."},{"verdict":"오답","why":"보헴이 제안했고 원시 코드 라인 수를 기반으로 비용을 산정한다. COCOMO의 특징에 해당한다."},{"verdict":"정답","why":"COCOMO의 개발 유형은 조직형(Organic), 반분리형(Semi-Detached), 내장형(Embedded)이다. object, dynamic, function은 럼바우 객체지향 분석의 객체, 동적, 기능 모델링이다."}],"keywords":[{"term":"COCOMO","desc":"보헴이 제안한 LOC 기반 비용 산정 모델"},{"term":"Man-Month(MM)","desc":"한 사람이 한 달 동안 하는 작업량 단위"},{"term":"COCOMO 유형","desc":"조직형(Organic), 반분리형(Semi-Detached), 내장형(Embedded)"},{"term":"COCOMO 모델 종류","desc":"기본형(Basic), 중간형(Intermediate), 발전형(Detailed)"}],"memo":"COCOMO 유형은 'Organic, Semi-Detached, Embedded'. object, dynamic, function은 럼바우와 섞어 낸 함정이다."}},{"id":"written-2023-3-96","no":96,"unit":"정보시스템 구축 관리","q":"물리적 위협으로 인해 발생하는 문제에 해당되지 않는 것은?","choices":["하드웨어 파손이나 고장으로 인한 장애","방화, 테러로 하드웨어와 기록장치를 물리적으로 파괴하는 행위","화재, 홍수 등 천재지변에 의한 위협","방화벽 설정을 잘못 조작하여 발생하는 네트워크, 서버 보안 위협"],"ans":4,"exp":{"concept":"물리적 위협은 하드웨어, 건물, 기록 장치 같은 눈에 보이는 실체에 직접 피해를 주는 위협이다. 기계 고장, 화재나 홍수 같은 자연재해, 방화와 테러에 의한 파괴가 해당한다. 방화벽 설정을 잘못한 것은 소프트웨어 설정 문제이므로 기술적(논리적) 위협이다.","choices":[{"verdict":"오답","why":"하드웨어 파손이나 고장으로 인한 장애는 물리적 위협이다."},{"verdict":"오답","why":"방화, 테러로 하드웨어와 기록 장치를 파괴하는 행위는 물리적 위협이다."},{"verdict":"오답","why":"화재, 홍수 등 천재지변에 의한 위협은 물리적 위협이다."},{"verdict":"정답","why":"방화벽 설정을 잘못 조작해 생기는 보안 위협은 설정과 운영의 문제로, 물리적 위협이 아니라 기술적(논리적) 위협이다."}],"keywords":[{"term":"물리적 위협","desc":"하드웨어·시설에 직접 피해를 주는 위협, 예: 고장, 재해, 파괴"},{"term":"기술적 위협","desc":"해킹, 악성 코드, 잘못된 보안 설정 등 시스템과 네트워크를 통한 위협"},{"term":"방화벽(Firewall)","desc":"내부 네트워크와 외부 네트워크 사이의 트래픽을 통제하는 보안 시스템"},{"term":"물리적 보안","desc":"출입 통제, CCTV, 잠금 장치 등으로 시설과 장비를 보호"}],"memo":"'방화(불을 지르는 것)'는 물리적, '방화벽(Firewall)'은 기술적. 비슷한 글자를 섞은 함정이다."}},{"id":"written-2023-3-97","no":97,"unit":"정보시스템 구축 관리","q":"소프트웨어 생명주기 모형 가운데 프로토타입 모형의 장점으로 볼 수 없는 것은?","choices":["최종 결과물이 완성되기 전에 의뢰자가 최종결과물의 일부 혹은 모형을 확인할 수 있다.","개발과정에서 사용자의 요구가 충분히 반영된다.","단기간에 제작하는 것이 목적이므로 비효율적인 언어나 알고리즘이 사용될 수 있다.","의뢰자와 개발자 모두에게 공동의 참조 모델이 제공된다."],"ans":3,"exp":{"concept":"프로토타입 모형은 실제 시스템을 만들기 전에 견본(시제품)을 먼저 만들어 사용자에게 보여 주고 요구사항을 다듬는 모형이다. 사용자 요구를 잘 반영할 수 있지만, 빨리 만드는 데 집중하다 보니 비효율적인 언어나 알고리즘이 쓰일 수 있다는 단점이 있다.","choices":[{"verdict":"오답","why":"최종 결과물이 나오기 전에 의뢰자가 일부나 모형을 미리 확인할 수 있는 것은 장점이다."},{"verdict":"오답","why":"견본을 보며 의견을 주고받으므로 사용자 요구가 충분히 반영되는 것은 장점이다."},{"verdict":"정답","why":"단기간 제작에 집중하느라 비효율적인 언어나 알고리즘이 사용될 수 있다는 것은 프로토타입 모형의 단점이다."},{"verdict":"오답","why":"견본이 의뢰자와 개발자 모두의 공통 참조 모델이 되는 것은 장점이다."}],"keywords":[{"term":"프로토타입 모형(Prototype Model)","desc":"견본을 만들어 요구사항을 확인·보완하는 모형"},{"term":"폭포수 모형(Waterfall Model)","desc":"단계를 순차적으로 진행하는 고전적 모형"},{"term":"나선형 모형(Spiral Model)","desc":"반복하며 위험 분석을 하는 모형"},{"term":"반복적 모형(Iterative Model)","desc":"구축 대상을 나누어 병렬 개발 후 통합하거나 반복해 개발하는 모형"}],"memo":"'비효율적', '~될 수 있다' 같은 부정적 표현이 장점 문제에 나오면 그것이 답이다."}},{"id":"written-2023-3-98","no":98,"unit":"정보시스템 구축 관리","q":"취약점 관리를 위한 응용 프로그램의 보안 설정과 가장 거리가 먼 것은 무엇인가?","choices":["운영체제 정보 수집 제한","운영체제 접근 제한","실행 프로세스의 권한 설정","서버 관리실의 출입 통제"],"ans":4,"exp":{"concept":"응용 프로그램과 서버의 보안 설정은 소프트웨어적으로 접근과 권한을 통제하는 것이다. 운영체제 정보 노출을 막고, 운영체제 접근을 제한하고, 실행 프로세스의 권한을 최소로 설정하는 것이 해당한다. 서버실 출입 통제는 사람의 출입을 막는 물리적 보안이다.","choices":[{"verdict":"오답","why":"운영체제 종류나 버전 같은 정보가 외부에 노출되지 않게 제한하는 것은 응용 프로그램 보안 설정에 해당한다."},{"verdict":"오답","why":"허가되지 않은 사용자가 운영체제에 접근하지 못하게 제한하는 것은 보안 설정에 해당한다."},{"verdict":"오답","why":"실행 프로세스에 필요한 최소한의 권한만 주도록 설정하는 것은 보안 설정에 해당한다."},{"verdict":"정답","why":"서버 관리실 출입 통제는 물리적 보안 대책으로, 응용 프로그램의 보안 설정이 아니다."}],"keywords":[{"term":"취약점 관리","desc":"시스템의 보안 약점을 찾아 점검하고 보완하는 활동"},{"term":"최소 권한의 원칙","desc":"작업에 꼭 필요한 최소한의 권한만 부여"},{"term":"물리적 보안","desc":"출입 통제, 잠금 장치 등으로 시설을 보호"},{"term":"정보 수집 제한","desc":"배너나 오류 메시지로 시스템 정보가 노출되지 않게 함"}],"memo":"'응용 프로그램' 보안 설정 문제에서 사람·장소를 막는 보기는 물리적 보안이라 답이 된다."}},{"id":"written-2023-3-99","no":99,"unit":"정보시스템 구축 관리","q":"다음이 설명하는 것은 무엇인가?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>광채널 스위치의 이점인 고속 전송, 장거리 연결 및 멀티 프로토콜 기능을 네트워크상에서 활용</li><li>서로 다른 운영체제를 가진 여러 기종이 네트워크상에서 동일 저장장치의 데이터를 공유하도록 함으로써, 여러 개의 저장장치나 백업 장비를 단일화한 시스템</li></ul></div>","choices":["SAN","NAC","MBR","NIC"],"ans":1,"exp":{"concept":"SAN(Storage Area Network)은 서버와 저장 장치를 광채널(Fibre Channel) 스위치로 연결한 전용 고속 네트워크다. 서로 다른 운영체제를 쓰는 여러 서버가 같은 저장 장치의 데이터를 공유할 수 있어, 흩어져 있던 저장 장치와 백업 장비를 하나로 통합할 수 있다.","choices":[{"verdict":"정답","why":"SAN은 광채널 스위치의 고속 전송, 장거리 연결, 멀티 프로토콜 기능을 활용해 여러 기종의 서버가 저장 장치를 공유하게 하는 저장 장치 전용 네트워크다."},{"verdict":"오답","why":"NAC(Network Access Control)는 네트워크에 접속하는 단말의 보안 상태를 검사해 접근을 통제하는 기술이다."},{"verdict":"오답","why":"MBR(Master Boot Record)은 디스크 맨 앞에 있는 부팅 정보와 파티션 정보 영역이다."},{"verdict":"오답","why":"NIC(Network Interface Card)는 컴퓨터를 네트워크에 연결하는 네트워크 카드다."}],"keywords":[{"term":"SAN(Storage Area Network)","desc":"광채널 스위치로 서버와 저장 장치를 연결한 전용 네트워크"},{"term":"NAS(Network Attached Storage)","desc":"일반 네트워크(LAN)에 연결해 파일 단위로 공유하는 저장 장치"},{"term":"DAS(Direct Attached Storage)","desc":"서버에 저장 장치를 직접 연결하는 방식"},{"term":"광채널(Fibre Channel)","desc":"저장 장치 연결용 고속 네트워크 기술"}],"memo":"'광채널 스위치'가 나오면 SAN. 저장 방식은 DAS(직접), NAS(네트워크 파일 공유), SAN(전용 네트워크)."}},{"id":"written-2023-3-100","no":100,"unit":"정보시스템 구축 관리","q":"암호화 키와 복호화 키가 서로 같은 암호화 알고리즘은?","choices":["RSA","AES","ECC","DSA"],"ans":2,"exp":{"concept":"암호화 키와 복호화 키가 같은 방식을 대칭키(비밀키) 암호라고 하고, 두 키가 다른 방식을 비대칭키(공개키) 암호라고 한다. AES, DES, SEED, ARIA 등이 대칭키 암호이고, RSA, ECC, DSA 등은 공개키 방식이다.","choices":[{"verdict":"오답","why":"RSA는 공개키로 암호화하고 개인키로 복호화하는 공개키(비대칭키) 암호 알고리즘이다."},{"verdict":"정답","why":"AES(Advanced Encryption Standard)는 암호화와 복호화에 같은 키를 쓰는 대칭키 블록 암호 알고리즘이다."},{"verdict":"오답","why":"ECC는 타원 곡선을 이용한 공개키(비대칭키) 암호 알고리즘이다."},{"verdict":"오답","why":"DSA(Digital Signature Algorithm)는 이산대수 문제에 기반한 공개키 방식의 전자 서명 알고리즘이다."}],"keywords":[{"term":"대칭키 암호","desc":"암호화 키 = 복호화 키. 예: DES, AES, SEED, ARIA, IDEA"},{"term":"비대칭키(공개키) 암호","desc":"공개키로 암호화, 개인키로 복호화. 예: RSA, ECC, ElGamal"},{"term":"AES","desc":"DES를 대체한 미국 표준 대칭키 블록 암호, 128비트 블록"},{"term":"DSA","desc":"이산대수 기반 전자 서명 알고리즘"}],"memo":"대칭키는 이름이 '표준(Standard)'이나 국산(SEED, ARIA)인 것이 많고, 공개키는 RSA·ECC·ElGamal·DSA를 따로 외운다."}}]};